window.POEM_DB=window.POEM_DB||{};POEM_DB["song_021"]={"n":"释居简","dyn":"宋","poems":[{"t":"杨园四题 其四","f":"七言律诗","c":["直从平地矗崔嵬，南向群山斗次来。","尽此半春留客醉，莫愁一日不花开。","水从绿野前头绕，竹向芳菲缺处栽。","目送断鸿天外去，问它更是几时回。"]},{"t":"八月大风大水 其一","f":"七言绝句","c":["十日溪头鹢退飞，相逢那暇问雄雌。","不如二月春风好，草木无情亦去思。"]},{"t":"白衣文简净人呈度牒","f":"七言绝句","c":["袖出天书喜动容，从来汗马不言功。","长鞭未举追风去，回首相寻异类中。"]},{"t":"白荷花","f":"七言绝句","c":["数亩澄漪不用耕，移根玉井不曾耘。","羽衣何处霓裳遍，翠盖参差踏水云。"]},{"t":"白莲雨后渐衰","f":"七言绝句","c":["晓池芳柄袅残馨，褪雨攲风鹭委翎。","碧展一奁秋练练，似怜玉色镜中零。"]},{"t":"安藏主","f":"七言绝句","c":["尽教佛性自瞒顸，终日如愚已自谩。","不是较渠三十里，平生穿凿不相干。"]},{"t":"庵居即事","f":"七言绝句","c":["欲过东家怕渡桥，欲题黄叶怕随潮。","经旬不踏门前路，陡顿苍苔绿色饶。"]},{"t":"矮僧求颂","f":"七言绝句","c":["见说矮人多计较，大家知道不曾藏。","只将丈六金襕挂，莫与诸方论短长。"]},{"t":"灞桥风雪图","f":"七言绝句","c":["桥滑驴僵噤不嘶，诗穷弗死反穷诗。","华山也是吟疆土，更欲烦君写倒骑。"]},{"t":"白马金砂洞","f":"七言律诗","c":["准拟朝餐洞口霞，更穷泓碧涨桃花。","可曾石罅潴成玉，多是金边拣得沙。","符说有灵寻汉篆，人因鉴止见胡麻。","依稀似入天台路，不属刘家与阮家。"]},{"t":"白鸡谢静讲师湖州旧馆","f":"五言律诗","c":["素羽剪零云，冠裁辰锦新。","德如潮有信，雄压牝无晨。","物化寤非蝶，蚁酣惊代邻。","莫教风雨暝，缄口却羞人。"]},{"t":"八月大风大水 其二","f":"七言绝句","c":["零落茅茨水半扉，媪颦翁蹙小儿啼。","老鸡不管丰凶事，独自将雏树上栖。"]},{"t":"八月廿七风雨大浸","f":"五言古诗","c":["左扼飞廉吭，右拊巽二背。","谓云如何其，坐使六鹢退。","亦有司雨工，絷如系单于。","不卷油然云，自欲干剪屠。","乡来不鸣条，块亦不曾破。","卿云千点明，华月半天堕。","衮衣徂东山，拔木仍偃禾。","至今东山诗，千载犹咏歌。","悠然启金縢，风反雨亦止。","是中果何书，顷刻变天纪。","流言久弗作，狐亦不复疑。","至诚动真宰，风雨胡不知。","风雨不我以，我稼已堕水。","不知十日淫，滴碎田父心。"]},{"t":"白苧歌","f":"五言古诗","c":["经纱才上机，梭飞玉攕攕。","怕君寻春迟，落机宽裁衫。","春心乱如蓬，冉冉随春霏。","芳径晓沾露，软尘红上衣。","归来恨尘污，湔衣浣纱处。","难湔芳露痕，易湔衣上尘。"]},{"t":"白藕花","f":"五言律诗","c":["一楮三年工，欲赋无三都。","剪作千叶芳，出水渊不枯。","照影秋湛染，摇柄春敷腴。","夜老勺华月，侧此华玉壶。"]},{"t":"白藕花寄袁状元仓使","f":"五言律诗","c":["澄练彻山脉，玉透山池沙。","老火奋残烁，凛姿燉不瑕。","方方秋一奁，弹压红万葩。","安得濂溪叟，来赋东林花。"]},{"t":"白蘋洲新楼曰溪山伟观","f":"七言古诗","c":["溪头烟煖蘋花春，岂独满渚亦满汀。","春城绮绣艳溪曲，柔玉掺掺歌采蘋。","采采芳鲜日将暮，玉盌琼盂旋分贮。","水晶阙冷禁城宽，兰棹夷犹缓归去。","乡来小亭横水浒，雨震风凌日榛莽。","山鬼啸梁猿啸渚，寂寞风烟向谁诉。","仙槎忽从银浦来，吟疆开拓搜吟才。","眼前有句未暇著，只著画楼临水开。","一双浮图笔插架，层级高低与楼亚。","从来天巧不曾藏，纷纷俗眼空茫羊。","赋此须还造楼手，大苏小杜相先后。","柳恽才华更有馀，那堪一等爱楼居。"]},{"t":"哀三城","f":"七言古诗","c":["岁逢虎牛祸折萌，荡荡蜀道犹可评。","嗾奸反正善其计，振槁拉枯徒尔勤。","初虽覆杯可扑灭，终焉决海难为平。","智人三尺眼前暗，明玉一玷磨弗晶。","因仍扰扰不知了，残金欲灺连鞑人。","武功夙著冲与寔，貂蝉贵欲兜牟成。","孽成孤凤鸟不度，守有可死生无因。","两公气节固相类，又类射虎飞将军。","西和寅仲出儒素，开禧总饷先垂名。","太丘是父有是子，冲楼跨灶前无伦。","话头讲明有定见，不与奸谄相因循。","犬戎日众我日寡，貔貅乍屈还乍信。","贺兰饱鲜方醉醇，啮指不雠南霁云。","恸哭秦庭不肯援，有严玉帐无分兵。","借令空弮可持满，飞镝已尽风中鸣。","三城父兄一时陷，况复骨肉怀亲亲。","有生必死死有所，此死可羞尸素群。","矜韬衒略谩蠢蠢，妒功嫉效徒逡逡。","幸灾之迹弗容掩，不掉之尾何足云。","乡来益昌倡大义，阿源流芳千载荣。","胜天倘可恃人众，公道莫于行路听。","后先忠节贯日星，野史孰愈良史真。"]},{"t":"按曲图","f":"七言绝句","c":["八茧蚕抽独茧丝，舞衣嫌重要纤絺。","君王自按霓裳曲，直到坡前驻马时。"]},{"t":"咄庵","f":"词","c":["咄地一下，好肉剜疮。","更安名字，雪上加霜。"]},{"t":"偈颂一百三十三首 其七十二","f":"词","c":["日可冷，月可热，众魔不能坏真说。","且道如何是真说，三人證龟，定不是鳖。"]},{"t":"偈颂一百三十三首 其一○四","f":"词","c":["诸佛不出世，四十九年说。","祖师不西来，少林有妙诀。","是假易除，是真难灭。"]},{"t":"孤山行","f":"七言古诗","c":["盛时考槃古逸民，湖山草木咸知名。","至今八篇烂古锦，岂特五字如长城。","长驱万骑到其下，束手按甲循墙行。","大邦维翰蔽骚雅，遐冲既折犹精神。","抗衡剧孟一敌国，弹压西子孤山春。","死诸葛走生仲达，送修靖邀陶渊明。","聚蚊莫及怒雷迅，老瓦不乱黄钟鸣。","清弹岂为赏音废，自芳更问林扉扃。","鸥盟未冷浪拍拍，弋者何慕鸿冥冥。","水流山空鹤态度，冰枯雪寒梅弟兄。","梅当成实自调鼎，鹤既生子仍姓丁。","乡来偶同赋招隐，老去亦各相忘形。","故庐夜夜月如昼，少微耿耿天无云。","千金傥可市骏骨，万古适足空凡群。","百身可赎但虚语，九原唤起知无因。","为公满酌井花水，酹一抔土公应闻。"]},{"t":"塘淫","f":"五言古诗","c":["苍官百夫雄，盘错千仞冈。","铁干紫尤劲，铜柯青更刚。","屡吞霜雪敌，弗受斤斧戕。","支厦不为柱，跨壑犹飞梁。","胡为在泥滓，断岸繄关防。","岂伊坚贞姿，泥滓永相望。","中分枵其中，吻合相抵当。","彼巧事穿凿，我方信行藏。","惟其司出内，秉彝德之常。","谨口饱涵畜，与时相抑扬。","持满岂无道，损馀端有方。","尾闾小溟渤，砥柱回污潢。","瞥尔手翻覆，枯涸随汪洋。","叔度万顷陂，未足与较量。","匠氏弗遇郢，才不登俊良。","藐然用其小，约水不得洚。","有若古豪隽，落落吞湖江。","遭时发所蕴，利泽何其厖。","时哉倘不逢，蕙帐云雾窗。","独善与兼善，一辙元非双。","任大岂遗小，养浩惟能降。","对此一感慨，勿谓吾言哤。"]},{"t":"檄菖蒲","f":"五言古诗","c":["陶器承昆珉，猎猎散绿丝。","饮以一杯水，卒岁长如斯。","露叶矗锋锷，霜根蟠崄巇。","昌阳欲论功，十驾不得追。","松柏脚踏土，并驱仍背驰。","寒苦我所安，泉石皆闻知。","岂意泉石间，得此偿心期。","澡濯冀怀新，疏剪贵适宜。","芳洁日以薄，潜逐炎凉移。","谓我水太清，汝便清涟漪。","抑我水太浑，古井非污池。","孤根要特立，晚节须坚持。","贞姿或不返，终当怨尤谁。","春葩与秋芗，擅美固有时。","西风一摇落，不死将安之。","亦足观物化，亦足为箴规。"]},{"t":"次宫讲于素斋韵为别 其一","f":"七言律诗","c":["凫短何曾计鹤长，从他踽踽复凉凉。","马归塞上元非失，弓在人间岂是亡。","旋别薰莸充子佩，剩栽红白课蜂房。","到家趁得梅花在，分遣飞来数点香。"]},{"t":"次宫讲于素斋韵为别 其二","f":"七言律诗","c":["无言桃李各成春，造化番腾巧入神。","佳境骎骎逢蔗尾，苦心隐隐饫猩唇。","蠖虽善屈难忘直，虹岂长蟠不得伸。","一日百畦机事了，区区亦有汉阴人。"]},{"t":"正月初九日客舍","f":"五言律诗","c":["水冻冰连底，山疑雪满颠。","恰才如旧腊，全不似新年。","绵折何曾暖，柴生只拥烟。","较他山店雨，枉自怨秋天。"]},{"t":"上钱昭文","f":"五言古诗","c":["拄天有佳木，青跨云沉沉。","不知几何高，四海分清阴。","悠然响虚籁，万象寂若瘖。","寒则为阳和，盎盎春昼深。","穆若吹清泠，六月消烦衿。","烈风益遒劲，厚地盘崎嵚。","浓翠出云雨，大旱徯作霖。","巍巍架明堂，枝干端可寻。","上有孤凤凰，下有众羽禽。","和乐声成文，戛击韶濩音。","大雅得指归，一洗郑卫淫。","向来艰难际，凡才空满林。","天风一披拂，寸碧开遥岑。","遂使化弦改，人命蚁出燖。","大哉德曰生，抑见天地心。","悠悠江海人，蜀道扪井参。","怀土如仲宣，破囊无一簪。","回首白玉霄，欲往勇不禁。","区区竟何有，有句如惜金。","金亦不足惜，铸作颂与箴。"]},{"t":"早课","f":"七言绝句","c":["井花嫩煮熨梅花，先酌芳甘注佛茶。","冷淡工夫相次了，却留窗日看横斜。"]},{"t":"水仙","f":"七言律诗","c":["矮丛傍砌小成阴，冻彻敷腴谢水沉。","细著鲜风扶弱干，剩将零露酌芳心。","华裾冉冉低青绶，柔玉棱棱衬嫩金。","弱水绕山三万里，断魂长记碧萧森。"]},{"t":"和六一居士守汝阴禁相似物赋雪","f":"七言古诗","c":["涟漪碎剪成新萼，廉纤带雨尤轻薄。","人间但见巧番腾，天上不知谁制作。","九地瑕疵都粉饰，重云揞塞难恢廓。","晓光夺目增眩转，夜色侵灯尤闪烁。","康庄充斥去无路，老干压低摇不落。","寒棱冻得水生皮，气艳冷欺裘拥貉。","可胜思苦相嘲谑，旋忘手冻争拿攫。","乱委平堆可照书，圆瑳小握供弹雀。","静闻裂竹亟扶颠，勇作探春思蹑屩。","犯寒果胜附炎热，苦饥预庆歌丰乐。","长须嫩煮蚓方泣，小龙新破团初瀹。","默观造物真戏剧，更看一色吞沙漠。","载赓险韵付衔枚，孤军大敌空横槊。","寡和尤知白雪高，非偶自贻齐大噱。"]},{"t":"和东坡守汝阴祷雨张龙公祠得小雪会饮聚星堂用欧公故事","f":"七言古诗","c":["六花萼萼都无叶，万花斗白都输雪。","缓飘微霰止还集，急趁回风飞欲绝。","山固无愁鬓先老，竹非为米腰频折。","乡来囊萤本同调，今夕风灯不愁灭。","僧窗处处茶烟湿，渔舟个个纶竿掣。","老坡不犯汝南令，粲如晴午裁新缬。","乾坤荡荡无畛畦，比类区区空琐屑。","雾沉云重记葳蕤，雨收风拾书轻瞥。","肯为忠臣六月飞，剩烦太史从头说。","粗人金帐暖如春，诗人布衾冷如铁。"]},{"t":"借榻妙上人小楼简圆方外","f":"七言绝句","c":["透骨清贫两苦心，圆方觅句妙方琴。","尚堪拥鼻麾崔烈，来借楼头破布衾。"]},{"t":"盆菊","f":"七言绝句","c":["叶底金茎沆瀣浓，篱边令尹酒尊空。","回头说与闲花草，自占春三二月风。"]},{"t":"宝溪鹿苑寺","f":"五言律诗","c":["唐刻文虽泐，梁时寺可稽。","已无金布地，犹有宝名溪。","水媚珠生浦，云低篆绕畦。","夜遥僧定起，璧月在璇题。"]},{"t":"鹿苑乃月堂昌禅师受业","f":"五言律诗","c":["水自朝宗去，源曾发此来。","惠琳参政事，澄观擅公才。","葩焰古难续，袭衣今未开。","不知五百世，几度擢陈荄。"]},{"t":"送友人归湖上","f":"七言绝句","c":["云卷云舒欠十成，暮霞曾误客占晴。","不堪满载朱泾月，冷落阳关第几声。"]},{"t":"云锦亭","f":"七言绝句","c":["花围竹护锦成林，檐压红云绕砌深。","燕子来时寒未了，莫教帘幕带春阴。"]},{"t":"秋塘陈敬父席上饯薛子舒之官建康","f":"七言律诗","c":["秋塘自是眼头高，倒屣于君老更豪。","兴尽有时聊访戴，法当无酒亦邀陶。","乡来文字如翻水，近日工夫又反骚。","月是秦淮旧时月，平分只合与金刀。"]},{"t":"哭赵别驾子野","f":"五言律诗","c":["年高唐进士，官小魏诸王。","落落青云步，朣朣古锦囊。","笔随文冢瘗，剑返虎丘藏。","分得闲风月，湖山不掩光。"]},{"t":"谢张丹霞序疏藁","f":"五言古诗","c":["裳织新云锦，交寻旧布衣。","荆蛮九鼎重，岭海一官微。","心事渊明是，天时伯玉非。","谈高方谔谔，调古独巍巍。","亦有兰为佩，能无简绝韦。","灌缨东涧水，访旧北山薇。","老我家何在，颠风鹢退飞。","袜头常反著，车辙每殊归。","但觉乌仍好，端知骥可睎。","草中同臭少，爨下赏音稀。","煮字徒相饷，忘言合见讥。","牛腰繁卷轴，蚌腹欠珠玑。","重借言如史，轻因鼠发机。","毳云甘寂寞，华衮借光辉。","鸡肋初无取，云斤不足挥。","楼宽长挂榻，月好许敲扉。","踵息宁乖众，心声愿听希。","李虽嘲杜瘦，孟不与韩违。","末路宜多助，孤军伫解围。","载驱惭款段，忍负镂金鞿。"]},{"t":"赵紫芝得羌村图拉余与赵山中同赋","f":"五言古诗","c":["中原闻休兵，久客问归路。","穷途倦策蹇，窘步甚脱兔。","小立候柴荆，互闯走儿女。","喜极先蹙頞，思苦旋煦妪。","触绪尽愁态，抚膝见濡慕。","诸邻稚扶老，旨畜各携具。","老瓦勇倒泻，飞觞约深注。","居者诉徵调，归者诉羁旅。","欢呼贺生还，不醉不肯住。","哂乃骊山梦，奇警在团素。","生灵果何罪，此祸竟谁与。","眼明新画轴，心折旧题处。","掩卷续微吟，玉倚亭亭树。"]},{"t":"雪夜怀上人借衾","f":"五言律诗","c":["挟纩如冰薄，无毡替客愁。","绫衾闲直舍，布被老夔州。","楼玉方撑起，山冰莫倚休。","岁寒知小友，馀暖肯珍投。"]},{"t":"赵紫芝雪中见寄 其一","f":"五言律诗","c":["易销知地燥，未济识天悭。","凹凸难行处，模糊转盼间。","定应凭小槛，频看钓沧湾。","嫩煮添茶兴，何须倒玉山。"]},{"t":"赵紫芝雪中见寄 其二","f":"五言律诗","c":["群峰惊易老，犹自替人寒。","有火虽红拥，慵吟只白看。","不妨添冷落，何暇扫零残。","小伫茏葱日，销镕却怕难。"]},{"t":"池雪","f":"五言律诗","c":["填得中心合，铺成四面齐。","宝奁方剪玉，璧范直裁圭。","水镜难呵雾，冰田不点泥。","霜蟾都隔断，弗许透灵犀。"]},{"t":"耕云","f":"七言绝句","c":["云子炊香欠策勋，无心亦作一廛耕。","石田也似砂田瘦，不是冥搜太瘦生。"]},{"t":"茅屋","f":"七言绝句","c":["索得藑茆不足占，趁晴剪剪插疏檐。","弗图炙背干阊阖，试策奇勋到黑甜。"]},{"t":"酬陈中书杨侯家赏瑞莲 其一","f":"七言律诗","c":["法自春秋著一王，不曾纪瑞到莲塘。","露盘对倚金茎小，水镜双寻玉井凉。","同样著花仍并蒂，异篷结子不分房。","会须问字求玄草，接武华风到后堂。"]},{"t":"酬陈中书杨侯家赏瑞莲 其二","f":"七言律诗","c":["倾城倾国俪侯王，千载馀芳托藕塘。","红入双葩相艳冶，绿摇万柄觉凄凉。","侧承初日联风袂，并挹残蟾酌露房。","花下诗人长不老，岧峣直禁玉为堂。"]},{"t":"少陵画像","f":"五言古诗","c":["我思浣花翁，梦绕浣花水。","有竹一顷馀，杜鹃暮春至。","开元天宝间，九州暗风尘。","新诗一洗涤，天地皆清明。","槐叶一杯春，思君欲走致。","悠然忧国心，天地相终始。"]},{"t":"贾长江画像","f":"五言古诗","c":["苦吟京华春，韩门得归乡。","但知空哑羊，未暇识龙象。","逢人问梓州，策蹇来长江。","长江蛟龙怒，涛澜相舂撞。","公来一弹压，熨帖平如镜。","新吟若为容，万古秋涛瑩。"]},{"t":"送宇文尚书宣抚荆湘","f":"五言古诗","c":["伟哉不世才，要为天下奇。","一鹗不待荐，自受虚皇知。","力精运甓处，心切闻鸡时。","去年镇南徐，前年来合淝。","至今军与民，念之如母慈。","肖象系遗爱，岂特甘棠思。","便合登岩廊，虚襟待畴咨。","春风玉笋班，夜光增陆离。","荆楚天一方，有生怀保绥。","不向繁剧地，何以观设施。","明明九重意，大任端自兹。","诸儒浪誇诧，自许傅与伊。","重内不重外，图安不图危。","一旦大典章，瞢然如乱丝。","始悟少更历，虽悔将安追。","有商六百年，不待试者谁。","版筑与割烹，中有辅相资。","后世伊傅流，纷纷何多为。","公乎风尘际，卓荦起一夔。","轩昂气如虹，霹雳手欲龟。","永怀更一行，策勋早言归。","坐理天下事，迎刃而解之。"]},{"t":"山中像","f":"词","c":["之子瘦策湘竹枝，写我委羽春耕时。","鞭索在手横溪湄，看牛饮溪特子随。","开窗卷帘惊见之，有二文殊还自疑。","镜中瘦影丝发无，参差又如饮溪牛。","觜连觜，蹄踏蹄。","恍然因我得见伊，不知见者端为谁。"]},{"t":"丁丑除夕","f":"五言律诗","c":["结局又开端，更初数到残。","小须新过割，却问旧平安。","事事从头起，悠悠倒指看。","六千三万日，逐日度何难。"]},{"t":"松溪","f":"七言绝句","c":["翠盖童童胜碧油，老根络石漱溪流。","秋池两部吾无取，留得江声在屋头。"]},{"t":"正月初六观灯","f":"七言绝句","c":["山敛吴云暝几层，卷帘都上内前灯。","朔蓂六叶初弦月，犹作朝天淡扫痕。"]},{"t":"挽同衣 其一","f":"五言律诗","c":["有地皆堪隐，云胡独指西。","劫烧翻浊焰，刹说听新题。","春荠挑蘋渚，秋荷缀稻畦。","觉天无落月，耿耿印苕溪。"]},{"t":"挽同衣 其二","f":"五言律诗","c":["印佩三周法，莲栽十丈花。","源寻南岳正，路革化城差。","静与月分座，闲如云住家。","不知百世后，谁索紫金车。"]},{"t":"登齐云楼","f":"七言律诗","c":["云与檐楹面面齐，脚头高处觉云低。","水围万雉半烟雨，天彻四垂漫畛畦。","冉冉无心犹可拊，堂堂有路亦堪梯。","若非梦泽胸中小，空倚阑干到日西。"]},{"t":"孤山路","f":"五言律诗","c":["截水开平地，浮天界碧空。","有云分越镜，无柳似吴虹。","菱棹阑干外，荷花鉴影中。","断桥吟不尽，行过御沟东。"]},{"t":"四月初八","f":"五言律诗","c":["只么随流去，如何庆佛生。","飘零嗟劫浊，湔洗俟河清。","托讽知无益，谗谀又不情。","韶阳奉尘刹，不荐一杯羹。"]},{"t":"续懒庵生前索挽章","f":"五言律诗","c":["死向生前办，铭留去后思。","穴疑龙井迥，邻傍鸟窠移。","殉有登山屐，传无跨灶儿。","它年三尺剑，谁挂碧松枝。"]},{"t":"书智迁抵触图","f":"七言绝句","c":["力敌难教死斗心，墨轻毫淡柳阴阴。","莫将抵触迂奇思，只写洪川扣角吟。"]},{"t":"孤山前举溺死者","f":"七言绝句","c":["柳色经秋草葑湖，菱荷彫尽到菰蒲。","谁将处士孤山路，幻出天台九想图。"]},{"t":"酬韩涧泉","f":"五言古诗","c":["乡来风骚坛，作者肩相摩。","遂使宋嘉定，不数唐元和。","涧泉一官冷，门馆雀可罗。","管中既微露，屡倒名胜戈。","自笑不入时，独对儿女哦。","锦瑟岂不好，弗好如之何。","岂特弗好耳，平地千丈波。","泠泠玉藕船，岂曾翻钓蓑。","归与造物游，坐受醉尉诃。","云月相献酬，泉石供婆娑。","幽芳时自妍，幽鸟时自歌。","遗补南涧书，乐胜东山阿。","怀哉东华门，白玉鸣朝珂。","忸怩避谗謟，趑趄虞轗轲。","聊将须臾忍，付与两鬓皤。","听君闲适篇，所得谁最多。","持此寿闲适，金蟆空坡陁。","思君令人瘦，水远山峨峨。","寄声谢鸿鹄，为把青铜磨。","莫嫌俗眼白，且惜朱颜酡。"]},{"t":"吴吾何待制遣四鹤入山","f":"五言古诗","c":["竹扉无人敲，掩关长夕曛。","一饥苦难疗，三篾收奇勋。","鼎来四胎仙，缟袂垂玄帉。","其一行且却，隐若避世纷。","其一拟前迈，步武闲如云。","唳者又其次，画然戛天垠。","季氏响相答，和乐方訚訚。","昂然青田英，暂尔北涧濆。","鸾鹄倘可侣，鸡鹜端不群。","乘轩初何心，在阴当有闻。","日饮涧底渌，时啄岩根芸。","华表怀故都，蕙帐悲移文。","仙凡岂异辙，风月当平分。","主人尔同调，与俗相莸薰。","浪迹傃富贵，永怀酣典坟。","衡连老苍官，从合抱节君。","遣尔寻考槃，亦足张吾军。","人方斧槁梧，对此齿没龈。","骎骎恐尔及，惴惴令人慬。","胸中小天地，笼中何足云。"]},{"t":"陈卿座上得贵字","f":"五言古诗","c":["后来如积薪，在前类扬秕。","群飞刺天去，寻坠九地底。","扶摇转羊角，力尽固应尔。","赵孟能贱之，何取赵孟贵。","譬夫春方妍，处处耀桃李。","冶容倚皓态，厥类叵胜纪。","一时颜色鲜，永永曷足恃。","要当见平生，姑待灏商至。","楩楠大蔽牛，支厦栋梁器。","春风不知喜，秋风不知畏。","炎炎金石流，凛凛复堕指。","四时有常守，坐看造物戏。","用大古所难，肯顾万牛废。","怀哉楚令尹，落落差可拟。","弹冠既三仕，解冠辄三已。","岂弗曰代耕，岂弗曰行志。","终将奚以为，了弗事愠喜。","一笑付倘来，道在百不理。","特操固超绝，小智谩嗟异。","区区荣辱际，判然遂成二。","炙手苟可热，骈首争附丽。","欣戚变妻孥，况复论州里。","悠哉经济才，未始挂牙齿。","不独不过口，未必不掩鼻。","恶此而逃之，政恐不免耳。","弗为天下先，闻诸老聃氏。","徐行后长者，孟氏亦若是。","聃也未暇学，学孟顾不韪。","唐虞已千古，执中揆诸理。","问之果何事，孝悌而已矣。"]},{"t":"黄龙洞前遇倪文昌赋苕之清","f":"五言古诗","c":["止止天连碧，沉沉镜不磨。","渊源端有自，潢潦尽从他。","清可临流赋，浑贻濯足歌。","中津谁击楫，后进自盈科。","亦有西驰者，其如北注何。","还元虽一味，到了不同波。","至洁清严濑，孤忠叹汨罗。","勺贪惩俗下，汲酿乐天和。","洗耳成轻去，乘槎倘重过。","咸池升晓日，何必挽天河。"]},{"t":"苕溪晚归","f":"七言绝句","c":["轻罗熨帖展溪湄，溅沫飞涛顷刻移。","莲子焦时红蓼紫，采菱船小不禁吹。"]},{"t":"酬赵天乐","f":"五言律诗","c":["桂为诗人馥，邻喧羯鼓催。","秋窗无唤起，海石借飞来。","眼老因山碧，襟疏并水开。","何妨不解饮，对客浅持杯。"]},{"t":"化周大孺人长明灯","f":"七言绝句","c":["古佛舒光照夜遥，微明欲灺倩谁挑。","福田中有光明藏，试遣周郎问小乔。"]},{"t":"吹香","f":"七言绝句","c":["寒压痕云冻不消，华风酝藉不鸣条。","瘦枝褪煖无多韵，亦有鲜明玉色潮。"]},{"t":"芙蓉","f":"五言古诗","c":["溪痕寒不肥，岸容晚益退。","其谁怜婆娑，明霞剪零碎。","烂烂饱泠露，酣酣俯清濑。","宛然古铜碧，嫣然靘妆对。","又若翠袖薄，瘦立烟渚外。","西风仅如许，晚节尚可待。","遂拜拒霜号，不受断肠浼。","亦岂无老成，试请推行辈。","桂腾小山馥，菊耀东篱采。","裳衬芰荷衣，服称陆离佩。","芳芷雅相乡，宿莽安敢背。","花城隔仙凡，俗说信茫昧。","独有离骚经，名氏得先载。"]},{"t":"从闻从思沐发","f":"七言古诗","c":["绝顶丛林茂林叶，虮虱象龙争迅捷。","汤沐风晞曝煖檐，薮剔原搜会秋猎。","齿豁明瑶水为扈，编密青琅陆为罟。","围溃犹思勇负嵎，匪麈匪麇非虎兕。","小生束发能操觚，亦有武备当前驱。","但知疏散非长计，不知远岫云如髻。"]},{"t":"黄茶","f":"七言律诗","c":["官焙曾看白玉花，不知黄玉在山茶。","浅欺罗柳香仍烈，轻压荼蘼净弗瑕。","著露未晞才半萼，倚曛欲透忽全葩。","月团已属卢仝赋，别调何妨记物华。"]},{"t":"慧日致爽轩","f":"五言古诗","c":["襟怀净无尘，太山岩岩秋。","心声响虚籁，何俟西山幽。","悠然一段清，可就不可致。","苟非可人就，未必蒙倒屣。","吾家短髯翁，吴霜诧新茁。","因依眉睫间，凛凛可濯热。","钩帘事晚眺，层翠出林杪。","一笑自点头，万象同飕飗。"]},{"t":"福山渡","f":"五言律诗","c":["鲸浪粘云白，狼山隔岸青。","鸢来方跕跕，鸿去忽冥冥。","欲济江程险，先祈海若灵。","贾胡相习俗，抛掷有残经。"]},{"t":"树经火而殒今复荣茂","f":"五言律诗","c":["无药医双树，扳枝忽再春。","不随人换世，曾见寺归真。","雨露虽全节，风霜只半身。","荣枯相倚伏，东海复扬尘。"]},{"t":"雪窗","f":"五言律诗","c":["小似剡溪船，方方斗底安。","绿疏云母透，青琐水晶寒。","蟾影从低入，蝇头得细看。","人皆苦炎热，一点不相干。"]},{"t":"姜贫乐青龙征商","f":"五言律诗","c":["月冷孤山幌，潮翻沪渎春。","关讥今不古，课最食常贫。","北雁云难驻，南枝雪又新。","莫教诗满箧，忘却寄来频。"]},{"t":"张主簿葵庵","f":"七言律诗","c":["寸金尺地长安土，不种其他只种葵。","葵倚太阳知向背，土于生物荐华滋。","睡醒檐影三竿早，歌彻花阴几线迟。","欲劝飞光一杯酒，要看侧盏绕芳枝。"]},{"t":"有虎","f":"词","c":["悠悠天壤间，务各得其所。","兽蹄交鸟迹，尧忧填肺腑。","伟哉神禹功，明德迈前古。","九畴既定位，万生斯按堵。","奔驰服牛马，飞潜适鳞羽。","虎豹嗜残暴，山林托深阻。","云胡不奠居，出辄啸当路。","昨来东家妪，云汝三瞰户。","西邻竞相告，丰豕娄攘取。","行苇既践履，生理靡繁橆。","田野日搔动，老羸困病窭。","遂使扊扅歌，不待黄昏?。","唐虞全盛时，四凶怒如汝。","赫然雷霆奋，四罪同一举。","彼无罪汝意，汝特犯其怒。","商监犹未远，与汝凶孰愈。","蝮遭愚溪宥，鳄避昌黎去。","大信及豚鱼，二子吾所与。","彼暴化为仁，汝仁亦其伍。","犹来仁暴心，不隔毫发许。","度河速迁徙，负嵎毋跋扈。","况今属多事，诛求猛于汝。","两雄不俱立，孤踪曷足怙。","勿谓三家市，智勇未易数。","智者有馀怒，勇者有馀贾。","排云叫阊阖，长歌捎林莽。","四聪若旁达，百揆必鼓舞。","毒机发必中，万悔竟何补。","丁宁不汝欺，盍亦听吾语。","苟如不我听，是不听尧禹。"]},{"t":"宥蚁","f":"五言古诗","c":["穷山忍调饥，小窗玄豹蹲。","百行无一膻，尔类曷所闻。","倏忽来往频，蠢蠕争夺繁。","报王张义气，贾勇如虎贲。","鼓行有行伍，回旋呼弟昆。","陁然方解严，滃然新分屯。","长蛇偶成势，偃月非无辕。","咂肤甚虮虱，足駃不可扪。","上我古生台，隙我新垝垣。","缀我玄兔颖，饮我陶泓浑。","或循伽梨圈，从朝不知昏。","小弹复就地，讵忍伤其元。","屡扫复屡集，再驰仍再奔。","咄哉诵帚儿，轻儇真少恩。","不复事扫除，直欲加燖燔。","斥儿旋呼蚁，请试为蚁论。","好生乃大德，略听吾㖧㖧。","尔宫大槐国，附庸檀萝根。","南柯在其左，东厢曾偃藩。","休云城郭卑，中有侯王尊。","蜩甲贡庭实，虫臂供盘飧。","犒享日厌馀，糗粻时有存。","可以燕族属，可以蕃子孙。","悠哉天地间，晓然愚智分。","鹏则抟扶摇，鴳则止棘樊。","蟭螟固微茫，触蛮方并吞。","巨细俱逍遥，彼此适晏温。","老我不足慕，负尔犹忍言。","尔留固不恶，诵帚真尔冤。","去去别处去，我砌休重扳。"]},{"t":"蝗去","f":"五言古诗","c":["人言蝗有知，我谓蝗无知。","使其果有知，不出昌明时。","傍睨听我言，饮笑辄见嗤。","问之何因尔，却立双颦眉。","甚矣戆且愚，抑非狂则痴。","谅不阅图史，又弗闻书诗。","不知朝廷尊，但习山林卑。","耕稼徒勤劳，理乱慵考稽。","嗟子昧理道，使我繁言辞。","伊昔贞观中，民生皆熙熙。","呻吟化讴歌，文教渐戎夷。","行旅弗赍粮，道路无拾遗。","外则方与虎，内则傅与伊。","腹心颇胜任，股肱良倚毗。","四海同车书，九重垂裳衣。","虞夏相较量，毫发无参差。","善乎魏郑公，惜哉封德彝。","当此全盛际，蝗起夫何为。","初传满郡国，遄复侵京畿。","民瘼副所求，丙夜长怀思。","未旦坐以待，罪己勇不疑。","奋然事吞噬，厥类举族移。","上帝斯下临，捷于声响随。","良苗曾勿伤，凶岁稔不饥。","太仓皆充盈，老瓦相淋漓。","开元天宝间，燮理颇失宜。","虫横加暴残，田稚难支持。","号令速且严，捕逐期毋遗。","氓力日困毙，彼类尤蕃滋。","不能格天心，徒欲徇己私。","设或遇水旱，人力恶乎施。","世变日益下，汤德常巍巍。","盍广成汤心，以为百世师。","上自天子圣，下逮兆庶微。","德合倘可行，力胜勿自欺。","可以弭灾异，可以延贞祺。","我固肃听瑩，拳拳其敢辞。","再拜嘉昌言，大明烛冥迷。","仲夏月既望，我适田中归。","趯趯五六辈，出入荒芃茨。","见之辄怵惕，滂然挥涕洟。","小复相与言，胡为乎来兹。","倘尔因我来，伴我食蕨薇。","毋使我稼伤，勿令秋庾亏。","俾其丰粢盛，馀则糁藿葵。","谨勿鸠尔类，谨勿增我悲。","尔众易暴寡，我瘠难再肥。","一善倘可穰，众戾幸见归。","天乎弗遐弃，虽死甘如饴。","蝗方蔽天来，容与天云垂。","悠哉翔而集，果适他山飞。","曩闻斯行诸，今者亲见之。","便当如负暄，排云叫天扉。","庶几持一得，或可赞万几。","宣示刍荛言，下付百职司。","上宰天下平，连帅阃外威。","郡国其颁行，风俗端可移。","勿谓此道迂，试以诚至推。","推此及四海，贞观何远而。","当法太宗是，毋遂姚崇非。"]},{"t":"送陈紫薇分韵得寿字","f":"五言古诗","c":["皇极建五福，筮得一曰寿。","人间最殊特，何者出其右。","持以奉君子，数量未易究。","乐哉仁者静，克享本天授。","况复湖海豪，不在曹刘后。","良玉市有贾，韫椟敢轻售。","用大古所难，局缩万牛脰。","巨镛当簨簴，欲振待洪扣。","乘槎到丛霄，下士逮圭窦。","药物固满簋，骥子亦盈厩。","弦歌美遥夜，图史乐清昼。","养高知道腴，思苦坐吟瘦。","淫蛙不停响，老凤合伸咮。","想当吟酣时，俗驾不得簉。","广居与正位，自有不须僦。","一篇荐蔬笋，三舍避衮绣。","桂玉破官舍，芝兰茁瑶甃。","莫讶分符速，正恐传衣骤。","归来黄金瓯，名氏得先覆。","看镜了心期，一笑丹砂就。"]},{"t":"陈紫薇知宛陵出关三日复召归 其一","f":"五言律诗","c":["竹分宛陵去，环赐北关归。","出昼只三日，排云趋九扉。","春风随意好，卿月上天飞。","想见高寒处，朣朣并紫微。"]},{"t":"陈紫薇知宛陵出关三日复召归 其二","f":"五言律诗","c":["笼锁新莺啭，帘容旧燕归。","禁林仍下榻，画戟漫开扉。","虚与谷相应，淡如云自飞。","升沈知雅量，喜愠不几微。"]},{"t":"西庵惠海棠","f":"七言律诗","c":["妃子惊回午枕时，别无名品略因依。","效颦已笑林禽粉，谐俗偏嫌谢豹绯。","碧酒晕朱犹未褪，丹肌痕露欲全晞。","同盟更有红千叶，细剪垂丝纬锦机。"]},{"t":"送叶桐轩赴永嘉上幕兼简刘使君 其一","f":"五言律诗","c":["清才出故家，幕府在东嘉。","吟熟蕃池草，潮回富石花。","霜垂低树实，珠滴小槽霞。","更勺龙翔碧，晴窗试麦畬。"]},{"t":"送叶桐轩赴永嘉上幕兼简刘使君 其二","f":"五言律诗","c":["雁宕雨初收，迟将部曲留。","佳山如好友，远仕当清游。","忆与白鸥侣，曾盟贤郡侯。","依刘可无地，莫倚仲宣楼。"]},{"t":"青龙张贤良四高堂","f":"五言律诗","c":["肯续高人传，能分鼎足无。","烦君添一个，为我壮全吴。","正学非谋士，清吟岂钓徒。","须知而祖意，断不在莼鲈。"]},{"t":"柔桑","f":"七言绝句","c":["羽葆攲墙绿未摇，春风易放曲尘消。","天教叶叶关机轴，不与群芳一样彫。"]},{"t":"揽镜","f":"七言绝句","c":["新茁吴霜剪不零，临鸾羞涩对星星。","天生两眼人嫌白，只有青铜照得青。"]},{"t":"薛子舒半镜","f":"词","c":["饥蟆缘云吞婵娟，径圆千里亏一边。","何年吹缺堕九地，更复几时飞上天。","不悟素为明所误，削地更无开拓处。","遂使骑鲸汗漫归，拟斫婆娑镜中树。","又疑白玉楼居大手笔，喝得倒行轮半仄。","至今弗作玻璃声，犹自铮铮作金石。","不然十连酬贾难，怒发凛凛冲其冠。","归来寒芒耿夜阑，亭亭小试龙文看。","半规朣朣尽分晓，团团如漆知多少。","是中观德又观空，缺处何曾碍圆照。"]},{"t":"立夏","f":"七言绝句","c":["弦改南薰曲自调，萦回小篆水沉消。","叶舟自打窗前过，只有杨花度小桥。"]},{"t":"悼赵紫芝","f":"五言律诗","c":["不解俯华簪，峨峨独苦心。","反骚嫌少作，番袜动新吟。","折玉兰风急，摧金菊雨霪。","中年儿女泪，消得几沾衿。"]},{"t":"杨梅","f":"五言律诗","c":["枝繁疑坠地，烟暝欲燉空。","止渴差相似，和羹却不同。","每嗟龙井白，易变鹤头红。","好在文园令，冰盘对晚风。"]},{"t":"千叶栀子花","f":"五言律诗","c":["虽与馀香别，何曾别样开。","一花分六出，千叶是重台。","玉洁浑无玷，金黄谩夺胎。","寻思天下白，只合友江梅。"]},{"t":"盘隐陆别驾楼居 其一","f":"七言绝句","c":["别浦潮生玉一痕，倚阑目送渡江云。","宝莲秀色连秦望，商略风烟到十分。"]},{"t":"盘隐陆别驾楼居 其二","f":"七言绝句","c":["隔江便是越州山，无雨无晴尽好看。","不妒卧楼高百尺，妒它终日倚阑干。"]},{"t":"颐斋","f":"五言古诗","c":["有生分贵足，足患不自知。","知贵得所止，不止盈益亏。","盘涧隐沦友，图史森孙枝。","闲适寿且康，不止将奚为。","卜筑脩竹间，养正是用宜。","惟其得所养，自乐颐之时。","初筮得上九，颐道皆备之。","静默战纷华，燕晦观群蜚。","对月喜秋霁，问柳知春归。","鸣鹤闻夜弦，振鹭惊昼棋。","池宽纵鱼乐，机忘悟鸥疑。","幽草时自妍，歌鸟时自窥。","钓则钩可直，艺则芳可移。","酒酣卧花底，不知吾为谁。","起来飞羽觞，万化同熙熙。","药圃雨新霁，徐步观耘耔。","眉津双解颦，心渊平弗攲。","酡颜渥且丹，老鬓秋不萎。","从它自逐逐，舍蔡观朵颐。"]},{"t":"赠写竹叶生","f":"五言古诗","c":["三年一楮成，九年一弓就。","虽刮造化骨，总落造化后。","叶生翻袜法，二者竟何有。","因依霜节劲，缱绻虚心厚。","细意幻扶疏，与俗洗棼垢。","慨慷纵一醉，顷刻便千亩。","不知盘礴时，更有全牛否。","忍贫不谋富，捉衿见两肘。","千愁怜竹瘦，百屋嫌铜臭。","虽无种秫田，亦有吸川口。"]},{"t":"可庐","f":"七言绝句","c":["傍水依山便托栖，百年心事老茆茨。","恰如彭泽归来后，柳色遮门菊绕篱。"]},{"t":"苕溪行","f":"词","c":["清苕可镜亦可渔，风烟佳处画不如。","无钱买田傍城阙，拟僦溪叟西邻居。","得鱼换得菰蒲米，菰煮作糜饱则已。","宁能负腹不负人，以腹负人不若死。","富春残火犹堪稼，上时容易艰难下。","在山远志山可移，小草还复令人讥。","菱歌惯涛澜，樵声出林疃。","蘋风为谁好，璧月待秋满。","延月入怀输恳款，好风未必无人管。","笔床茶灶散人家，何须去乘牛斗槎。"]},{"t":"九日登莲峰得二石一石如鱼而尾赤名之曰赪尾一石有眼口鼻名之曰山鬼 其一","f":"五言律诗","c":["青巉俯碧浔，潜伏翠层深。","雨蚀莲峰碧，岚昏鹫岭阴。","朵云生燕寝，片玉下岑崟。","可拊仍堪击，依稀一寸心。"]},{"t":"九日登莲峰得二石一石如鱼而尾赤名之曰赪尾一石有眼口鼻名之曰山鬼 其二","f":"五言律诗","c":["怪状出岩扃，山精死弗灵。","文如云子白，质带土花青。","雨信莓苔湿，蜗涎窍穴腥。","九歌如可些，为尔续骚经。"]},{"t":"酬毓斋李尚书","f":"五言律诗","c":["惜闲如惜金，不趱雪侵簪。","步向青冥却，交容野逸寻。","禅深排默照，句熟动酣吟。","得趣忘弦索，无声自赏音。"]},{"t":"寄乡州宪使曹国博","f":"七言古诗","c":["雁宕秀色连脩眉，胸中岂止雁宕奇。","展旗卓笔在怀袖，文事武备皆称之。","剑南江山梓最胜，弹压江山须逸兴。","国子先生绣斧光，一道风烟入评品。","颇闻边警喧蜂虿，谈笑从容起凋瘵。","勿谓生平少作诗，古锦可容空载归。"]},{"t":"酬杨左司","f":"五言古诗","c":["蜜花小春操，自笑雪萼迟。","中有千斛香，半点不自私。","逮兹良月半，著得鲜风吹。","吹作群卉先，以庆此段奇。","悠然一临风，粲然一解颐。","孤芳尔何事，要结斯人知。","紫荷乡来橐，綵庭亲付衣。","今兹玉笋班，默赞元化机。","不知春几何，但见物自怡。","蔼蔼蒸粹和，荡荡生华滋。","问之何因尔，有以润色之。","善颂继善祷，试听舆人辞。","亦既多寿祉，颂祷夫奚为。","盍观舆人心，以尉舆人思。"]},{"t":"逆风行","f":"词","c":["大块噫气一气同，条达万汇参化工。","不教扶摇转羊角，五日一吹零雨濛。","唤醒枯槁皆蒙茸，假借秋鬓回春容。","后来见说兰台宫，君臣相与论雌雄。","至今雌雄无辨白，几回拟问兰台客。","便从平地欲泠然，结口土囊呼不得。","坐使六月七月背汗挥老农，燥土滴作兰塘融。","赫赫炎炎濯无处，积威蓄锐尽数施玄冬。","一叶东来顺流水，怒号不肯吹船尾。","转船又复投西去，蓬蓬依旧从东起。","试从逆境求诸己，可容不拜飞廉赐。","谨勿颠狂蹈前辙，长不鸣条伴华月。"]},{"t":"拜真歇了菩萨塔","f":"七言律诗","c":["只作深云土一抔，象龙蝼蚁弗同谋。","郁金薰陆不足道，行潦潢污端可羞。","岂特龙翔开壮丽，也曾雁宕见赓酬。","人言合瘗凌霄顶，我谓凌霄在下头。"]},{"t":"蔡京葬处女冠居之","f":"七言绝句","c":["观里黄蜂晚退衙，观前桃著小春花。","更无寻访麻姑处，零落风烟似蔡家。"]},{"t":"谢楼别驾","f":"五言古诗","c":["日者鹓鸿序，年来月旦评。","芳腾新令问，绝似老先生。","特立风尘表，全消鄙吝萌。","步何妨展骥，乐岂俟专城。","书卷终长策，云窗尚短檠。","不知身富贵，犹遣笔耘耕。","大雅连城重，籯金一羽轻。","无弦皆古意，比竹谩新声。","玉骨难教俗，金茎只得清。","试论簪履旧，细细勺高情。"]},{"t":"谢人惠斗綵袱","f":"七言律诗","c":["碎红零绿尽其宜，骈俪收成一段奇。","曲砌鳞鳞尤缜密，方联翼翼自参差。","大成富有诸家善，小数穷如集句诗。","蜀锦吴绫重表出，阿蛮针线策勋时。"]},{"t":"李燕公生华亭尉厅旧有相公阁可斋洪少府于废址更为梦燕堂用玉燕入怀事永嘉赵清旷索同赋","f":"七言律诗","c":["适华胥氏问津来，祥兆其先必有开。","偶尔入怀真是玉，及乎同梦却非梅。","曰兰倘可名千古，指李何妨又一回。","未问读书堂上客，斲轮堂下亦英才。"]},{"t":"瑞香两首 其一","f":"七言绝句","c":["旧从康俗老千峰，紫绮裁葩藐万红。","一与宫花分次叙，至今羞杀锦熏笼。"]},{"t":"瑞香两首 其二","f":"七言绝句","c":["低欠阑干护绿云，紫苞寒褪暖敷英。","服膺不下南枝拜，应使馀香误得名。"]},{"t":"隙月","f":"七言绝句","c":["侧飞蟾影入檐低，鹊倦乌慵尚绕枝。","灯灺小窗帘不卷，定回冻合玉楼时。"]},{"t":"内相洪容斋名诸孙华亭少府曰可斋","f":"五言古诗","c":["滥觞学沧溟，弗至吾弗已。","九仞规成功，弗成吾弗止。","方其未至时，傍睨岂知此。","及其既成后，岂暇顾傍睨。","或云山既高，我则揆诸理。","或云海未深，我则反诸己。","所立固先定，所诣孰能尼。","刻瓜大如斗，浅诺复轻唯。","甚者反自画，不则中道弛。","傲然曰山海，不了可斋耻。","可斋何人斯，故家振番水。","束发读父书，介特固若是。","幼蒙玉堂印，壮授盘洲记。","至于自肯时，不见两君子。","黄河可为带，太山可如砺。","悠然君子心，无同亦无异。"]},{"t":"酬秋塘古诗之惠","f":"七言古诗","c":["乡来小朵烟苍苍，乌纱瘦策寻初凉。","囊封借月留云章，朗吟响答山琅琅。","寥寥十载遥相望，尺书不得鸿雁将。","朅来屡分读书床，残编断柬杂朱黄。","梅花楮帐芙蓉裳，书传腾馥掩众芳。","前日破雨破竹窗，勃窣倒屣成踉跄。","寒暄一语不暇吐，望之岿然鲁灵光。","郊寒岂复疗岛瘦，齐大叵堪容楚狂。","亭亭雪茸未下榻，采采霜荠先盈筐。","长歌烂烂古锦段，十诗亹亹秋圃场。","离骚大雅得祖述，夜光明月相抵当。","不贻它人乃见及，三咽十袭藏缄箱。","藿葵䫲颔欠琼玖，谁羹甘露医沧浪。","车轮裹蒲碾云汉，为我举手瓢天浆。"]},{"t":"南山阻雪 其一","f":"七言律诗","c":["裂竹声乾搅夜林，宽裁玉楮漫重衾。","遥知凹凸先平满，未暇崎岖探浅深。","冻折衣棱须煖熨，明穿檐隙怕寒侵。","西湖冻合方连底，独钓无人傍涌金。"]},{"t":"南山阻雪 其二","f":"七言律诗","c":["密密疏疏忽满林，小斋冷直欠绫衾。","旋疑蟾毂行春晓，细看蝇头到夜深。","已有四郊三白瑞，更无一点软红侵。","庭除层砌皆明洁，长笑当时侧布金。"]},{"t":"送魏郎中出守潮阳","f":"五言古诗","c":["临邛犊鼻裈，环堵长萧然。","千金贱卖赋，忍为俗子妍。","安知有名胜，文采明相鲜。","环堵不相下，危行仍危言。","自有万间屋，未暇著一椽。","屹立鹓鹭行，飞作蓬莱仙。","鲜为目前计，阔著胸中天。","千骑潮阳州，旌旆行翩翩。","身居风化首，鞭著循良先。","鳄鱼碧潭底，瘴海光风前。","物既不疵疠，俗亦知变迁。","问之何因尔，仪刑邦伯贤。","我恐席未煖，十行来日边。","哂乃韩退之，袁州小回旋。","当如黄丞相，登庸由颍川。"]},{"t":"李夔州挽章 其一","f":"五言律诗","c":["防拓西南重，皇华赋咏优。","忍将忧国泪，来作听猿愁。","瘴扫乌蛮俗，吟残白帝秋。","脩名磨不得，三峡自东流。"]},{"t":"李夔州挽章 其二","f":"五言律诗","c":["俭素律豪奢，攻浮复填华。","竹枝谣五裤，棠影懋三巴。","硖雨催吟翰，江春酿醉霞。","不知舒啸地，谁此岸乌纱。"]},{"t":"谢高秘书雪蕈","f":"七言绝句","c":["瘦云臞雪漱霜漪，烟火无功合茹芝。","囊锦若编群玉府，树鸡吟续晚唐诗。"]},{"t":"素斋于君实赋别兼简方岩侍郎","f":"五言古诗","c":["诸公皆青云，一士独苦心。","怀哉英雄泪，亦复长满襟。","乡来梁楚声，不贵双南金。","九仞横界墙，馀子不敢侵。","两鬓吹黄尘，倦翮投晚林。","渺观酒勍敌，袖手妒病瘖。","元龙异姓兄，老凤仪韶音。","秋窗坐欲曙，晓灯挑不禁。","鸰原思寥寥，雁影云沉沉。","东观可纵观，北斗当满斟。","虽无广文毡，亦有丞相衾。","好邻买道南，逸兴追山阴。","唤起方岩翁，共作商岩霖。"]},{"t":"送方岩下黄岩曲江阻风几溺 其一","f":"五言律诗","c":["天云卷炮车，横波起涛头。","拔木如剪叶，况复一叶舟。","乡来不鸣条，酝藉仍风流。","今也贾馀勇，浩荡隳前修。"]},{"t":"送方岩下黄岩曲江阻风几溺 其二","f":"五言律诗","c":["万籁忽自作，萧萧夜何其。","悠然一寸阑，雪衮涛山飞。","飞廉尔何事，狡狯取巧施。","古井湛弗摇，鼓荡终奚为。"]},{"t":"元日领客登北高","f":"七言绝句","c":["云绕檐楹扫不开，阑干直下是飞来。","笑看白玉芬陁利，领略风烟又一回。"]},{"t":"别李子源","f":"五言律诗","c":["分携二十年，解后复翩然。","易办长亭别，难忘短李贤。","春非无胜日，雨是未晴天。","最是关心处，帆开顺水船。"]},{"t":"景献诸兄侍两国入山","f":"词","c":["飞鞚入山深，幽从野逸寻。","闸开观喷激，云敛闯?嵚。","茵锦苍苔绿，油幢碧树阴。","客儿亭最古，访古盍重临。"]},{"t":"清明日闻杜鹃","f":"七言绝句","c":["吴越清明四十年，可曾归梦搅清眠。","楼头欲与仲宣语，蓦地一声啼杜鹃。"]},{"t":"方岩侍郎得灵壁一峰名碧云","f":"七言古诗","c":["坡陁巨璞韬玄质，壤断虏尘天半壁。","乡来谁试小龙文，切得一峰归笠泽。","太湖绕山三万顷，奇产虽多不足惜。","云边七十二峰青，强颜亦复无颜色。","滑肤弗受莓苔裹，素蕴岂容尘土蚀。","云升霞举幻瑰奇，玉响金浑随拊击。","一从越相去悠悠，几见吴宫春寂寂。","方岩委羽在何许，帖天弱水蓬莱隔。","泠然一瞬三万里，风烟浩荡寻无迹。","既伴壶中清昼长，想见袖中东海窄。","那知篆鼎铭彝外，尚馀三丈浯溪石。","擘窠不到小玲珑，却须细细蝇头刻。"]},{"t":"醒庵王大卿松柏屏障歌","f":"七言古诗","c":["青青岁寒之淡交，柏也揖逊苍髯梢。","凛姿古调瘠而实，昔未成才先莫逆。","执此能事柄者谁，弹压玉霄王紫微。","千古万古不可追，落子亦复四十围。","公乎多才亦多艺，小试演纶光帝制。","复将馀墨散馀春，烟云树石皆精神。","擎重雪枝寒不倚，霜干相周不相比。","山林豪逸并孤标，冠剑大臣横劲气。","想当欲画未画时，积思凝虑全天倪。","忽然直上盘云霓，不见笔墨之畛畦。","因依方寸亦磅礴，岂止一丘仍一壑。","良木非摧石不崩，于戏九原不可作。"]},{"t":"柳絮 其一","f":"七言绝句","c":["轻轻漠漠又斜斜，去作青萍漾水涯。","院落晚春闲意绪，合分一半与梨花。"]},{"t":"柳絮 其二","f":"七言绝句","c":["勇作轻狂又懒飞，又如欲去却沉思。","霅云不度清苕曲，独受融风款曲吹。"]},{"t":"送常德徐使君兼简李伯达 其一","f":"五言律诗","c":["孺子老蹁跹，尊前小谪仙。","水程春泛鹢，山驿夜啼鹃。","屏小梅垂实，楼高柳度绵。","楚天回雁字，几日到吴天。"]},{"t":"送常德徐使君兼简李伯达 其二","f":"五言律诗","c":["榻为何人下，书令稚子温。","定驰天际梦，来访水边村。","秦地千年旧，桃花几树存。","为宣邦伯惠，诗礼教儿孙。"]},{"t":"椀柏","f":"五言律诗","c":["土入花瓷浅，林疏雪操鲜。","后凋非地力，独秀是天年。","老我不谐俗，惜才如养贤。","明明千古意，渠自指庭前。"]},{"t":"谢随庵赵牧之墨竹","f":"七言古诗","c":["胸中千亩不愿馀，颖也戏剧资轩渠。","湖州九原不可作，百年合浦今还珠。","玄卿浓淡知权变，淋浪迅疾如驰电。","为君击节赏此音，孝娥庙刻题黄绢。","君胡不歌石鼎联，两手笑拍弥明肩。","又不钓垂五十犗，六鳌一掣空重渊。","幻成群玉参差立，露梢点滴鲛人泣。","鹘落还从兔起时，一机才失嗟无及。","我住双岩峰下寺，梦断池塘无一语。","家山新绿报平安，万金堕眼宽西顾。","葛陂头角犹完全，镜中观影俱茫然。","坐令野人破屋壁，万里风烟生咫尺。"]},{"t":"书诚斋答晦庵帖伤刘子澄死于贬所","f":"七言绝句","c":["宋司马后鲁臧仓，贤圣虽穷道不伤。","老子看棋高一著，噬脐空自忆刘郎。"]},{"t":"石人","f":"五言律诗","c":["面冷如水瘦，心刚笑竹虚。","痕云衣不浣，晕藓髻难梳。","七凿混沌死，十成山泽癯。","谷城山下路，谁复理残书。"]},{"t":"墨荔枝","f":"七言绝句","c":["尘蜕冰肤玉透肌，皱絺洴墨剪裳衣。","芳鲜甘与缁云老，不与轻红转眼稀。"]},{"t":"凤儿花 其一","f":"七言绝句","c":["小似钗头缕粟金，不将红浅笑红深。","虚名冗到闲花草，寂寞朝阳采羽瘖。"]},{"t":"凤儿花 其二","f":"七言绝句","c":["弄玉何年堕翠钿，托根便作九包妍。","飞花只合秦楼去，莫与金钗压鬓蝉。"]},{"t":"谢司令惠赐茶","f":"七言古诗","c":["昨寻密斋觅茶吃，倒屣踉跄笑相逆。","一杯青白胜黄白，好风两袖来无迹。","晴窗午景浣风味，露饱秋蝉谩尘蜕。","周诗虽记苦如荼，浮俗但知浓若醴。","归来急足敲晨扉，香郁密云光陆离。","圭零璧碎不复惜，自候泣蚓声悲嘶。","不妨为佛先拈出，油然雪乳翻秋色。","更需佳士细商评，我恐眼中无此生。"]},{"t":"次陈中书惠生绡韵","f":"七言绝句","c":["曾评五字玉堂诗，豪压城南示阿宜。","池上凤毛今几个，阿宜何似阿戎奇。"]},{"t":"钱竹岩之官清远","f":"五言古诗","c":["帆挂之清远，潮来驾浊流。","火云方振虐，仙舄自生秋。","拔宅虽浮汎，逢山得款留。","一夔携骥子，几度访羊裘。","景尽孤台胜，题分庾岭幽。","风餐愁欸乃，水宿贯钩辀。","文采休藏豹，诗盟莫冷鸥。","神明毋自鄙，蛮瘴不胜瘳。","单父鸣弦外，巴东野水头。","鼎钟馀事业，一德配灵脩。"]},{"t":"书陈平佐刺图","f":"七言绝句","c":["千虑难穷智士心，周防密计保千金。","宁能有备为无用，一寸渊渊几许深。"]},{"t":"早过湖","f":"七言绝句","c":["唤得航船傍采菱，柳桥竹榭曙烟深。","船头惊起蜻蜓睡，欲立还飞到涌金。"]},{"t":"日者鹤轩","f":"七言绝句","c":["令威不在鹤轩先，华表归来是几年。","试向青田问休咎，不知何日去乘轩。"]},{"t":"题三教图","f":"七言绝句","c":["岩高风压树头低，三子相逢把手归。","掩室在陈无足笑，笑它同传有韩非。"]},{"t":"苦旱","f":"七言古诗","c":["荼蘼殿春春云徂，芳庭过雨红欲无。","一晴不雨苦阳久，四五十日瞻天衢。","黄尘陆涨草树暗，积水戽乾河港枯。","秧犹未插莠如棘，田已不胜龟拆涂。","沈牛投虎竟茫昧，死鹬脯蚌才斯须。","蜿蜒展转不肯寤，山川尸素方宁居。","困鱼止陆相喣濡，斗升未必副所需。","元首股肱本同德，熙怡和乐绵九区。","万几总览天所见，十目所视吾谁谀。","商羊弗见来庭除，旱魃妄冀逃天诛。","曩闻尺箠笞单于，岂不足将雷电驱。","不须决海戒覆车，不须挽河洗潢洿。","只愿闭门十日雨，四海凉生毙九乌。"]},{"t":"苦旱书蕉叶","f":"词","c":["自是秋怀易寂寥，强将离绪怨芭蕉。","教它不报??信，只么萧萧过夜遥。"]},{"t":"太湖初日","f":"七言绝句","c":["飞光飞上碧澜底，碧跨三州连底明。","多少潜珍畏人见，只知犀炬太无情。"]},{"t":"朱庵睡起","f":"七言绝句","c":["檐外飞花不翳天，阶前浅水恰通船。","借床睡起自作供，餐尽楚英霜后妍。"]},{"t":"会稽胡丞相过","f":"五言律诗","c":["眚目醌衔冰，逃空喜弗胜。","别怀虽易久，雅况独难承。","官业清于水，家生少似僧。","不知厅壁记，几个似君能。"]},{"t":"桃源行","f":"七言古诗","c":["种桃种得春一原，逃死逃得秦外天。","杀鸡为黍替草具，不识晋语犹秦言。","昨日相逢今日别，流水落花行路绝。","鸡黍更从仙隐设，疑是齐东野人说。","典午乱多仍治少，此事明明不分晓。","一秦才灭一秦生，避世避人还避秦。","忆昔怒驱丞相去，犹思上蔡东门兔。","纵有封君禄万钟，争如食邑桃千树。","空山惜日见日长，秦民怨日偕日亡。","恨身不为治时草，不恨祖龙长不老。"]},{"t":"拜总持尼祖塔","f":"七言绝句","c":["平生自爱黄金膝，肯屈榛芜草棘深。","弗似灌溪闲上座，尼坛再展不同心。"]},{"t":"自寿","f":"七言律诗","c":["燕雀生成日几何，技惭断断更无它。","近来同岁人尤少，老去思亲泪更多。","无事关身惭素食，有心作佛笑凡科。","思量大欠工夫在，更把馀生细濯磨。"]},{"t":"戆庵约子与素斋赴二石丈江阁之集得颊字","f":"七言古诗","c":["半山蛇腹弯城颊，层云鸱尾翔山胁。","紫萸独自对黄花，采笔不须题落叶。","山容入秋太瘦生，倚筇欲赋登山行。","诸公谭玄若破敌，万籁为我俱销声。","俯瞰市人酣战蚁，喧寂两忘同一视。","悠然五字隐长城，万马循墙看披靡。","数峰薄暮方展眉，笑人买山后小支。","谁能料理身后计，更复愿为天下奇。","沧江潮晚鲸吞吐，白鸥群分复群聚。","出门一笑问浮图，风动琅珰半天语。"]},{"t":"粟隐","f":"词","c":["坤壤大如许，或谓藏于斯。","此理颇未安，如之何勿思。","乡来云梦吞八九，眇而视之竟何有。","是中馀地渺无边，尽吸西江斟北斗。","区区载笑触与蛮，流血如海骸如山。","蟭螟之国蚊睫间，开边拓土久不还。","隐沦萧洒尘嚣外，六合尘嚣在其内。","俗子先标出大门，我欲乘风跨鹏背。"]},{"t":"持钵 其一","f":"七言律诗","c":["未必腰缠把鹤骑，可堪青女奋全威。","推蓬教密寒尤重，挟纩虽重煖尚微。","沓足敢忘偎叶记，屈身不与曲肱违。","船头亦有茏葱日，水激风回作雪飞。"]},{"t":"持钵 其二","f":"七言律诗","c":["乐岁持盂尚许艰，有求那解破人悭。","立残穰草堆头日，撑尽苹芜断处湾。","钟鼓敢嫌贫指众，斗筲庸恤老腰顽。","归舟只载华亭月，不作华亭误夹山。"]},{"t":"持钵 其三","f":"五言古诗","c":["颠风挟玄霜，跋扈清溪阴。","长年把船尾，铁面抵弗禁。","面皴不暇问，腕裂龟文深。","手中老篙竹，出水冰淋淋。","一步一千里，进寸或退寻。","抵死为食谋，俛首潜呻吟。","劳人冻入骨，寸心攒万针。","乐哉田舍郎，坐拥廪若林。","强使损绪馀，瞪目如病瘖。","所得不盈把，粒米敌数金。","沈思耕者志，岂异舟子心。","其谁受此施，观此受施箴。"]},{"t":"送宗无传赴闽帅杨伯子西禅之招","f":"七言律诗","c":["尚有诚斋老宁馨，来寻方外阿师兄。","滔滔入海如泾浊，囧囧于公独阮青。","旧忆薰莸分草木，新来一再扣柴荆。","不龟手是家传药，莫遣人言药不灵。"]},{"t":"卢太君","f":"七言古诗","c":["老颜瑩玉卢堂前，明年一百欠一年。","岁时罗拜各有序，四三千指诜诜然。","发白衣斑传冢嗣，子生孙了孙生子。","寸田种德日蕃滋，一气所钟至于此。","寿骨棱棱岁寒后，深拜伽梨问耆寿。","尽将回向南极星，化凶短折为脩龄。"]},{"t":"不雨","f":"七言律诗","c":["田欲龟文晓尚龟，高高如燎恐云焦。","未应天上无炎热，可是山中欠燮调。","草偃风颠凉自至，雨随车后暑应消。","冷菰寒玉关心外，却立虚庭望泬寥。"]},{"t":"访菊","f":"七言律诗","c":["东篱贬剥勿丝毫，著得先生一字褒。","剩馥缅怀彭泽县，落英掩恨楚江涛。","缀团晓露心尤苦，揖逊春风节更高。","不把幽妍酬愤悱，鸾胶弗解续离骚。"]},{"t":"泣胡晦叔 其一","f":"七言律诗","c":["一臂才交小朵阴，傍池分石坐云深。","先生自袖春风手，乔木吾非故国心。","操与苍官同瘦立，思兼梁甫独长吟。","锦囊羞涩惭多助，卷尽牛腰尚忍寻。"]},{"t":"泣胡晦叔 其二","f":"七言律诗","c":["书恨来迟讣亦来，寸刚不觉为君摧。","双眸忍俗终难瞑，流水无情去不回。","定作雷霆输宿愤，枉教风鉴在棼埃。","断魂巫峡归丹旐，深注山茶酹一杯。"]},{"t":"颜丞开炉","f":"七言律诗","c":["鳞差云母著书窗，软火深炉晓自妆。","篆恰才消馀桂馥，手终不暖为枨香。","小中天地何妨大，闲里工夫不欠忙。","莫向市朝寻大隐，二松环水自汤汤。"]},{"t":"梵天僧舍金竹中有绿竹一茎","f":"七言律诗","c":["手栽碧玉间黄金，炎赫流金弗敢侵。","莫作两般分实相，定知一等是虚心。","根分丽水难沉色，节老蓝田待赏音。","终有九包来止息，万竿何患不成林。"]},{"t":"书雪巢林景思诗卷","f":"词","c":["诗人巢雪如住山，巢中所得强得官。","官微不足了饘粥，尽日幽寻遣儿读。","舂容大篇辄千字，鍊字贵活不贵死。","乡来杜陵有布衣，晚到夔州也如此。","乃今遗藁安在哉，古花囊锦宗文开。","开缄宛见谏议面，只字重哦复三咽。","三咽然后耳有闻目有见，见人捧心颦两眉。","不学施家女，只学唐人诗。","为言诸子将安之，巢空雪明康鼎来。"]},{"t":"青梅子","f":"七言绝句","c":["雪未消时入旦评，才黄又属傅岩人。","暂分叶底藏身地，部领莺花过半春。"]},{"t":"三友轩","f":"七言律诗","c":["矫矫苍髯傍把茆，疏疏碧玉倚琼梢。","饱经霜后转无恙，未及岁寒先定交。","影瘦自随窗月上，阴浓时有岭云巢。","此君不独论三益，高节还应待九包。"]},{"t":"小泊湖州","f":"七言绝句","c":["蜿蜒粉雉枕寒汀，阔著清苕碧界尘。","帆落水晶宫未晓，素花开尽一溪蘋。"]},{"t":"酬晦斋谢司直和子寿宫使赋归来望思之台","f":"楚辞体","c":["推恩保四海，寡恩徒自戕。","父兮不念子，悠悠我心伤。","父子至情天性也，戾岂自经沟渎者。","回天无药愈狂酲，朽索胡为羁六马。","邪心不作天不疑，皇恤江充刘屈氂。","灵脩一悟倘可冀，抑免杀身伤父慈。","千秋一言机发弩，堕甑已非何所补。","归来望思兮胡不归，千古万古一抔土。"]},{"t":"昭台行 其一","f":"楚辞体","c":["昭台一锁无开扉，君恩易随朝露晞。","桃笙葵扇果何物，不长相保终奚为。","人言昭台失其所，殆不知其得其死。","当时嫁作将相妻，赤族之顷宁独遗。","父兮久持震主威，兄也景升豚犬儿。","负芒之背潜生疑，祸萌骖乘渠莫知。","君王持心亦太薄，滋蔓不图惟稔恶。","立无嗣续劝功臣，只书官氏标麟阁。","将军惜子如惜金，不为长计诚何心。","丈夫事业当惊世，区区乌足私家计。"]},{"t":"昭台行 其二","f":"七言古诗","c":["将军发机阴中的，功如熟稼生螟蟘。","母仪天下极尊荣，非道得之非所得。","一朝乐去悲相随，霜露既降风凄其。","茕茕吊景将安之，不自为计终奚为。","关中旧约三章法，法当夷宗雠逆节。","况复曾孙诛大臣，项背相望眉不颦。","昭台不隔昭阳路，花落鸟啼春几度。","麟角凤觜皆可煎，惆怅君恩非断弦。"]},{"t":"龙井吊古","f":"七言律诗","c":["井龙孤躅转空濛，万斛泉源忆长公。","流水高山仍古意，落花啼鸟自春风。","石题岘首千年后，人在苏堤万柳中。","惆怅半生行乐地，阑干曲曲夕阳红。"]},{"t":"病起书蕉叶 其一","f":"七言律诗","c":["寂寞经春苦未荣，蓦舒新绿上疏楹。","不追松柏凌霜操，漫学梧桐送雨声。","抽半卷心忺趁晓，剪全开叶恨遮明。","炎炎三伏流金石，来相茶瓜枕簟清。"]},{"t":"病起书蕉叶 其二","f":"七言律诗","c":["摇青已见及时荣，猎猎翩翩衬短楹。","似我不才非世用，对伊侧枕听秋声。","影铺缺甃侵苔绿，丛倚疏棂蔽月明。","脆弱不胜连夜雨，亟凭幽讨饯馀清。"]},{"t":"病起书蕉叶 其三","f":"七言律诗","c":["青鸾翠尾曳前荣，仄雨番风绿闯楹。","的自梦中包死鹿，误从雪里著嘉声。","烟寒曲砌秋容澹，句满旁行墨色明。","尽是吹来最奇警，与君分此一襟清。"]},{"t":"代觉无象续楮衾吟谢楼大参","f":"七言绝句","c":["一合溪藤展样裁，蒙头叠足傍寒隈。","玉楼冻合春初透，只有青灯伴定回。"]},{"t":"送谭浚明归江西","f":"七言古诗","c":["恨无玉楮三千幅，尽使春风归约束。","乐饥功谢明月珰，休景息惭芰荷屋。","朋来皎皎歌白驹，不歌长铗弹无鱼。","批风切月瘦弗腴，枕头一束知何书。","欲把列城凭轼下，馀子纷纷谩凌跨。","归来袖手如病瘖，舌在何曾问人借。","占灯夜喜傍短檠，剧谭不知山月倾。","元戎后乘沸笳鼓，之子但默黄钟声。","平地邛郲九折坂，十年已恨相逢晚。","四座悲歌漏正迟，一龛风雨花频剪。","镜里功名一横槊，百鸷啾啾空一鹗。","双玉未倾罍未耻，自倒玉山还自起。"]},{"t":"酬铦朴翁梅花 其一","f":"七言绝句","c":["槎牙绝后复重苏，绰约冲寒瘦有馀。","自是灵根钟间气，不从春力借吹嘘。"]},{"t":"酬铦朴翁梅花 其二","f":"七言绝句","c":["未利山矾亦可人，圣之和与圣之清。","由来风物须弹压，故遣孤芳集大成。"]},{"t":"酬铦朴翁梅花 其三","f":"七言绝句","c":["暗香浮动月黄昏，直与离骚力抗衡。","今日孤山山下路，对花如对老先生。"]},{"t":"酬铦朴翁梅花 其四","f":"七言绝句","c":["一枝分遣到朱门，未插铜壶已断魂。","龙液麝脐匀百和，清流难洗浊江浑。"]},{"t":"早行","f":"七言绝句","c":["鹎鴂初声戒趣装，强携瘦影度重冈。","畏途政尔吴牛喘，误把残蟾作夕阳。"]},{"t":"杨宗伯知举出院","f":"七言律诗","c":["三级桃花把要津，懿文储德在权衡。","鸾雏将授三传托，虎榜先同一瓣盟。","荣以依光如昼锦，乐于兼善胜专城。","履声早晚星辰上，弗与群仙地上行。"]},{"t":"纸帐","f":"七言绝句","c":["玉楮亭亭称冷官，晴云垂地著蒲团。","梦回不复疑胡蝶，犹记蟾枝宿广寒。"]},{"t":"柏香岩","f":"七言律诗","c":["卜筑深云榜柏香，小楼缥渺远吞江。","路随山转巧当户，潮与月来高挂窗。","得饱但惭秋稼足，爱眠嫌听晓钟撞。","明明斗劣无求胜，一任诸方建胜幢。"]},{"t":"老母元宵初度是日立春","f":"五言律诗","c":["冰鉴呵云薄，金莲照夜遥。","灰飞催腊尽，雪拥待春消。","檐已冰垂柱，山犹玉坠腰。","不知初度酒，几度酌元宵。"]},{"t":"易水行赠修和谢德之高士","f":"七言古诗","c":["悠哉招隐琅琅然，画然勇变易水寒。","槁梧语急声欲乾，哀丝欲绝回风酸。","激昂馀地涵清圜，弗落断崖清夜湍。","想当悲歌蓄真怒，发立如棘冲其冠。","慨慷一死不复惜，从容按辔无求还。","投机之间不容发，一失万古成永叹。","尘侵匕首壮士死，谁写遗恨归清弹。","谓言此曲无再弹，浑刚不敌智士肝。","脑脂盖眼日高卧，幽愤欲平良独难。","油然易感不易触，徒使壮泪双汍澜。","琴工推琴向我言，我指何自生忧端。","物能移人不移物，安得心广仍体胖。","欲令心广仍体胖，不妨试作如此观。"]},{"t":"再赠谢高士得之","f":"词","c":["我曲非俗音，亦非正始音。","阒然洞遗响，万籁俱为瘖。","有弦不足弹，无弦不足寻。","与之俱浮沈，适以写我心。","谢郎介洁弥明操，结喉深目苍髯槁。","刘生侯喜不相逢，弗联石鼎歌南风。","援琴速我城南道，为我从头写怀抱。","不是山林同苦心，更有阿谁弹得到。","曲终月堕仍反闻，欲弹不弹心自论。","小俟茶甘回齿颊，唤起胎仙舞三叠。"]},{"t":"赠悟上人","f":"楚辞体","c":["峨峨复汤汤，夭阏不可寻。","哀丝一弹绝，不救焦尾瘖。","遂使筝笛耳，喜厥郑卫淫。","划然勇为赏音废，此道未必皆平沈。","盍观薰弦育万汇，不育傲很顽嚚心。","廪完未既使浚井，仅脱死地仍床琴。","拳拳终慕不知老，放勋赏此不赏其声音。","圣贤不与我殊类，出乎其类吾所钦。","弹兮须弹古人意，学平当学有虞氏。","赠颖师者韩退之，悟师鉴赏今其谁。"]},{"t":"移兰","f":"七言律诗","c":["莸劣薰优只自强，寄林亦足称孤芳。","故应纫佩成春服，不为无人閟国香。","移傍瘦筠同雨露，怕随行苇践牛羊。","客非九畹同心事，莫反离骚吊碧湘。"]},{"t":"送客 其一","f":"七言绝句","c":["老矣无钱买沃洲，欲从苕霅问菟裘。","却烦二子先归去，好处林塘为相攸。"]},{"t":"送客 其二","f":"七言绝句","c":["欲快青眸忍白开，故将渊默自藏雷。","苕溪今日宁无昼，不见蘋吹好句来。"]},{"t":"病起","f":"七言律诗","c":["药性从前已惯谙，折铛彷佛旧同参。","无禅无道了生死，问疾问安徒再三。","人瘦可肥姑小待，宪贫非病固多惭。","起来细数檐前竹，新绿猗猗箨半含。"]},{"t":"过钱塘","f":"七言绝句","c":["初日驱阴积翳销，鹳鹅嘈杂橹初摇。","白鸥踏浪平如地，不似吴儿学弄潮。"]},{"t":"月楼陈寺簿惠李阳冰千文新刻","f":"词","c":["厥初至文无一字，谁将鸟迹分形似。","天淳屡警不知防，七凿才终混沌死。","遂令天下后世空纷纶，虫鱼钟鼎骈相新。","茫然不理字外意，但见九州四海同轨仍同文。","王郎羽化不可絷，小篆千人万人习。","祖龙无恙事如麻，稍缓簿书期会急。","西京杜门草太玄，诸儒载酒尊所闻。","莫言字是纸上语，寻古康逵须得门。","朅来小楷无馀韵，更复颠狂窥草圣。","不见当时石鼓歌，哂乃数纸博白鹅。","悠悠古恨凭谁雪，想见月楼时对月。","质衣访古锦作囊，李侯屈铁千琳琅。","百金购工镵翠琰，数间僦舍生寒光。","欲寿此书休待贾，待向君家提此话。","不图复见古人心，要与月楼同博雅。"]},{"t":"中秋","f":"七言律诗","c":["得月山房夜夜秋，仲秋既望岂常俦。","狡移三穴虽明见，圆印千江恐暗投。","于我覆盆虚镜面，为谁飞辙碾云头。","吴儿不管团如璧，只唱弯弯照几州。"]},{"t":"后中秋夕同渊清叟宗无传登觉无象宿蟾小阁","f":"七言律诗","c":["练挂河源夜欲流，略无云物碍双眸。","有时长恨菱花破，今夕何须玉斧修。","五载重逢馀闰岁，百年几见两中秋。","更舒望海亭东啸，细把穷乡令节酬。"]},{"t":"过剡 其一","f":"七言绝句","c":["曹娥泪血点江潮，百里都无绿半篙。","剡水迎潮须款曲，小分清瑩洗浑涛。"]},{"t":"过剡 其二","f":"七言绝句","c":["春涨新痕绿渐开，只知东去不西回。","濯缨莫负沧浪咏，曾送扁舟泛雪来。"]},{"t":"蜂房","f":"七言律诗","c":["各开户牖复尊王，酿熟芳鲜又绝粮。","课有常程分殿最，日无馀暇息奔忙。","酷嫌虿尾长摇毒，终使花头不损香。","细细中边分正味，莫教勤苦度韶光。"]},{"t":"清明善住蜂归用前韵","f":"七言律诗","c":["雾拥云屯畏失王，相攸来此各赍粮。","絮轻漠漠移家晚，花冷冥冥领众忙。","卒岁缓营新旨蓄，掠丛怕有欲残香。","凛然暗室明如昼，不待通天一点光。"]},{"t":"解嘲杜鹃","f":"七言绝句","c":["神武门头稳挂冠，至今犹颂二疏贤。","试将史传从头读，不说西京有杜鹃。"]},{"t":"种瓜","f":"七言绝句","c":["一亩荒园石衬沙，若为图蔓不伤瓜。","丁宁落蒂方拈出，辄莫搀先摘褪花。"]},{"t":"悼寿此山","f":"词","c":["七轴澜翻卷怒潮，九天恩重记前朝。","力鞭觳觫防侵稼，活写厓?恶吠尧。","秋幌囊萤心未老，春风吹雪鬓先彫。","青雷玉立青如削，千载高风不寂寥。"]},{"t":"花芥 其一","f":"七言绝句","c":["澹金生色染宫黄，只作坡羹亦擅场。","稚子不能供小摘，相呼扑蝶趁斜阳。"]},{"t":"花芥 其二","f":"七言绝句","c":["谢遣毡根煮菜根，雨畦晴圃驻春痕。","听它岁岁蕃孙息，百亿须弥不足吞。"]},{"t":"书平田田家壁","f":"七言绝句","c":["笭箵埏埴自陶渔，上大人题小教书。","不过乱山深处路，人间无处问唐虞。"]},{"t":"积雨","f":"七言绝句","c":["积雨低田欲再车，经旬湿稼糵寒沙。","绝怜百念如焦谷，大浸稽天不复芽。"]},{"t":"竹居","f":"七言古诗","c":["水云不羁随所寓，破包不挂无竹处。","眼前一日无此君，朽索徒将六骏御。","岂无花木事幽讨，自然南北如歧路。","苕溪阿珂秀而古，虚心囧囧云同趣。","数椽老屋傍深云，一亩清阴著环堵。","岁寒门户不胜冷，春梦池塘时得助。","坚刚老节贯凌霜，冷澹生涯不受暑。","客来烧笋然竹枝，客去呼儿纫竹布。","更制芰荷供岁晚，旋采蕨薇歌日暮。","便从此地赋真游，更把故山为别墅。","不妨月夜据胡床，细扫苔痕印芒屦。"]},{"t":"红叶 其一","f":"七言绝句","c":["猎猎翩翩赤羽旗，霜裁风剪乱零吹。","打窗便是敲篷响，梦断吴江欲冷时。"]},{"t":"红叶 其二","f":"七言绝句","c":["要与松筠共岁寒，听它青女苦彫残。","不于叶上添生色，谁辨刚中一寸丹。"]},{"t":"红叶 其三","f":"七言绝句","c":["郑老毫端醉墨浓，朝朝伛偻拾西风。","那知猩血燕脂外，尽在银钩铁画中。"]},{"t":"红叶 其四","f":"七言绝句","c":["句满山林写不成，怕缘流水误虚名。","夕阳满树牛羊下，只看玲珑血色明。"]},{"t":"红叶 其五","f":"七言绝句","c":["趁得晴秋作许妍，动人春色政秋寒。","林塘水冷溪痕瘦，镜里何曾欠渥丹。"]},{"t":"红叶 其六","f":"七言绝句","c":["树下收帆系断航，树头新染夜来霜。","小春未凛犹相贷，款曲辞柯不要忙。"]},{"t":"益老得广惠呈制帅大资槔闲居士","f":"七言律诗","c":["客已梅山访把茆，城隅闲锁一枝巢。","金园俗下谬公举，玉帐眼明寻淡交。","不但据鞍尤矍铄，尚堪策蹇作推敲。","采毫不借江山助，谁为高人赋解嘲。"]},{"t":"圆明后葬者居祖塔前属寺僧树表以识之","f":"七言律诗","c":["小桥南北尽僧居，彷佛天花傍镜湖。","支遁厩中多养骏，丈人屋上试占乌。","轩窗面面云痕湿，楼观层层水影孤。","惆怅门前一抔土，倩谁封殖戒樵苏。"]},{"t":"万卷堂","f":"词","c":["吾闻先进之野人，耕养之外三年通一经。","区区三六一十有八载，六经未必皆知津。","猎猎牙签三万轴，当时想见从头读。","若将有限趁无穷，偃鼠饮河徒满腹。","何如一笑俱忘言，文字洗空如露蝉。","等闲一嗅尽其要，萧郎馀习三生前。","万卷堂中浩如海，一点胸中无芥蒂。","茏葱初日上阑干，坦腹便便日中晒。"]},{"t":"西湖夜归观打鱼怀赵京兆","f":"七言古诗","c":["德人天游乐者全，亦以此乐均鱼鸢。","陶然亦复忘所乐，西湖澄澈如心渊。","管领西湖人不少，前后无如赵京兆。","至今画手画西湖，不著绿蓑人独钓。","胡为今夜月满湖，大船小船皆得鱼。","鱼登罔罟叫不得，那知老子今归欤。","滔滔京兆万人海，平地翻涛渺无盖。","活鱼之外尤活人，人在甘棠颂遗爱。"]},{"t":"墨梅 其一","f":"七言绝句","c":["描邈檀栾黪素元，万红千紫失根源。","大玄自古人嫌白，白尽何妨反太玄。"]},{"t":"墨梅 其二","f":"七言绝句","c":["楚楚仙裳澹染缁，耐寒宜瘦不宜肥。","莫言无子调商鼎，卿相当年有黑衣。"]},{"t":"墨梅 其三","f":"七言绝句","c":["省力寻春愈出奇，窥篷图上看新诗。","杀风景问春知否，两手风霜一样龟。"]},{"t":"墨梅 其四","f":"七言绝句","c":["莫恨丹青废画工，不须求异只须同。","玉容弗及寒鸦色，故托缁尘异汉宫。"]},{"t":"墨竹","f":"七言绝句","c":["搜搅微茫到物初，解衣盘礴便扶疏。","岁寒节节曾参透，不负刚明一寸虚。"]},{"t":"送道州使君江西张正父","f":"七言律诗","c":["词学清流属上游，可曾轻外叹迟留。","半生萧洒居仁宅，千骑精明赴道州。","曾拟朝阳鸣老凤，暂从楚水问盟鸥。","不妨高索山人贾，款曲归来尽黑头。"]},{"t":"客去","f":"七言律诗","c":["茗椀篝灯自校雠，长歌伐木啸吟俦。","九回断续珠难度，八月凄凉燕不留。","夜雨忆同湖上榻，旧题曾拂涧西楼。","破囊犹有新篇在，辄莫逢人说暗投。"]},{"t":"佛手岩雨过","f":"七言古诗","c":["白云裹山裹不尽，高处露头低露胫。","一条悬水透云飞，雪色蜿蜒伸脊领。","画然怒卷风霆震，银鱲玉鳞俱奋迅。","滂然才歇四山明，湿尽悠悠云万顷。","是时豁达纵双明，岩巘更无毫发隐。","太华岿然不较多，直上削成五千仞。","想应有路近丹梯，未必无花开玉井。","便欲搴花供岁晚，更揽藕根刳短艇。","径上明河欲尽头，块藐九州聊一瞬。"]},{"t":"飞湍","f":"七言古诗","c":["飞湍衮衮飞当户，平地隆隆万鼍鼓。","澎轰乱石震风霆，崩奔千仞无朝莫。","涛神何许驾潮来，馀愤未平方震怒。","又若飞廉声万窍，馀勇尚多无处贾。","年时旱涸尚如此，况当八月九月雨。","渊潜虽伏不能安，林栖欲寐还惊顾。","山翁惯听如不闻，只应自乐山中趣。","对床展转悲游子，咫尺华胥迷去路。","欲随胡蝶翩翩举，空过夜遥忘栩栩。","起来晨炊恶草具，误作迅雷仍失箸。","呼童秣马不少驻，不待黎明出山去。","出山定入红尘去，欲去谓言姑小住。","此声不似郑声淫，聒耳虽喧君勿恶。"]},{"t":"雨后山水入潮江方岩索赋","f":"七言绝句","c":["湍雪投江只得浑，观澜未了复消魂。","不知从此随流去，清白何时得反元。"]},{"t":"海庄观稼","f":"七言绝句","c":["东输三十六溪湍，海若谽谺不足吞。","我有黄云连断岸，夜深随月看潮痕。"]},{"t":"方岩王侍郎江西破贼归 其一","f":"七言绝句","c":["大厦难将一木支，驾言孺子托心期。","绝怜十八滩头树，不管安危管别离。"]},{"t":"方岩王侍郎江西破贼归 其二","f":"七言绝句","c":["左蠡扬澜草葑湖，轴轳衔尾碍前驱。","苇航摺叠多馀地，潜伏骞腾在卷舒。"]},{"t":"刘改之题王总干虏中怀亲帖拉朴翁与余同赋","f":"七言律诗","c":["白云起处感亲深，故倚西风动越吟。","送老有田非住计，欲飞无翼是归心。","强随邻里虽胡语，自教琵琶只汉音。","玉瘗遐荒元不死，夜干牛斗尚千寻。"]},{"t":"方岩惠蕉丝布","f":"五言律诗","c":["绿趁桄榔剪，黄如柘茧抽。","海绡云湛染，鲁缟玉温柔。","待月投清夜，炊菰梦冷秋。","直然无可报，杂佩不中酬。"]},{"t":"舟中酬竹岩","f":"七言绝句","c":["官船只合办清游，却载蛩声雨夜愁。","明日蓼花蘋叶上，不知辏得几分秋。"]},{"t":"松花","f":"七言绝句","c":["都将坠粉扫残枝，聊伴伊蒲簪蕨薇。","合赋老饕矜厚享，秋池更有芰荷衣。"]},{"t":"候钱蜕堂","f":"七言古诗","c":["属闻旌节西南归，跨剑越栈窥峨眉。","便将峨眉软庐阜，孔明十倍于曹丕。","怀哉西南一万里，日者庸人扰之耳。","豁然天地复清明，断自葛韦遗俗起。","我寻竹岩踏雪来，好怀尽为江山开。","人物于人尤不恶，更于众角寻麟角。"]},{"t":"松风阁","f":"七言古诗","c":["绕檐恶木方童童，苍官著脚将焉从。","海涛熨帖清涵空，不见蘋末来蓬蓬。","是时散衣阑独倚，不晓此中题榜意。","但见茫茫涨软红，扑满市人乌帽底。","蜀仙茶鼎扛无人，寥寥不复闻此声。","玉川凉夜更渺邈，飕飕只今无地生。","尚怜芳草春池句，梦破客儿烦举似。","夺胎换骨蜕氛埃，丛霄九万泠然去。"]},{"t":"踯躅","f":"七言绝句","c":["露凝丹脸粲芳肌，不御铅华亦自奇。","强学海棠春睡足，如何学得未醒时。"]},{"t":"春江曲","f":"七言绝句","c":["十里西江日日佳，回汀曲渚艳春华。","秋来等得明如练，未必蒲花似柳花。"]},{"t":"赠笔工","f":"七言绝句","c":["护惜神锋逮缺残，回观败冢只潸然。","只今汗血无人问，朽骨成山直几钱。"]},{"t":"刘簿分赐茶","f":"七言古诗","c":["吁嗟草木之擅场，政和御焙登俊良。","双龙小凤取巧制，断璧零圭誇袭藏。","晴窗团玉手自碾，旋熁铁坏玄兔盏。","瓦瓶只候蚯蚓泣，不复浪惊浮俗眼。","卯金之子我所识，户外青藜扶太一。","十袭携来访赏音，清白犹能胜黄白。","君家阿伶两眼花，以德颂酒不颂茶。","遂令手阅三百片，风味尽在山人家。","潮从委羽山前涨，少得清涟入瓶盎。","瓢瀹天浆睡足时，香演丝纶九天上。"]},{"t":"笑轩沈仲归挽章","f":"七言律诗","c":["尊周微意托炎刘，秽史端令后世羞。","不把遗经究终始，安知吾志在春秋。","虹霓未吐身先老，龟手空传自不侯。","奏赋长杨上天去，断编残简乱山丘。"]},{"t":"黄侍郎帅闽解后皎如晦受业寺","f":"七言律诗","c":["送客稽山欲尽头，丁宁一语驻骅骝。","荔枝莫惜轻红擘，醽醁何妨大白浮。","语必惊人休散失，才多在野细寻搜。","此怀只合从公赋，说与它人定暗投。"]},{"t":"蕙林","f":"五言古诗","c":["薰有腾芳蕙，莸无砌埒金。","绿窗涵一镜，朱户掩双岑。","度土观肥瘠，移根较浅深。","不愁新绿暗，长恐软红侵。","剪翠滋繁露，留芬引碧浔。","芝兰元并德，姚魏不同心。","暑战知勍敌，霜零抚壮襟。","晓梳风猎猎，晚沐雨森森。","草色分春思，苔痕借夕阴。","缀丛流夜照，拥砌递秋吟。","佳树青油幕，幽泉绿绮琴。","帐空从鹤怨，盟在听鸥寻。","触胜齐蛮负，骚亡甚雅沉。","吮香须细写，搔短惬芳簪。","野逸勤招隐，清狂苦不禁。","悠然饱风味，送目挂岑崟。"]},{"t":"夜泊故山 其一","f":"七言绝句","c":["群峰雪后尚崔嵬，行尽黄昏不见梅。","独有故庐山数曲，殷勤推月过溪来。"]},{"t":"夜泊故山 其二","f":"七言绝句","c":["略彴横溪度笋舆，稚松孙竹半蓁芜。","呼童相伴锄明月，缺处重添一两株。"]},{"t":"己巳元宵种松庆母生初","f":"七言律诗","c":["白发生初庆此朝，手移松桂上岧峣。","要知雪操寒尤劲，长伴庭萱老不彫。","牲养独惭亏夙志，綵衣犹记舞元宵。","旋添万本青青色，小作寒江涨怒潮。"]},{"t":"曹侯旧作题红扇子永嘉陈原父得之","f":"七言绝句","c":["未将心事付题红，已有灵犀一点通。","采笔春归横槊后，高情都属小元龙。"]},{"t":"晚归","f":"七言绝句","c":["晚凉初试出严城，云表浮图恰上灯。","归棹只知将月去，不知摇碎玉棱棱。"]},{"t":"一犁春雨图","f":"七言古诗","c":["谢家风流绝代无，底事要作耕田夫。","一犁春雨开新图，此图之作胡为乎。","莫是天民先觉者，小试经纶起莘野。","复将斯道觉斯民，千载精神入模写。","不然渊明赋归后，荷锄去种南山豆。","晚风新霁擢良苗，一段风光相授受。","扣之辄笑横点头，老农老圃吾何求。","六经芜翳力穮蓘，百王理乱深锄耰。","剪剪茆茨出林罅，菽水清欢在其下。","圣贤所乐属吾庐，当观吾庐莫观图。"]},{"t":"朴翁加冠巾苏召叟讶予不嘲之","f":"七言律诗","c":["见与闻同骇且猜，多应自断不佗裁。","聪明断种岂僧事，矍铄据鞍须将才。","好在夕阳愁夜近，怀哉鲵齿尚心孩。","自非独善林泉懒，应是林泉少祸媒。"]},{"t":"酬水心叶待制见寄宿觉庵记并诗","f":"五言律诗","c":["天藏今偶得，人杰古犹存。","莫遣苔封径，宁教竹碍门。","市喧酣蚁战，潮晚看鲸吞。","金粟元非病，何妨一驾言。"]},{"t":"中津","f":"七言绝句","c":["帆挂中津趁落潮，且停双桨不须摇。","却将中散凭阑意，直送孤鸿到玉霄。"]},{"t":"吴江道中","f":"七言绝句","c":["蔓滋螟螣燕孙谋，争得嫠砧不怨秋。","筑圃莫嫌登稼少，尚馀荞麦趁霜收。"]},{"t":"牧童","f":"七言绝句","c":["蓬松袒跣倒骑牛，折得山花便满头。","强使倡歌浑不听，听它天籁自鸣休。"]},{"t":"秀侍者?蕈","f":"七言古诗","c":["葵藿不甘羊酪膻，笋蕨隽永非薨鲜。","树鸡风度扫藜苋，盖其氏者尤称贤。","敷腴孕秀茁枯朽，软湿不齐相后先。","春风薰陶紫芝秀，陆地挺特荷钱圆。","虽非灵椿八千岁，要与风月三千篇。","古源阿棠文人行，荐新已办罗百笾。","开端慷慨约同饷，一语不移金石坚。","过门走致演纶手，不记旧约篝灯前。","小空在左辄反睨，解衣作质呼芳鲜。","晓罂嫩汲井花水，地炉瓦鼎相周旋。","蒲萄馀沥正其味，盐醯不御全乎天。","缀盂独当第一义，曾水洗空十万钱。","不须沆瀣更疏瀹，欲跨明月凌风烟。"]},{"t":"樵谷","f":"七言绝句","c":["谷口云横草不生，弗容斤斧弗容耕。","呼童尽拾风前叶，自去提撕折脚铛。"]},{"t":"霅川","f":"七言绝句","c":["茅茨傍水似浮家，自把蘋洲缺处畬。","鱼菜常多蔬菜少，荠根挑尽到芦芽。"]},{"t":"酬于君实","f":"七言律诗","c":["新有吴霜著鬓颠，却无俗驾到门前。","试寻池草生春思，不为楼钟废晓眠。","葵苦易荒锄短日，豆甘多种廪残年。","家生冷淡尤堪笑，却怕炎炎又可怜。"]},{"t":"骥无称筑墙护放生池","f":"七言律诗","c":["凿山樊圃幻屏帷，自出胸中一段奇。","拓寿域归常住地，注恩波入放生池。","剪蒿忍放蛙分部，空穴宁教兔不疑。","坐看春风归约勒，先开墙角向南枝。"]},{"t":"贫乐堂","f":"七言绝句","c":["瓦盂脱粟自成歌，直与箪瓢不较多。","弗恨道人贫似我，却嫌所乐弗如它。"]},{"t":"潘子善范先之林自知赋木犀嘱和","f":"五言古诗","c":["孤芳如阿平，晚乃出六奇。","傍睨肃听瑩，请试从元推。","韵如圣之清，避世观商衰。","翠幄方童童，露叶流蟾辉。","降真换骨法，谱牒当寻披。","悠悠千斛香，鲜风如驲驰。","霪秋百草死，不复干等威。","江蓠交晚生，楚英托深知。","罗柳追逸驾，峻坂方驱羸。","尤物能移人，心正物自移。","年年月中仙，一人簪一枝。","后先不须问，亦各安其时。"]},{"t":"贷粟 其一","f":"五言律诗","c":["我有一斗粟，不暇春作糜。","宁受藜苋诳，不忍刚肠嘶。","要果天下腹，吾饥吾敢辞。","长愿饱者饱，毋使饥人饥。"]},{"t":"贷粟 其二","f":"五言律诗","c":["古之圣之清，吾独称夷齐。","采薇替周粟，所乐甘如饴。","山亦不义山，薇亦不义薇。","惟其不素食，食粟令人思。"]},{"t":"今岁兰柳相先梅最后 其一","f":"七言绝句","c":["稍殿金丝与紫茎，骎骎躐等败清盟。","白鸥认得横斜影，应对清流诉不平。"]},{"t":"今岁兰柳相先梅最后 其二","f":"七言绝句","c":["长是年年趁雪妍，一鞭迟著笑今年。","姓名虽在百花上，终不敢为天下先。"]},{"t":"雪中访别魏使君 其一","f":"七言绝句","c":["踏雪寻春计亦优，不如去款魏君侯。","雪裘风帽台州去，岂是无才入蔡州。"]},{"t":"雪中访别魏使君 其二","f":"七言绝句","c":["大雅离骚不入时，反骚变雅又奚为。","天台好处休提掇，只咏寒山拾得诗。"]},{"t":"晚归遇雪","f":"七言律诗","c":["集霰缤缤趁雨飘，回风籍籍委江郊。","重阴冻锁天无畛，一眼平铺池不坳。","直恐径迷随意扫，又疑竹裂带寒敲。","倚阑欲看连云色，更待黄昏桂影交。"]},{"t":"山阴道中残雪","f":"七言律诗","c":["晃眼鲜明未寂寥，江村犹自碍渔樵。","积阴虽重消平地，背日犹多压小桥。","抢地竹头扶眩起，种畬山脚望晴烧。","天诛螟螣躬行罚，杀气回春款款消。"]},{"t":"与应真遇","f":"词","c":["神游八极乘风车，小复按辔凌谽谺。","龙湫下瞰不咫尺，下有深窦无底无津涯。","应真长年一扪膝，俯观尘滓井底蛙。","朝来岩室忽阒寂，水流山空鹊槎槎。","浮云出岫杳杳不可絷，锡声小振巅云丫。","问之何以出山去，一笑不知山日斜。","共看八纮净如洗，五云明洁从东嘉。","山川所钟一人耳，半千千载何其遐。","经纶才大辅以德，八斗一石初何加。","天公不忍世寂寞，憖遗一老为国华。","一经指授豹则虎，未获印可龙仍蛇。","去寻宿觉言外意，助发康乐毫端花。","粲然颖脱世间语，简古佶屈仍聱牙。","称扬此老长不老，岂惮弱水蓬莱赊。","纶巾羽扇凛如画，恍然来泛丛霄楂。","群仙奔走敬且肃，百神呵护严不哗。","知公醉经不以酒，玉盌自浇新露芽。","谓言正传仅如缕，邪说诐行纷于麻。","正音一震击聋瞽，洗空乱耳秋池蛙。","廉隅道丧日滋甚，习俗侈靡相矜誇。","清风俭德起颓俗，革去极侈仍穷奢。","黄金羁勒驾款段，青丝络头闲渥洼。","小施尺箠试鞭策，驽骥庶毋遗等差。","振衣小作一年别，伛指盈阙之虾蟆。"]},{"t":"送方岩出帅平峒寇 其一","f":"七言律诗","c":["草木犹知旧姓名，妖狐折胆在先声。","乡来笔下三千字，今日胸中十万兵。","直把文章为小技，横遮江汉隐长城。","油幢坐啸祛锋镝，六合清风白羽生。"]},{"t":"送方岩出帅平峒寇 其二","f":"七言律诗","c":["漠漠江城度柳花，江南春事又天涯。","绿抽秧颖秋占稼，碧凝檀云晚未衙。","风动十连咸自化，夜严千灶静无哗。","书生只事毛锥子，试把轻裘缓带誇。"]},{"t":"许由观","f":"七言绝句","c":["万乘何曾换一瓢，羽成玉骨蜕尘嚣。","是非到耳虽无迹，颍水何曾洗得消。"]},{"t":"舟中","f":"七言绝句","c":["曝背初从晓日开，当时曾说献君来。","船头亦有茆檐暖，准拟排云又一回。"]},{"t":"下池 其一","f":"七言绝句","c":["漾漾璇题湛镜光，团团素璧剪方方。","一抔曾勺蟾蜍玉，犹带仇池翰墨香。"]},{"t":"下池 其二","f":"七言绝句","c":["老子随行苜蓿盘，不曾无客自开单。","更将馀粒投清浅，聊为游鱼小倚阑。"]},{"t":"酬竹岩江湖伟观","f":"五言古诗","c":["伟观如伟人，特立万夫上。","胸中九云梦，浩然老益壮。","挂窗著孤山，排闼数秦望。","平湖宜阴晴，西子亦澜浪。","江潮齐晦朔，海若见情状。","由来非地献，亦复岂天相。","谁将万象影，幻此千幅怅。","悠然会真意，何以堪俗况。","曲阑供小立，双眸纵遐放。","空濛辨畛畦，平漫分趣尚。","外则尽诸物，内则了诸妄。","何妨水涵空，勿使云塞向。","不须陋狭隘，更复事宽旷。","湛此一寸虚，秘发千古藏。"]},{"t":"圆方外明伟室","f":"五言古诗","c":["沙砾不自汰，清明日遄逝。","充此一寸虚，八纮静无翳。","天风卷沧溟，涛山郁岧峣。","悠然一沤灭，中有湛不摇。","方其澄湛时，十日洞无际。","用晦乃全功，何妨九乌毙。"]},{"t":"魏宪使石笋小筑 其一","f":"七言绝句","c":["住山做得淡生涯，泉有金沙与白沙。","自课小童城市去，归来煮饭又煎茶。"]},{"t":"魏宪使石笋小筑 其二","f":"七言绝句","c":["野芳佳木自衡斜，约勒春风占物华。","聊复避喧非避世，种桃不似种梅花。"]},{"t":"泉上苔梅方著一花 其一","f":"七言绝句","c":["华风先试老茶牙，煖破苍苔著一花。","浅浅石泉都冻了，不容疏影浸横斜。"]},{"t":"泉上苔梅方著一花 其二","f":"七言绝句","c":["冰锁寒泓湛不摇，瘦枝无力闯春饶。","风中鲜馥来无迹，一点乾酥冻不消。"]},{"t":"盆蕉盆稼各一首 其一","f":"七言律诗","c":["不才脆弱自天全，亦既它怜复自怜。","根托器盛宜瘦小，叶从心展看芳鲜。","近听似有秋声远，侧卷都无露点圆。","时把短屏遮凤尾，不教细字上蛮笺。"]},{"t":"盆蕉盆稼各一首 其二","f":"七言律诗","c":["尺水涵空镜不尘，晚秧疏密政亭匀。","叶膏微雨潜分润，手栉鲜风不厌频。","万斛堂堂嗟既没，数茎矗矗喜怀新。","钵盂只靠家田饭，薄享无功弗愧人。"]},{"t":"野步","f":"七言绝句","c":["岭上人归欲寄梅，岭根流水隔尘埃。","水中忽见胡麻饭，不入桃源便出来。"]},{"t":"迓回庵谯卿持节东浙","f":"五言古诗","c":["廷尉天下平，轩轾论锱铢。","时称无冤民，传载西京于。","旧史读至此，遗恨辄有馀。","元康神爵间，赵盖靡其躯。","陵迟至五凤，继以韩杨诛。","孝宣不足道，定国其争乎。","不得言则去，何苦但嗫嚅。","大哉平恕心，至是果有诸。","公乎开禧末，定见了万殊。","大本固易拔，滋蔓非难图。","在辟疑惟轻，寸田斋以虚。","触藩岂无羝，漏网固有鱼。","执中事宽大，吹春苏槁枯。","近者获自新，远者免自洿。","至仁不胜用，盛德多阴储。","一节雄东藩，六月驰轺车。","歌谣沸先声，弩矢观前驱。","清风方泠然，列城斯凛如。","民物破郁陶，云翳亦展舒。","敛此一道惠，归为商鼎需。"]},{"t":"贺李临海雨","f":"词","c":["唤得蜿蜒觉黑甜，油然云气起沉潜。","一声霹雳飞寥泬，三日霶?洗赫炎。","水足旧畦仍浸闸，夜凉新月又窥檐。","令君后乐先黎庶，大有今年不再占。"]},{"t":"冷泉待月 其一","f":"七言绝句","c":["犹自单衣怯夜阑，不风亭户子声乾。","平生知己莲峰月，不为衣单不倚栏。"]},{"t":"冷泉待月 其二","f":"七言绝句","c":["闸住亭前绿半篙，泉中白兔眇秋毫。","庾楼自是当年好，番袜工夫合反骚。"]},{"t":"冷泉待月 其三","f":"七言绝句","c":["眩转金波凝不阑，特寻佳处阁团团。","南飞乌鹊噇眠去，独与飞来小朵看。"]},{"t":"金鳌山御榻","f":"七言律诗","c":["丁未龙飞动四溟，惊涛曾岂碍扬舲。","抃鳌不露黄金背，跨岸谁开白玉京。","环扈翠华驱海若，勒回钓艇问山灵。","暮钟万岁千秋颂，澄彻尧聪得细聆。"]},{"t":"高潮庄中秋","f":"七言律诗","c":["贯见冰盘出海山，可曾海上看团团。","全潮退舍开平地，万里无云展素纨。","冷怯单衣沾沆瀣，皎如白昼数峰峦。","败荷深荡僧归去，髣髴西湖画里看。"]},{"t":"题永嘉杨孟均巫山图","f":"七言绝句","c":["部领群峰压小巫，阳台犹自雪模糊。","若教指点猿啼处，判得刚肠百断无。"]},{"t":"蒙泉","f":"五言古诗","c":["坎井只丈寻，得名由参寥。","丈人玄豹姿，养德富不骄。","想当发泉蒙，如此湛弗摇。","珠明水增媚，镜净尘当消。","陶泓勺馀沥，采笔生春潮。","止则云沉沉，涨则桃夭夭。","淘趁槐火新，战与坡仙挑。","坛拜十四字，高山郁岧峣。","灯灺谩图续，些苦何能招。","须公起九原，为我饮一瓢。","于戏不可作，仰止苍崖腰。"]},{"t":"酬子寿谢宫使七夕见寄","f":"五言古诗","c":["吾门开康庄，吾心洞秋旻。","泓澄湛无底，方寸无涯津。","美人隔秋水，数月一合并。","昨宵七月七，游子脚不停。","仰看乌鹊桥，遥盼牛女星。","吁天致私祷，席地罗广庭。","乞巧问天孙，逐物昧己灵。","齐东田野间，语言殊不经。","夫何古犹今，竞作奔奔鹑。","玉霄眇空阔，银汉横青冥。","不须赋解嘲，且复歌闲情。"]},{"t":"霜柳","f":"七言绝句","c":["春傍垂杨困得醒，池塘部曲顿精明。","褪寒欲试鹅儿浅，商略工夫苦未成。"]},{"t":"双头兰","f":"七言绝句","c":["艾拥萧陵雪未消，蒂连芳萼闯春饶。","国香不似倾城色，寂寞空山大小乔。"]},{"t":"落梅","f":"七言绝句","c":["一点消磨几许春，苔生新绿衬残馨。","忍看卷地随风去，不忍儿童扫乱零。"]},{"t":"如隐","f":"五言古诗","c":["堂堂伟冠衣，琅琅歌紫芝。","洗空绮纨习，政恐富贵逼。","富贵安在哉，一笑付倘来。","不来亦不觅，不直水一杯。","小圃时时开，不待春登台。","俗驾驱尘埃，合为山灵回。","隐非盛世事，说与隐君子。","未尽碧山鱼，此隐诚何如。"]},{"t":"和素斋口占兼简戆庵","f":"七言律诗","c":["岸巾斜日倚庭柯，调度疏明似小坡。","长铗不弹秋寂寞，短檠更问夜如何。","青云旧约联镳上，白苧新闻对酒歌。","秉钺登坛谁独步，今淮阴更办多多。"]},{"t":"万年寺前古杉","f":"七言律诗","c":["千载万年门外树，铜柯铁干古髯须。","鹤归空误单华表，鹿走徒羞五大夫。","自厚本根虽磊砢，不烦枝叶衒敷腴。","栋梁大厦知多少，落落群空只一株。"]},{"t":"罗汉岭上古杉","f":"五言律诗","c":["一亩蔽苍苔，昙猷手自栽。","滴高零露馥，蟠厚烈风哀。","黛色垂云黑，丹心阅世灰。","儿孙几度老，独立暝云隈。"]},{"t":"酬金陵吴别驾","f":"七言绝句","c":["乡来王谢不传衣，只有乌衣乌鹊知。","无限去思无处系，断魂长是燕归时。"]},{"t":"盆荷","f":"七言绝句","c":["萍粘老瓦水涵天，数叶田田小帖钱。","才大古来无处用，不须十丈藕如船。"]},{"t":"池上","f":"七言绝句","c":["冰澌漱齿夜生寒，白苧生裁踏月残。","水面有风人不见，只教荷气上阑干。"]},{"t":"寄杨大监","f":"五言古诗","c":["商飙流西金，万卉寒如灰。","广寒烂银阙，初放蟾枝开。","一花堕九地，四海无纤埃。","钟作河岳灵，挺此梁栋才。","倘可济巨川，不然为盐梅。","我欲问此翁，山林起摧颓。","勺以长安酤，大白非鲸杯。","擘麟配万钱，鸟爪去不回。","抑以颂与箴，耸德如徂徕。","赋岂料敌手，吟非横槊才。","不如姑置之，高卧深云隈。","长啸揖箕翼，更把灵椿栽。","明年紫荷橐，此约当重来。"]},{"t":"次张文昌送川张道人韵","f":"五言律诗","c":["万水绕千山，翩然去不难。","双明元自碧，方寸为谁丹。","鹤化曾留句，凫轻欲振翰。","不知藏世界，一粟几何宽。"]},{"t":"楼大参嘱珣起宗索孤山旧藁 其一","f":"七言律诗","c":["旧赋梅花欲反骚，效颦徒自不偿劳。","未寻处士孤山梦，误得先生一字褒。","剪剪衰兰甘草莽，朣朣华月在林皋。","从来平地神仙脚，咫尺钧衡步武高。"]},{"t":"楼大参嘱珣起宗索孤山旧藁 其二","f":"七言律诗","c":["乡来文字汹涛澜，淼淼回渊搅不浑。","鼎鼐饱参梅子熟，雪霜不见竹枝蕃。","愧无攻处心尤小，力丐归时德更尊。","云静八纮天在水，华风煖处见春痕。"]},{"t":"圆无外一春不归兰犹有花","f":"七言绝句","c":["一春寂寞无人问，不为无人不谨初。","犹有两花藏叶底，隙檐三见月如梳。"]},{"t":"韩寺遗墟","f":"七言绝句","c":["十年秋傍故山零，一坞残云夜不扃。","土偶向人犹作祟，相传不似旧时灵。"]},{"t":"书荆公访僧图","f":"七言绝句","c":["长须瘦蹇策深云，来就蒲团到夕曛。","畴曩山中无此画，至今猿鹤怨移文。"]},{"t":"冷湾","f":"七言绝句","c":["怪雨盲风塞冷湾，破头艇子出湖滩。","平生无地酬忠信，独向风波险处看。"]},{"t":"赵节推挂冠 其一","f":"七言律诗","c":["不为鲈鱼不为莼，只思天际九华青。","心关幽事惟招隐，脚到荣途亟引龄。","营掾廨成才燕贺，笑虞罗巧叹鸿冥。","乐闲趁得身强健，振厉仙源擅德馨。"]},{"t":"赵节推挂冠 其二","f":"七言律诗","c":["虚舟所至信浮沉，揭厉何曾较浅深。","坚不可磨惟定见，去终难挽是归心。","书生岂但青衫债，俗子安知绿绮音。","神武门头旧时月，照人如镜古犹今。"]},{"t":"国清寺绝顶更好亭下古梅","f":"词","c":["花开更好亭前枝，亭曰更好花更奇。","我犹未到春已到，春不到此将焉归。","千山万山俨环抱，一树两树藏嵚?。","晓妆弗受朱粉污，老去自著莓苔衣。","澹交霜髯与苍玉，雅宜茅舍横疏篱。","云英风味有馀裕，石鲸鳞甲饶华滋。","恍然罗浮月中见，髿髿绀发森冰肌。","又如大窖冻不死，凛凛素节无瑕疵。","纷纷红紫不解事，与春角逐何迟迟。","待文作兴不足道，凡民碌碌终奚为。","孤芳拔俗千万丈，未暇相与论襟期。","贞姿皓态美无度，幽意独许鲜风知。","悠然凭高一披拂，僧窗处处开晴霏。","窗间跏趺拥风叶，照几碧眸岩电驰。","渊渊方寸湛古井，一沤不动清涟漪。","天香閟此无尽藏，潜于鼻观通几微。","水流山空但自笑，理与神遇端如斯。","乡来孤山水清浅，龟肤鹤膝相参差。","青铜盘屈破香雪，紫铁矫揉骈明玑。","膏肓泉石政为此，冠冕草木今其谁。","天公亦复加靳惜，阔著湖水无边涯。","八篇只遣处士赋，一点不放红尘飞。","是中泉石固深秀，惜欠晴湖山四围。","客如我辈亦不恶，拟赓疏影横斜诗。","后车合改效颦辙，亦若佩弦仍佩韦。"]},{"t":"小圃即事四首 其一 杏花著风","f":"七言绝句","c":["粉红蓓蕾弗禁吹，尽拾鲜英缀旧枝。","欲赋惜春麾巽二，形容不到未开时。"]},{"t":"小圃即事四首 其二 桃花著雨","f":"七言绝句","c":["恰则夭夭看小桃，靓妆撚指九分消。","丁宁更耐明朝雨，款曲随风送落潮。"]},{"t":"小圃即事四首 其三 李花耀月","f":"七言绝句","c":["练帨新裁衬缟衣，暝云垂地拥瑶姬。","自知素洁难谐俗，只赴梨花淡月期。"]},{"t":"小圃即事四首 其四 芳径初日","f":"七言绝句","c":["白白红红短短篱，自锄芳径简繁枝。","羲皇向上渊明老，此段家风说与谁。"]},{"t":"移棕榈次蓬山兄韵","f":"七言律诗","c":["丛拍苍柄顶春寒，诗史题名胜得仙。","剪出鳞皴仍节节，何曾拥肿到便便。","更无曲处连黄壤，只欠横枝架老禅。","来岁子鱼分树艺，檐前清影赋联绵。"]},{"t":"闻陈无却辞钱丞相道堂","f":"七言律诗","c":["挂堂钱了不求馀，熟处工夫放得疏。","逐客未行丞相令，绝交先作孔方书。","富非贫乐人皆笑，去似留轻絮不如。","采采蕨薇歌日暮，也胜弹铗叹无鱼。"]},{"t":"送周教授兼简刘左史薛寺丞 其一","f":"五言律诗","c":["舍选诸生出，侯藩博士归。","一官甘独冷，千仞看群飞。","苦学丹心古，春风泮水肥。","传衣观岁晚，先使识抠衣。"]},{"t":"送周教授兼简刘左史薛寺丞 其二","f":"五言律诗","c":["霜趁残秋肃，寒侵薄暮生。","帆开吴浪急，鸿挟楚云横。","客里常加饭，人归得寄声。","为询刘与薛，江汉几长城。"]},{"t":"揖山楼","f":"词","c":["溪阴留云云不留，楼在五云之上游。","青天一握净如洗，好山四面清涵秋。","主人亦有大白浮，揖逊群峰相献酬。","岩中野逸皆名流，农隙颇复登临不。","何当天风吹袖寒飕飗，披衡跨霍迤逦昆崙丘。","悠悠按辔双龙湫，泠然为君上上头。","楼头风物须盟主，风骚之外吾无取。","猛拍阑干抚寥泬，不问青天问华月。"]},{"t":"双溪潮水清","f":"七言绝句","c":["灭影双溪死便烧，年年枫落见清潮。","浙江亭下晴翻雪，卷作浑涛怒不消。"]},{"t":"朴翁约效诚斋分题得月色","f":"七言绝句","c":["霜晴如此月明何，独恨空庭著不多。","窗外楼头都有了，其馀四散尽从它。"]},{"t":"赠心上人","f":"七言绝句","c":["一抹新霜雁背寒，满庭疏雨客衣单。","苦心莫负韦编绝，岁晚归来语夜阑。"]},{"t":"闻济妙高为善净攘其居兼简杨守慈湖 其一","f":"五言律诗","c":["俗习翻新样，民生先故吾。","缁云忘揖逊，何处有廉隅。","戛戛难穷鼠，纷纷莫辨乌。","多应风化首，坐啸答歌襦。"]},{"t":"闻济妙高为善净攘其居兼简杨守慈湖 其二","f":"五言律诗","c":["听鼓噇箪食，逢山办把茅。","雾窗闲自挂，月槛许谁敲。","战蚁翻侯国，驱鸠入鹊巢。","先生河汉辩，何以解人嘲。"]},{"t":"酬云卧白鸡","f":"七言绝句","c":["冠染丹砂雪剪翎，不因风雨废常鸣。","有时失度无人醒，只有刘琨与祖生。"]},{"t":"谒樊将军舞阳侯庙","f":"七言古诗","c":["萧曹笔削宏楷模，良平智略吞万夫。","巍坛既登跨下士，贡帐谩悦骊山徒。","龙争虎斗爪牙备，刘怯项勇天渊殊。","鹿虽未果死谁手，鼎已潜知开汉图。","将军最先得所托，亭长之外无贞符。","逸群拔萃一人耳，屠城斩将群雄俱。","鸿门直入缓危急，虎口仅免才斯须。","宴安鸩毒寤主意，排闼紫禁当前驱。","奋身不顾但爱死，婴鳞未了仍编须。","帝虽寡恩少善后，吾宁守义如厥初。","匈奴无故遗嫚书，在廷如堵方嗫嚅。","将军裂眦不愿馀，请十万众行匈奴。","不知十万行匈奴，果与卫霍功何如。"]},{"t":"酬王哦松八景 其一 赤壁泛月","f":"七言绝句","c":["横玉临江展碧纨，冯夷庭院水晶寒。","天教两赋酬风雅，不谓人閒作画看。"]},{"t":"酬王哦松八景 其二 庐山霁色","f":"七言绝句","c":["欲从山北驻晴霏，先与山南淡扫眉。","见说商周遗俗在，试寻康俗未来时。"]},{"t":"酬王哦松八景 其三 潇湘雨过","f":"七言绝句","c":["雨歇江空锦瑟鸣，亟图清绝些湘灵。","斯须云敛便有月，更著数峰江上青。"]},{"t":"酬王哦松八景 其四 鄂渚春归","f":"七言绝句","c":["噎噎梅花煖响初，晓来痕绿到蘼芜。","鹗沈鹦鹉千年恨，指旧江山忍按图。"]},{"t":"酬王哦松八景 其五 吴江秋晚","f":"七言绝句","c":["浩然直养老益壮，吐作跨水晴虹飞。","三万顷秋天贴水，不禁依约写烟霏。"]},{"t":"酬王哦松八景 其六 浙江春潮","f":"七言绝句","c":["素车白马作前驱，垒雪屯云拟不如。","尺纸忽翻千尺练，断魂强弩控弦初。"]},{"t":"酬王哦松八景 其七 金焦雨馀","f":"七言绝句","c":["雨后双螺对绾青，采毫曾此蘸中泠。","写成九派分流势，不写当年瘗鹤铭。"]},{"t":"酬王哦松八景 其八 鉴湖独钓","f":"七言绝句","c":["羡他蓑笠度年华，尽把风烟付贺家。","盘礴细搜吟意绪，明波一曲小菱花。"]},{"t":"酬乐清陈簿雪中平反","f":"七言律诗","c":["用恕存存坐照奸，奸如挟纩弗知寒。","天虽有二无偏覆，网既开三亦甚宽。","疑欲惟轻刑自省，死终弗怨枕方安。","雪中小试阳和力，天地生成却不难。"]},{"t":"过张氏水亭","f":"五言律诗","c":["到岸不多遥，晴初雪未消。","茆檐虽傍水，人影不随潮。","鹊占寒枝喜，鱼从落日跳。","丹枫莫吹尽，我欲系兰桡。"]},{"t":"三锡堂下接桃 其一","f":"七言绝句","c":["前度刘郎去不来，炫晴灼灼又花开。","蟠桃著子三千岁，一岁从他熟一回。"]},{"t":"三锡堂下接桃 其二","f":"七言绝句","c":["接枝换骨胜刀圭，脸晕娇风满旧蹊。","有问春工在谁手，避秦人在武陵溪。"]},{"t":"乌?角行","f":"词","c":["村村花柳春菲菲，乌?声动清昼迟。","梅花噎噎不成弄，黄钟大吕相因依。","川平野阔牛背稳，水坳山曲人烟稀。","一声一声断复续，十十五五喧牧儿。","四郊唤得堕农起，不作阳关肠断声。","凄其道傍驻马远，游子往往不减阳关悲。","此声岂解令人悲，朝燕暮越远别离。","亦复岂能使人喜，蒉桴土鼓相酣嘻。","于戏此乐吾独知，尚记天台委羽破雨开林扉。","自鞭觳觫耦沮溺，白水没膝同扶犁。","是非利害不到耳，终日听此呜呜吹。","风淳调古相浃洽，不与市道趋浇漓。","朅来脚踏软红陌，不闻此曲闻此诗。","借翁语险久不和，迩来作者如埙篪。","埙篪虽美与时背，岂若乌?方适时。"]},{"t":"泊港口","f":"五言律诗","c":["港阔风初霁，潮平夜欲分。","半江都是月，一点不留云。","东去舟无数，南飞鹊恋群。","疏钟何处寺，隔浦最先闻。"]},{"t":"赵禅庵","f":"七言绝句","c":["面面苍崖似削瓜，涛翻鼍鼓半天挝。","依稀刘阮曾行处，无数水边桃未花。"]},{"t":"送谢司令通守严陵","f":"五言律诗","c":["访竹凌霜后，寻梅趁腊前。","春风方委曲，别乘忽腾骞。","处士不入府，客星仍受廛。","密斋容膝外，何处著壶天。"]},{"t":"拆桐花","f":"七言绝句","c":["叶底秋声急雨催，人言满树是愁媒。","九回百断渠何与，自是愁人做得来。"]},{"t":"新月","f":"七言律诗","c":["澹扫蛾眉雨后天，天容澄洁称婵娟。","弦虽未上终持满，璧反胡为尚不全。","只乡生时看最好，莫于缺处斲成圆。","人间梦事纷如蚁，著眼何曾到汝边。"]},{"t":"雪中登西菩寺参寥旧居分月阁闻读书声","f":"七言古诗","c":["谁平读书琅琅然，四山响答皆清圆。","山空无人渡双涧，更与流水相潺湲。","冻云压山吹不皱，云际棱棱展瑶甃。","广庭万舞乱零飞，老枝檠重如僧瘦。","吞蟾缟夜洞八窗，弗烦冻手挑残釭。","蝇头万字不足数，囧囧寒入青眸双。","辨才昔与参寥子，秣马问途端自此。","要汝勇追龙象躅，为我辛勤十年读。"]},{"t":"啸云","f":"七言律诗","c":["胡笳未奏边云悄，长啸一声山月小。","狂虏归思悲夜老，身未到家心已到。","山云不似塞云腥，云中倚阑时一声。","悠然清闻四十里，何独重围空万骑。"]},{"t":"问讯方岩侍郎 其一","f":"七言律诗","c":["翳尽珠明万象空，壶中只著小玲珑。","乡来冀北藐群马，此去斗南能几翁。","渊默但知藏霹雳，清宁何必友崆峒。","方城屹立青如削，万壑千岩在下风。"]},{"t":"问讯方岩侍郎 其二","f":"七言律诗","c":["用亦无心舍亦轻，岁寒只有竹忘形。","水村容与吹黄叶，溪圃耘耔课白丁。","细草远连三径绿，好山长借两眸青。","浚池小贮连天碧，待与人间洗浊泾。"]},{"t":"招遇野","f":"七言绝句","c":["叶响初疑夜霰微，晓看连玉幻屏帷。","令人忆煞天台遇，白尽蓑衣唤不归。"]},{"t":"辩才钟","f":"七言古诗","c":["井龙欲振兹山灵，忍使夜旦钟不声。","西京旧赐禁犹在，即山铸得蒲牢鸣。","虚文破壁俨如故，县官正令今重新。","身归柱后惠文手，加以束缚投诸囹。","夜囹焰发照城阙，燎原不足方其明。","民皆呼吏救回禄，骏奔稽颡祈玄冥。","及乎乡迩寂无睹，更欲炙手嗟无因。","朝闻夕报事从贷，雨濡露濯恩如春。","乡来光亦上牛斗，九畴分野当丰城。","干将独往莫耶在，延平涛浪今犹腥。","何如坎井蛰不死，雨晹答响如谷神。","百年逸事付僧史，不然簨簴重刊铭。"]},{"t":"雁来红","f":"七言绝句","c":["夜夜灯花巧胜裁，家书准拟傍秋开。","雁来红叶都红了，目断西风雁不来。"]},{"t":"田舍即事 其一","f":"五言律诗","c":["刺水绿针抽，田低水退流。","未饥先作午，图饱预占秋。","井远瓶罂重，陂荒茧栗浮。","静思田舍乐，却为素餐羞。"]},{"t":"田舍即事 其二","f":"五言律诗","c":["断垄收残麦，晴风卷宿云。","荡泥谙马力，煮茧策蚕勋。","野色如秋霁，山讴送夕曛。","悠然观岁事，不负一春勤。"]},{"t":"长门怨 其一","f":"七言绝句","c":["拜月归来剪绛灯，误占灯喜望承恩。","断魂薄命如初月，缺尽团团只一痕。"]},{"t":"长门怨 其二","f":"七言绝句","c":["菊到秋时独擅奇，怕秋嫌唱菊花词。","花头又似金钱小，不把金钱斗叶儿。"]},{"t":"长门怨 其三","f":"七言绝句","c":["拍拍官沟碧卷罗，影窥明玉敛青娥。","回头趁扑双双蝶，恨杀春风独管它。"]},{"t":"长门怨 其四","f":"七言绝句","c":["梦到昭阳与梦回，楚天云雨隔阳台。","壁粘鹾卤花如雪，赚杀羊车不入来。"]},{"t":"柳絮","f":"七言绝句","c":["麻姑米白玉床丹，老去慵将狡狯看。","却爱一川风絮好，就船做得雪团乾。"]},{"t":"日者","f":"七言绝句","c":["恶月悬弧岂好儿，衣冠聊复换伽黎。","听言易感人人信，不信田文善相齐。"]},{"t":"翠扫","f":"七言古诗","c":["小楼却立青林端，有水有竹仍有山。","微风徐来皱池面，浓翠澹扫开烟鬟。","九冈献状飞蜿蜒，悠然赴壑挽不还。","玄珠湛影不走盘，岚浮雾煖相萦环。","曲阑巧当环抱间，爱山聊复倚曲阑。","亦有零瀣供朝餐，崇朝挂眼双孱颜。"]},{"t":"送诜老归千顷山","f":"七言古诗","c":["老诜爱山不知了，何事冲寒下巍峭。","归装只有一囊诗，囧囧陆离还自照。","自言峰顶摩九霄，五月六月雪不消。","松风萧萧吹泬寥，千岩万壑酣笙箫。","前山后山畬可烧，黄精杂错黄独苗。","饭家田米可卒岁，亦有旨蓄延渔樵。","人间自有扬州鹤，诜也云胡甘寂寞。","笑云乐去悲相随，吾非恶此而逃之。"]},{"t":"钱百六录参入新宅得子","f":"五言律诗","c":["千忆子孙昌，衣传衮绣光。","厦成观贺燕，笔喜误书獐。","桂熟霜前子，梅腾雪后芳。","不须瞻岐嶷，定肖白眉良。"]},{"t":"寄陈黄岩","f":"词","c":["梅霖才自歇??，又复油然注上河。","水绕百畦虽喜足，雨当六月不嫌多。","甑虽未及炊先种，头已先低粒晚禾。","岁事莫于田祖卜，只于堂下听弦歌。"]},{"t":"刘检详新除","f":"五言古诗","c":["南北分疆后，关河气不清。","有才皆琐屑，临事少峥嵘。","嵩华俱崷崒，岷峨独抗衡。","卯金重耀德，藜杖复寻盟。","火老随秋灺，凉深伴月生。","虚凝仙掌泫，缥缈庆云明。","肯室高名节，宽西旧老成。","空群嘉骏产，跨灶大家声。","问望公舆论，芬香蔼旦评。","尺书贤十部，全璧藐连城。","一岁寻佳处，重阳欠好晴。","风轻茱未紫，露重菊初荣。","春玉新尝稻，挼香试剪橙。","满城风雨句，不足配餐英。"]},{"t":"闰月九日刘检详入山问近作","f":"五言古诗","c":["北涧寻新筑，东篱管旧香。","雨交前九月，晴到后重阳。","蚁慕无羊肉，鸿谋缺稻粮。","餐英聊自笑，辟谷竟何伤。","心远喧常寂，山深拙可藏。","息阴惭恶木，同调友孤芳。","丛蓧缘苔砌，闲花蔓藓墙。","寒枝繁鸟雀，落照下牛羊。","绿欠荷檠雨，青知橘未霜。","岁华惊过鸟，秋思老吟螀。","老子便幽事，深云僦睡乡。","指呼闲部曲，啸咏懒封疆。","率尔鸣天籁，泠然似野航。","汲溪酬欸乃，濯足咏沧浪。","蚁为谁开国，蜂如我敬王。","俗休嘲赋杼，骚谩吊沉湘。","兰茝新纫佩，芙蓉嫩制裳。","不知元亮醉，何似接舆狂。","更复求三益，何须馈五浆。","龙山在何许，云水渺相望。"]},{"t":"酬南宕诸友","f":"五言律诗","c":["岁闰黄杨厄，年丰白昼长。","独居无一事，两度见重阳。","野馈同谁饷，闲花各自芳。","贳将今夜月，藉手送秋光。"]},{"t":"唐人刘长卿送彻上人归越云禅客无心杖锡还沃洲深处草堂闲身随弊履经残雪手绽寒衣入旧山独向青山依树下空留明月在人间那堪别后长相忆云水苍苍但闲关洪义二上人请次韵归山阴","f":"七言律诗","c":["行云流水去仍还，多费清游少费闲。","缺处欲修前夜月，烧痕旋补去年山。","榻仍拂拭悬空壁，猿自归来守半閒。","寂寞东家老茅屋，平安几日到松关。"]},{"t":"江心寺步月诸公用甄监簿云卿韵","f":"七言律诗","c":["爱此凭阑夜不眠，欲将风驭作泠然。","呼蟾驾起三更月，展镜摊开万顷天。","亦有山灵回俗驾，可无蕙帐著胎仙。","试看拍岸涛翻雪，几许骊珠碎又圆。"]},{"t":"菜花","f":"五言律诗","c":["花芥开常晚，今年九月开。","直搀寒露过，弗待小春回。","后乘犹追菊，前驱不逊梅。","休誇太早计，老圃解栽培。"]},{"t":"冷水谷桃花未开次竹岩韵","f":"七言古诗","c":["山行两袖皆华风，游人未多花未红。","堂堂春去已无几，晴趁一日来山中。","山人寸金酬天地，都种芳菲留客醉。","粉桃商略待绯桃，坐令羯鼓催无计。","匆匆归兴如酒浓，零落断云流水踪。","明朝乘兴尚可再，应笑武陵蓑笠翁。","判花大手今燕许，收拾是中春一坞。","小待巴东制锦归，尽吹红雨为霖雨。"]},{"t":"酬姜贫乐","f":"七言律诗","c":["我欲渊明伯仲间，为谁乾没静中闲。","直将目送孤鸿度，横截湖飞短艇还。","稍閒便同搜万象，更忙亦可看孤山。","是閒真隐多馀地，玄豹何尝肯露斑。"]},{"t":"立可则礼思复雪中见过","f":"七言律诗","c":["花翻云叶舞风回，新好缤缤带雨开。","团破小龙寒未瀹，客如两鹤瘦飞来。","白灰宿火虽同拥，黄独无苗各自煨。","苕霅扁舟明日去，小须门外玉山颓。"]},{"t":"残雪","f":"五言律诗","c":["前水花新霁，暾云日未升。","檐声都是雨，笕溜半成冰。","幌冷疑眠月，窗虚罢续灯。","独馀林杪塔，犹自隐觚棱。"]},{"t":"酬方岩","f":"七言古诗","c":["大溪小溪沙水明，浊可濯足清濯缨。","渊渊寸田湛古井，澄浊与之俱忘形。","绿野菜花三四亩，不图娱客犹供口。","旧种庭前三树槐，更有门前五株柳。","时拊碧云歌碧云，婆娑鹄羽青纶巾。","不妨别调吟梁甫，收拾乾坤浩荡春。"]},{"t":"书雪湖寄张高沙诗卷后","f":"词","c":["大篇如建瓴，小篇如捍城。","执此能事柄，凌夺造物真。","雪湖坐此彻骨贫，致贫之具犹示人。","铿锵应是我辈语，饥鸢悲苦哦清新。","高沙旧日春风手，也是乘槎丈人后。","红莲开幕著诗人，此段风流少人有。","飞声郎署知闻旧，扫门谩惜千金帚。","不图愿与丈人厚，要看云锦三千首。"]},{"t":"复斋奚左藏挂冠 其一","f":"七言律诗","c":["趁得身轻便挂冠，翩翩出岫白云闲。","村疏一日是两日，心广半间如万间。","聊把大门标俗子，别开荒径友佳山。","羲皇向上多馀地，时对清风一破颜。"]},{"t":"复斋奚左藏挂冠 其二","f":"七言律诗","c":["特操刚明与俗乖，溪山亦复外形骸。","子狂正作岂矫世，我醉欲眠聊纵怀。","勇赋一归尤果决，光寒千丈不沉埋。","从来林下何曾见，仅有先生闼可排。"]},{"t":"送钱竹岩宰常熟 其一","f":"五言律诗","c":["无日游天竺，新除问补陁。","两回抽竹策，一语定弦歌。","悬应如虚谷，灵通岂祝鮀。","只依彭泽样，条具不须多。"]},{"t":"送钱竹岩宰常熟 其二","f":"五言律诗","c":["渊默战纷华，清吟日又斜。","尊中常有酒，堂下可施罝。","琴响家家月，春酣处处花。","平章风物手，小屈课桑麻。"]},{"t":"赠鹤鸣冯高士","f":"七言律诗","c":["静对深炉养白砂，又从活火剪黄芽。","蜕尘与世羽凡骨，看镜为谁开晓霞。","万里脚头元自稳，一毫心事不曾差。","何时采药天台去，烂醉桃源几树花。"]},{"t":"贺宇文枢使","f":"七言古诗","c":["伊洛正音闻者寡，邪说异端难并驾。","春风不到六经堂，和煦无由蔼天下。","卓然人物既兴起，浩然一气均陶冶。","横秋霁月耿东南，劲草疾风知用舍。","堤障狂澜如砥柱，渊源理学扶宗社。","伊周文宪复精明，汉唐述作俱陵跨。","论道经邦坐策勋，弹冠束带无遗野。","遂令四海九州内，三尺儿童耻言伯。","太山盘石固无疆，乱臣贼子胡为者。","今日枢庭拜宇文，还似前朝相司马。"]},{"t":"盆兰","f":"七言律诗","c":["采采芳根绿缀苔，一茎只放一花开。","畹中好恶非同调，林下薰莸各有才。","惜此国香无地种，知它楚些为谁哀。","小留鹤帐梅梢月，倘伴高情入梦来。"]},{"t":"送黄郡博之官高邮 其一","f":"五言律诗","c":["一曲占晴湖，楼居岂俗居。","人虽增境胜，鹭不与鸥疏。","古锦投明月，春风入绛幮。","好诗频遣寄，莫遣不情书。"]},{"t":"送黄郡博之官高邮 其二","f":"五言律诗","c":["贵作横金客，才如切玉刀。","长城坚未下，大敌勇难鏖。","老兔明千里，垂虹绿半篙。","何时醉醽醁，伴我读离骚。"]},{"t":"送谯回庵作江东宪","f":"七言律诗","c":["千骑前驱拥旆旌，鸟啼花发近清明。","斯文自是域中大，廷尉旧持天下平。","春到十连皆化日，风清万窍只秋声。","庐山面目无人识，应喜重来为主盟。"]},{"t":"续舞马行","f":"七言古诗","c":["见说开元天宝间，登床百骏俱回旋。","一曲倾杯万人看，一顾群空四十万。","梨园部曲能穷奇，踣铁矫揉杨柳枝。","不直玉环一解颐，更走泸戎生荔枝。","天上人间反覆手，故态忽生乱离后。","将军入眼可曾有，误骏为妖不足咎。","于戏唐虞全盛时，百兽率舞凤鸟仪。","雍熙之和乃其效，何用区区教坊教。"]},{"t":"韬光庵","f":"七言律诗","c":["洛下僧归未寂寥，馀光还向此中韬。","入千峰杪从它笑，放一头低尽自高。","客至坐凉分树影，云开写望到江涛。","夜遥月冷风初霁，万籁无声亦怒号。"]},{"t":"谢盘野黄文昌 其一","f":"五言律诗","c":["易入亚夫营，难收四海名。","两全无可愧，独以退为荣。","萧洒霜髯古，敷腴玉色明。","神仙在平地，跬步到钧衡。"]},{"t":"谢盘野黄文昌 其二","f":"五言律诗","c":["日课芳菲谱，归来手自栽。","有诗随意好，无日不花开。","鸥鹭论心事，云山入酒杯。","绮罗帘幕静，处处小蓬莱。"]},{"t":"十四夜月","f":"五言律诗","c":["几望沧浪月，裴回独自看。","小亏修未了，忒满怕持难。","篆冷檀烟湿，衣单桂露乾。","丁宁桥下水，明夜印团团。"]},{"t":"代竹岩送史侍郎 其一","f":"七言律诗","c":["曾泛东湖载月船，不将人物等闲看。","二灵千古独钟秀，五岳三光空自寒。","跨灶极知从古少，为兄端恐自君难。","故家别有单于调，付与鸰原次第弹。"]},{"t":"代竹岩送史侍郎 其二","f":"七言律诗","c":["荷橐风高北固秋，黄童白叟拥行舟。","旧盟不冷在群鹭，归兴绝攀回万牛。","传自教明南国后，可容寇借一年不。","旌麾小试经纶手，此惠何烦敛壹州。"]},{"t":"昭君行","f":"七言古诗","c":["楚山有美倾人国，家傍江城逐臣宅。","逐臣赋并日月明，琵琶遣入穹庐鸣。","哀弹不作胡儿语，写汉遗音吊亡楚。","泪如铅水湿春风，苦心只与春风诉。","曲中愁绪乱风丝，因风寄雁云南飞。","汉家弹作昭君怨，试问昭君别怨谁。","天生尤物天还如，仰天自笑蛾眉误。","不如强醉枕琵琶，暂时栩栩梦还家。","昭阳未有承恩地，阏氏孰与宁胡贵。","不须频下思家泪，汉女雄猜如阿雉。"]},{"t":"苕溪多楮三伏最茂","f":"七言律诗","c":["朱实燉空密幄成，曾阴无地暍行人。","风枝雨干彫零后，玉板云英制作新。","传得文章贻后晋，忍随竹帛祸先秦。","西凉叶叶秋声树，学到先生是效颦。"]},{"t":"寄漫塘刘平国索竹岩钱德载挽章","f":"七言律诗","c":["一从神武挂衣冠，千载华风去不还。","闲惬清宁羞宦巧，静窥奔竞识天悭。","高于少室从它售，捷似终南各自扳。","我欲西风问无恙，不知著得几鸥闲。"]},{"t":"西余庭犀合抱强半不下西湖刘寺双桂已厄于嘉定十二年打十方之初信夫主僧元粹之忍也余在北山作诗援之云翠华几度树边来手压芳枝内苑栽且看传灯金粟面小留残馥点苍苔两唐律赋西余吊刘寺云 其一","f":"七言律诗","c":["亭亭领袖晚风光，吹尽西凉不尽香。","勒麝兰薰回俗驾，动龙蛇影转回廊。","老持素节芳仍洁，碎点苍苔绿衬黄。","自把胡床低处著，高舂盘礴到斜阳。"]},{"t":"西余庭犀合抱强半不下西湖刘寺双桂已厄于嘉定十二年打十方之初信夫主僧元粹之忍也余在北山作诗援之云翠华几度树边来手压芳枝内苑栽且看传灯金粟面小留残馥点苍苔两唐律赋西余吊刘寺云 其二","f":"七言律诗","c":["蜕俗风标与月分，竞攀争撷到仍云。","弗知芗国有乔木，大似幽居无此君。","叶密听他嫌不韵，根盘如许合空群。","四朝雨露金刀寺，两树前年夭斧斤。"]},{"t":"初度","f":"七言律诗","c":["苕溪初度思亲泪，滴尽依前不及泉。","借使无言还自寿，便教有法与谁传。","五穷各自争为祟，百巧还他弗解禅。","为问季秋几望月，几回照我未生前。"]},{"t":"送袁状元别驾","f":"五言古诗","c":["碧苕秋晶晶，君子尚此洁。","渊渊方寸地，上善固一辙。","白蘋对红蓼，亦各振清冽。","况复芬陁利，穆若谢炎热。","譬彼寒水玉，温其出冰雪。","其中富涵蓄，其响亦疏越。","有德必有用，无瑕更无缺。","允属清庙器，合在东序设。","君家圣贤学，拟续邹鲁绝。","正音久不作，倩君木为舌。","风月小鸿沟，矧乃龙首杰。","伟兹真富贵，弗与颜原别。","辉辉近芳日，朣朣袖华月。","馀光散遐隐，四海俟昭晰。","遗直在山林，放言敢辞拙。"]},{"t":"和竹岩游虎丘","f":"五言律诗","c":["山低秋欲雨，树老晚藏烟。","剑试道边石，花飞台外天。","暝云埋古甃，嵌窦涨新泉。","欲借松风鼎，煎茶些玉川。"]},{"t":"九日姑苏台酬卢蒲江赵静斋钱竹岩诸名胜","f":"七言律诗","c":["岁晚登临似仲宣，可胜来此拍阑干。","水围绿野日将夕，露浥紫萸秋未寒。","欲雨天痕云气湿，不风庭树子声乾。","悠然吊古无穷恨，付与西风一永叹。"]},{"t":"雪中寄赵湖州容斋","f":"五言古诗","c":["庆兆三回白，祥开嗣岁春。","精求方恳恳，悬应忽逡逡。","化母非无待，玄冥却有神。","夜窗疑是月，晓砌不生尘。","麰麦占年熟，郊原见日新。","柳塘吹漠漠，银浦剪缤缤。","鹤干胜寒重，猿枝撼落频。","折腰嗟劲节，低首吊苍鳞。","池草生吟思，溪梅寄远人。","不知吟啸地，何似灞桥亲。"]},{"t":"开元观乃何畏斋施地张练师开山","f":"五言律诗","c":["何必过流沙，浔溪种道芽。","雄开献王地，胜傍觉皇家。","云侣呼朝斗，星坛数扣牙。","胎仙翔集后，底处蛰灵蛇。"]},{"t":"舟中遇雪寄宋使君 其一","f":"五言律诗","c":["数点雨中飘，萧骚响近郊。","霰微疑旋集，篷破省初敲。","乾没高连下，平铺凸到凹。","悬知天地力，瑕秽赖并包。"]},{"t":"舟中遇雪寄宋使君 其二","f":"五言律诗","c":["急舞随风乱，缤飞度竹迟。","松埋巢鹤顶，藤重挂猿枝。","螟■频年死，乌鸢尽日饥。","娄丰书野史，双展使君眉。"]},{"t":"代人与荆襄李制帅","f":"五言古诗","c":["桃花武陵原，千骑访旧游。","旧题鬼神护，苔藓封蛟虬。","是时原中花，炫昼烂不收。","稚耄相欢呼，再拜罗道周。","一闻謦咳声，曰似吾故侯。","侯今飞上天，盟在沧江鸥。","公来席未温，玉帐凉生秋。","粘天洞庭北，襄楚当襟喉。","小屈经纶手，平分宵旰忧。","风清鹦鹉洲，月满黄鹤楼。","黄鹤去不返，万灶栖貔貅。","白羽青纶巾，坐寝淮南谋。","文武固一道，貂蝉出兜鍪。","致身须黄阁，看镜方黑头。","故家迈种德，台辅不足酬。","颓支邹鲁澜，末障洙泗流。","载观统有宗，抑使俗不浮。","古道复大明，殊俗皆蒙休。","况夫蜀文章，眉独称雄酋。","多应峨眉月，只照东家丘。"]},{"t":"徐提刑挽章","f":"五言律诗","c":["衣冠忽蜕尘，桃下是仙津。","身与吴天远，恩沾楚泽新。","授官宁后子，退己不先人。","尽是无私处，何惭第五伦。"]},{"t":"卢君挽章","f":"七言律诗","c":["祸淫福善信前闻，话到斯人只断魂。","心岂眢丹遗囧囧，电虽藏碧鉴昏昏。","欲将书卷酬青紫，不啻籯金富子孙。","后夜黄龙洞前月，小留残照侧金盆。"]},{"t":"黄龙洞","f":"五言律诗","c":["玄窞蜿蜒宅，苔痕到底青。","凿深连地轴，设险讶山灵。","路斗风烟湿，风酸草木腥。","丁宁休勒驾，更欲上新亭。"]},{"t":"旧馆夜雪投静上人","f":"五言律诗","c":["雪重官塘滑，堆篷扫不消。","闻钟寻近寺，转港识飞桥。","肤粟寒初起，衣棱煖不朝。","主人无木佛，泥佛不中烧。"]},{"t":"谢陆少监分惠渭南剑南家集","f":"五言古诗","c":["故家骚雅传，翼翼见芳继。","况如孙仲谋，不败乃翁事。","圭残入裒拾，璧断归次第。","自成一家学，忍使只字弃。","若翁喻蜀时，名胜各超诣。","初从汉西京，绵绵振末裔。","相如子云后，经术奋多士。","岿然今陇蜀，渊乎古洙泗。","冯刘振风霆，刘李渺涯涘。","况复有小李，隽永出大胾。","翁来试掉鞅，平地快奔驷。","逸驾相后先，六月乃一税。","渭南问风俗，剑南看形势。","岷峨连蓬婆，风赋达骈俪。","雕镌到微茫，抉剔逮菑翳。","连络数十城，八万四千偈。","彬彬奂文采，烂烂存表制。","分甘成暗投，效颦更拙计。","琼琚报木李，美齐诏当世。","乃今得琼琚，何以答佳惠。"]},{"t":"葛无怀讣至 其一","f":"五言律诗","c":["饮羽窥天巧，御枚戒夜严。","采荼宁自苦，课蜜为谁甜。","阁令看山槛，亭空并水檐。","怀哉双宿鹭，日日望钩帘。"]},{"t":"葛无怀讣至 其二","f":"五言律诗","c":["静胜知天定，虚明悟物齐。","略伸嗟屈蠖，欲吐丧晴霓。","夜雨灯侵幌，春风柳并堤。","漫天吹絮尽，一点不沾泥。"]},{"t":"杲无外枝巢","f":"五言律诗","c":["树下无三宿，人间僦一单。","房新蜂最乐，巢旧燕知难。","云幌涵秋冷，蟾枝踏月残。","朱门空锁宅，多是别人看。"]},{"t":"即事","f":"七言律诗","c":["遥夜迟眠替夙兴，细听墙角打风棱。","白灰未冷已无火，红烬欲残犹有灯。","天做雪时先自雨，水通潮处可曾冰。","有诗只些孤山月，不恨梅花唤不应。"]},{"t":"分岁","f":"五言律诗","c":["办得分年供，清哉亦称怀。","野槃均柿串，草具爨松钗。","指冷柑初破，灰红芋旋埋。","火边相枕藉，火尽又添柴。"]},{"t":"读岳鄂王传","f":"七言古诗","c":["百钧不挽射羿弓，朔望酹酒马鬣封。","从来知子莫若父，许以徇国输精忠。","相州去谒大元帅，是时元帅方潜龙。","华风忽与庆云遇，千载一德明良同。","南薰门外众制寡，铁路步上雌决雄。","浮屠连墙望尘靡，拐子如山随手空。","伪齐可绐不可杀，兀朮可间毋庸攻。","寇连诸道解如瓦，气吐千丈长于虹。","声先到处皆春风，桀骜怙很摧枯蓬。","中原跂踵戴旧德，萧墙稔祸基元凶。","当时剑握不倒置，直北马首无由东。","全尺寸地有馀刃，半九十里隳奇功。","老罴既陷百尺阱，长城遂摧千丈墉。","群奸尾摇蜂虿毒，一蟆吻纳蟾蜍宫。","强胡妄冀脱虎口，残喘忽重苏犬戎。","难平者事有成算，可投之机无再逢。","乡来望诸报燕惠，无怨无怒方雍容。","其谁掩卷辄恸哭，主父偃与齐蒯通。","黄金台圮置勿论，问之胡不达四聪。","昔人已矣不可作，后来更复将焉从。","审如机括发必中，诚与日月昭而融。","将军碧电摇百步，跨灶英勇尤折冲。","乾坤不朽忠义骨，光腾抔土方朣朣。","春秋不书六月雪，是日集霰回泠风。","杞传百世子配食，天定胜人还至公。","乱臣贼子生看好，遗臭不老均翾虫。","坐令三光五岳气，百岁左衽昏濛濛。","周南滞留奋椽笔，折奸全直传无穷。","浯溪大字倘可法，燕然苍藓知谁砻。","开禧之事如昨日，清淮洒血连天红。","动逾二纪不解甲，残虏尚锐蕲黄锋。","噬脐太息复太息，遗恨黯黯齐崆峒。","至今奸血泽遗类，忠愤郁郁填人胸。","向使二子及见此，恸哭岂止喧旻穹。","古愁连环不可解，除是帝舜开重瞳。"]},{"t":"楂庵严教主塔","f":"七言律诗","c":["黄金扶膝起沉潜，一屈何须为老严。","扫径雪苔封古甃，举头花雨落疏檐。","楂酸如橘尤多涩，语苦如荼久自甜。","新霁林光净如洗，僧窗处处有孤蟾。"]},{"t":"送侃侍者归灵鹫","f":"七言律诗","c":["莫将平淡觅陶潜，纪律严于玉帐严。","要得澜翻联石鼎，也须雪立到茅檐。","太虚自笑花无蒂，佳境谁云蔗不甜。","如此工夫随分到，灵犀无夜不吞蟾。"]},{"t":"索笑","f":"楚辞体","c":["屋角飘香树，何曾解倩兮。","倚春和露瘦，闯晓待蟾低。","背俗高标致，从他浪品题。","若非林处士，冷面觑清溪。"]},{"t":"有客","f":"五言律诗","c":["雨止云犹黑，春寒草未青。","打门无俗客，勒驾有山灵。","彷佛斜川路，裴回曲水亭。","落梅都著子，点点六花零。"]},{"t":"鹤唳","f":"七言绝句","c":["九皋清响漏残时，想见松间露湿衣。","弱水弗关云外路，乘轩终不似横飞。"]},{"t":"蘋洲莱菔脆甚","f":"七言绝句","c":["藕生玉井何曾见，梨属张公不见分。","安得脆琼莱菔子，蘋洲南畔种残云。"]},{"t":"寄陈宣州中书 其一","f":"七言律诗","c":["霁月横陈几许秋，拍肩小谢老风流。","开尊孰愈暂挂榻，视草曷如高卧楼。","旧有凤衔新紫诏，今无鹤似古扬州。","颍川只说黄丞相，更为行春得小留。"]},{"t":"寄陈宣州中书 其二","f":"七言律诗","c":["夷惠清和不尚同，直将两手袖春风。","娄丰从劝三农始，初度重书二月中。","欲与大年分殿最，试于小知击倥侗。","虽云弱水归溟渤，自向西流不自东。"]},{"t":"佛眼侍者祖元血书华严八十卷以报母细而楷花石纲初得之藏诸塔寺后复失之复得之于京师","f":"七言古诗","c":["楚云血指书法华，藏诸衡山竺仙家。","自言剖匣待慈氏，凡指试触轰雷车。","思溪不落衡山后，行缀蝇头三十九。","停匀瘦劲妙钟王，初终一字亡差谬。","阿元曾透龙门去，失却登门最初步。","笔端佛语血滴滴，直下发明根本部。","一尘具有一卷经，破尘出经不动尘。","尘尘刹刹尽三昧，一字一行皆正因。","静想生初常反照，雱然母血知多少。","一支馀沥何足云，贝叶悉书酬不了。","莲花七卷六万言，净明海眼伯仲间。","诸经一写复屡写，大经血脉俱相关。","六丁畴曩曾搜索，青毡解后铜驼陌。","千金购得喜欲颠，十袭载归花石船。","恍如光焰腾双剑，夜夺龙光寒不焰。","遂令合浦有还珠，毋令沧海有遗珠。"]},{"t":"刘学谕挽章","f":"七言律诗","c":["大信难于浅俗谋，楚人然诺久无酬。","尽摅素蕴知难售，空抱遗经自反求。","数曲短屏林屋晓，半规残壁洞庭秋。","焚舟自是诸郎事，接武东厢两胜流。"]},{"t":"题水墨萱草水仙 其一","f":"七言绝句","c":["草欲忘忧蔓更滋，望云长在蜀天西。","萧萧风木添新恨，誊录精神答噬脐。"]},{"t":"题水墨萱草水仙 其二","f":"七言绝句","c":["绿玉纤扶水玉腴，华风披拂度华裾。","却从坏色衣中赋，不把高情托子虚。"]},{"t":"读南迁录","f":"七言古诗","c":["垂垂胡运风灯掣，不悟鼎中犹鱍剌。","后庭玉树不摇春，只看婆娑双勃脱。","提刀策马兆自南，梦中宿愤方深衔。","子生母死托诸母，祸既滋蔓难夷芟。","骨肉相残甚于寇，倒把太阿归女手。","宁能同死不同生，掎角亟图邻壤救。","奋戈秃体空无前，倾巢倒穴成播迁。","飘零左衽馀南冠，孙又生子罹腥膻。","回头九十年中事，水浅蓬莱人换世。","顺昌之捷金刀回，商虢破竹丘山颓。","韩刘亦复不世出，英勇弃捐如掷砾。","短檠伴语南迁话，泪眼不晴彻遥夜。","应是天归古汴都，却教胡羯先驱除。"]},{"t":"读泣蕲录","f":"五言古诗","c":["蕲当淮楚冲，虏骑如云隤。","书生胆如斗，激烈生风雷。","备禦尽吾力，力殚心不灰。","誓与城存亡，不遣疋马回。","忍死不忍屈，视死犹去来。","一州同一心，忠愤铁石开。","舍生贵取义，肯顾儿女哀。","话头素讲明，馀刃方恢恢。","视古不愧今，落落俱雄才。","援师窘于兔，趑趄山泽隈。","遂使破贼手，不复歼渠魁。","仪刑古睢阳，观阙双崔嵬。","传后韩愈书，芒寒燉九垓。","不知蕲州传，大手今谁哉。"]},{"t":"送高菊涧访方岩侍郎","f":"五言律诗","c":["尘涨软红深，髯高独访寻。","贫交难偶俗，生事不关心。","米贵甘餐玉，楼宽苦僦金。","霞标连雁荡，款款度岑崟。"]},{"t":"酬赵山中","f":"五言律诗","c":["壶公云雨上，秀整压全吴。","白眼嫌人俗，玄裳笑鹤癯。","对吟酬蟋蟀，独酌泛茱萸。","待赋归来后，商量觅镜湖。"]},{"t":"塘西寺闻蛙","f":"五言律诗","c":["器小易彭亨，声连踸踔群。","三更万籁息，两部一池分。","语海嗟难合，窥天亦浪云。","寻无杜鹃处，得此不堪闻。"]},{"t":"方岩许送纸不至","f":"七言律诗","c":["巾山高出慈恩寺，蜀叟贫于郑广文。","卷尽长廊无一叶，尚馀泼笔振孤军。","苍筠嫩杀空怀古，明玉方裁欠策勋。","惆怅洛阳收贾后，欲书重吊楮生文。"]},{"t":"谢周和州叔子","f":"七言古诗","c":["阴阴浓绿成新幄，荼蘼试妆催芍药。","缓鞚青丝果下骝，时与华风相领略。","风乎不违主人意，吹开宿酲换新醉。","玉山自起不须扶，隐若长城一万里。","和州归来贾如玉，高著十连酬不足。","倚阑目送断鸿飞，闲按新声翻旧曲。","畴曩方岩丈人厚，话到君侯布衣旧。","不知灞上故将军，何如细柳真将军。"]},{"t":"和赵湖州见寄","f":"七言律诗","c":["拙速诙谐与巧迟，约三章法赴吟期。","一从鸥鹭忘情后，都是池塘入梦时。","星履盍酬高步武，竹符聊试小施为。","凛然心事明如日，况是从来畏四知。"]},{"t":"泊然庵","f":"五言律诗","c":["白日静中消，忘言赋解嘲。","叶疏犹可幄，云浅亦堪巢。","清拟圣人酒，澹于君子交。","悠然无藉在，檐铎听风敲。"]},{"t":"平望徐监酒新楼","f":"七言律诗","c":["水际楼居入眼新，傍窗横榻款诗人。","早彫杜老双蓬鬓，晚赏徐卿两石麟。","浓绿已摇三丈线，残红恰有一釐春。","闲情直与眉霄壤，也为春归作小颦。"]},{"t":"次韵宣州使君陈中书见寄","f":"七言律诗","c":["听紫芝歌问绮园，橘中果有几何天。","试原雪夜玉堂梦，更了江春符竹缘。","新涨溢池荷叶小，煖风掠面柳花鲜。","大邦屏翰风骚地，应有诗人受一廛。"]},{"t":"泸南玉帐曹国博再知类省举","f":"七言律诗","c":["除却倚门憔悴兄，关心国子老先生。","近看西蜀群仙籍，远赴南丰一瓣盟。","久矣倚公如敌国，怀哉得士胜长城。","蜀江万派朝宗水，峭绝泸川砥柱横。"]},{"t":"竹院","f":"五言律诗","c":["种得碧参差，开门绿打围。","金铺宁免碎，玉瘦不禁肥。","雨过风梢重，晴初露叶晞。","弗须关月户，我欲款烟霏。"]},{"t":"题粲书记作双鸲鹆并宿梅花上","f":"七言绝句","c":["金线单弦馀睡思，黪茸乱羽欠春声。","立残参子黄昏月，犹傍梅花瘦影明。"]},{"t":"林酒仙祠","f":"五言律诗","c":["百丈古规绳，蹉讹尺到寻。","可曾知稼穑，多是少丛林。","有迹从人议，无心与俗沉。","太湖吞弗尽，哆口到如今。"]},{"t":"酬李如山见寄","f":"五言律诗","c":["俗棼须尽扫，扫尽又纷华。","喧避蚁争市，静看蜂报衙。","竹梢斑殒箨，蘋渚素浮花。","自把闲消遣，从容日又斜。"]},{"t":"问讯陆秘读","f":"七言律诗","c":["曾并篮舆上峭巍，先将鸾尾扫烟霏。","步从归鸟上头去，云在倚阑低处飞。","古锦尚馀前日句，秋荷重制北山衣。","蓬莱直与人间远，犹得清苕访采薇。"]},{"t":"经筵赐茶杨文昌席上得贵字","f":"五言古诗","c":["龙泓荐春甘，茶荈绝众卉。","屑琼作玄玉，不惜万金费。","厥贡来四方，特立建溪贵。","诸儒方重席，飘飘凌云气。","方圭与团璧，锡自一经既。","得从稽古力，不敌稽古味。","小苦政不恶，回甘亦差慰。","雪涨忽翻乳，珠碎仅成玑。","月团三百片，下下敢髣髴。","宏功适胥称，厚享可无谓。","馀沥逮蔬笋，疏瀹固所畏。","悠然记新分，嘉定次癸未。"]},{"t":"杨文昌得古方壶于巴子国","f":"五言律诗","c":["大巧出天姿，何年幻怪奇。","身轻成俗蜕，调古弗时宜。","方外虽圭角，宏中填侧攲。","同盟今几辈，郜鼎与宗彝。"]},{"t":"书薛符溪诗卷","f":"五言古诗","c":["三峨孕元气，直与乔岳侔。","因依几何年，蕴藉六十州。","芃芃擢楩楠，碌碌生琳璆。","潢污化清泠，仄陋发炳彪。","岩岩钟人才，出辄第一流。","或为德渊薮，或擅文雄酋。","或赴功名期，或于名节收。","崭然薛符溪，馀地出一头。","高寒蓬婆雪，翠扫山月秋。","黑头当策勋，青绶曷足酬。","得年虽不多，得名端不浮。","遗墨见绝少，六丁方隐搜。","曩闻桃花为，强悍繄公柔。","篇什富袭藏，零残皆萃裒。","牛腰几卷轴，棘心怀松楸。","心声出诚素，瑶肪谢雕锼。","往年诗寄为，趣为买归舟。","为无一簪直，自衒富寡俦。","倒橐仅如此，贫祟何时瘳。","昨从西子湖，来访蘋花洲。","请续梁甫声，使贻齐大羞。","惆怅貂不足，非类何足求。"]},{"t":"盆竹","f":"五言律诗","c":["老瓦新淇奥，清风小渭川。","有孙皆抱节，无地可行鞭。","不肉甘吾瘦，敲扉僦榻眠。","多君不受暑，移傍枕帷边。"]},{"t":"石上丛竹","f":"五言律诗","c":["斗石森微干，杯泓托茂林。","不多犹绝俗，虽小亦虚心。","风噎纤纤玉，蟾低琐琐金。","胸中渺千亩，尺许对曾阴。"]},{"t":"明远即事","f":"五言律诗","c":["红褪金罂子，芳腾金橘花。","物情闲态度，秋色澹韶华。","燕老迟归思，蜂慵早退衙。","关心最幽事，辐凑在山家。"]},{"t":"次李东迁寄娄云西两诗韵 其一","f":"七言律诗","c":["远明双白倦揩摩，镜里星星绿变皤。","凝不飞云疑有蒂，润潜分井信无波。","鹤安屡空都忘去，鼠笑长贫绝见过。","宛转门前听歌鸟，倚风疏柳正婆娑。"]},{"t":"次李东迁寄娄云西两诗韵 其二","f":"七言律诗","c":["绿涨菱荷一半空，残零小队试吴宫。","断虹暝卷千峰雨，方塔凉吹四面风。","遥夜河源和月晓，近秋溪影与天同。","山林横槊非长算，犹欲前驱挑两翁。"]},{"t":"送姜贫乐赴陈华亭约 其一","f":"五言律诗","c":["僦屋傍西湖，湖光浸屋除。","秋荷纫雨后，邻米饷斋馀。","句熟如圜转，谋生似我疏。","拙吟方巧宦，骚雅费甾畬。"]},{"t":"送姜贫乐赴陈华亭约 其二","f":"五言律诗","c":["见说华亭政，平夷似太丘。","适时宽胜猛，几月很成柔。","袖刺方徂岁，敲弦倏借秋。","尺书频寄意，君岂致书邮。"]},{"t":"次超果寺见远亭韵","f":"五言律诗","c":["寺古巧经营，横飞水上亭。","港分秋练练，云合暮青青。","暝树雨收画，残沙晴射星。","苹芜舒晚眺，障日恨山屏。"]},{"t":"立秋","f":"五言律诗","c":["清苕早试秋，便作练光浮。","雨褪荷花瘦，风生蓼叶愁。","一声离岸橹，几个入城舟。","惆怅田鸟响，关心卒岁忧。"]},{"t":"六月廿九神林寺池上荷花","f":"五言古诗","c":["凉沼承芳薰，急雨压炎暑。","叶叶蚌触碎，顷刻万斛许。","痕玉脸能薄，著得许多雨。","骈头如有愬，低簪欲相语。","摧拉翡翠翼，零乱鸳鸯羽。","剩拟笺老天，细意写心膂。","约束诛云师，前驱卷晴宇。","红酣尽扶起，绿摇并搴举。","蘋末风亦好，人间暍随愈。","太一泠然舟，著我歌白苧。"]},{"t":"怀归四首 其一","f":"七言律诗","c":["姓名何必上传灯，破釜难谐大吕声。","信脚半生惟舌在，策勋九转到丹成。","强知晴雨怜鸠拙，拟葺茆茨似燕营。","见说千金曾卖赋，不堪容易赋闲情。"]},{"t":"怀归四首 其二","f":"七言律诗","c":["富贵还乡颇称怀，谓之昼锦亦宜哉。","过家曾说分符去，持节旋闻谕蜀来。","皎皎月规前夜缺，悠悠渊水有时回。","车轮未必都生角，只合横推不竖推。"]},{"t":"怀归四首 其三","f":"七言律诗","c":["可能无地著蒲团，自把行藏一破颜。","试问飞来华表柱，何如生入玉门关。","角才扣罢寻烟棹，驴倒骑归看华山。","处士故庐霜月古，欲将全璧伴东还。"]},{"t":"怀归四首 其四","f":"七言律诗","c":["何须骑鹤与腰缠，欲傍家山问一廛。","任是五经俱扫地，可容四海欠弥天。","白砂自养真铅汞，玄草重纫断简编。","更絇梅花窗外树，曲肱听雨听风眠。"]},{"t":"淀山三姑新锡庙额曰会灵仍为作记","f":"五言古诗","c":["有德难藏用，惟功易及民。","封嘉从巨宋，宠贲逮先秦。","鼎足分灵躅，波心据要津。","水连天共远，湖与泖为邻。","盛事千年閟，幽光一日伸。","典刑开祀事，季孟旧彝伦。","天上丝纶美，山中雨露新。","嫩凉生暑昼，老火变阳春。","肸蚃先群望，丰凶在一身。","不知闲草木，何事亦精神。"]},{"t":"舣篷","f":"五言律诗","c":["幻得江天小，阴晴便合宜。","未将红蓼种，先报白鸥知。","贴水云千点，窥檐月半规。","归僧敲竹户，只作扣舷疑。"]},{"t":"蓬居梵竺卿诗藁","f":"五言律诗","c":["维舟吊竺卿，寒日暗丹青。","俗恶眼中屑，离骚身后经。","畦芳催蜜熟，圃药试方灵。","零落三千偈，关防在六丁。"]},{"t":"次韵惠寺丞见寄","f":"七言律诗","c":["雁塔名题久不知，新吟忽遣好风吹。","易推未画本无画，计已出奇何有奇。","孔雀屏开金错落，蟾蜍玉冷墨淋漓。","故家旧有传衣句，跨灶冲楼足尉思。"]},{"t":"大雅堂","f":"五言古诗","c":["少陵何人斯，曰似司马迁。","太史牛马走，于此何有焉。","瞢者瞢不理，知言超言前。","政如春在花，春岂必丑妍。","又如发清弹，意岂必在弦。","悠悠云出山，滔滔水行川。","云水山川行，莫测何能然。","不知其谁知，软语黄庭坚。","庭坚语弗软，壮折滟滪颠。","尽写剑硖诗，不数金薤篇。","密付草玄后，夜光寒烛天。","扁作大雅堂，醉墨犹明鲜。","至今百岁后，此意惟心传。","炎宋诸王孙，传癖不复痊。","闭户阅宗派，尚友清社贤。","吕韩俨前列，芳蜡然金莲。","三洪偕二谢，病可携瘦权。","夺胎换骨法，妙处尤拳拳。","疏越正始音，细取麟角煎。","亦有老斲轮，堂下时蹁跹。"]},{"t":"槎浦南翔寺","f":"五言律诗","c":["荒破齐梁地，宏开释梵家。","令威新化鹤，博望旧停槎。","风袅经幢石，芳腾品观花。","同声六万字，羊鹿换牛车。"]},{"t":"南翔九品观","f":"五言律诗","c":["清泰重开国，芬陁便满池。","高风追晋社，馀地拓萧规。","玉甃承丹垩，璇题漾碧漪。","西之真捷径，舍此复何之。"]},{"t":"华亭孙丞迎侍道州使君","f":"七言律诗","c":["老人端似老人星，五马精明旧典刑。","故事新看厅壁记，华堂旧有德威铭。","数州棠树应垂地，四世莱衣又过庭。","骚雅故家仍大手，可无清警赋华亭。"]},{"t":"秋潦叹","f":"词","c":["疾雷振秋杪，急雨动旬浃。","风中三重茅，露卧且病涉。","四郊漫漫空涌波，田叟田妪鹈在河。","阵头雨过阵头起，湿稼不多潢潦多。","风雨声中哭声苦，泪眼不晴多似雨。","不忧饥殍更流移，忧欠今年县官赋。","县官勤俭知岁饥，定有德音来抚绥。","老奸黠胥能巧诋，莫将白纸欺黄纸。"]},{"t":"赠丁相士","f":"七言律诗","c":["张雪湖家苜蓿盘，坐中著眼恐应难。","似华表鹤仍同姓，与华山人不两般。","客舍须寻佳处住，热官多是冷时观。","却须索我形骸外，莫作三支一等看。"]},{"t":"余尸巾山苦诛求而去钵无舂粮寓公范公伟质衣以赆西笑曰乱邦不居行矣","f":"七言律诗","c":["廉士难于俗吏并，质衣犹及送僧行。","惠惟适用偏多感，施及无求益见情。","弱羽敢辞三足妒，伏雌常与九包争。","故家逸韵难谐俗，共作台州一段清。"]},{"t":"赤城六章章四句","f":"词","c":["赤城峨峨，霞摽错摩。","笃生斯人，绝超凡科。","峨峨赤城，磅礴九地。","斯人笃生，水瘦石悴。","念昔三辅，湖独纷委。","逮公来斯，苕霅泾渭。","千里寿公，祷公寿康。","惠洽兆庶，日飞百觞。","伊我无酒，注彼觓兕。","愿公华衮，式昌厥嗣。","亦复愿公，啸吟紫微。","㑭我紫微，嬉其莞而。"]},{"t":"酬竹岩赋行春桥翁媪摘白","f":"七言律诗","c":["恨霜点鬓讳言霜，谁敢从翁话鬓苍。","每见丹林枫剪剪，只云青女陈堂堂。","所馀不足供弹镊，既往徒嗟易断肠。","惆怅行春桥下水，无朝无暮只沧浪。"]},{"t":"西菩中晖堂乃参寥辨才所居","f":"七言律诗","c":["门外青山自作双，檐前松韵泻秋江。","半规皎皎暾重雾，一点晶晶洞八窗。","用晦不曾欺暗室，凿邻何必借残釭。","俭存元祐规模小，曾著光明两胜幢。"]},{"t":"吊杨尚书哭子未几复鼓盆","f":"五言古诗","c":["寿域富万汇，楚楚惟灵椿。","彭固不可侪，聃亦虞遘迍。","天高杳难问，请以意自陈。","大年岂知止，小知宁无赢。","况夫朝有闻，幻变可得婴。","君家老孟光，及与膝上英。","洞窥天地先，一视蜾与蛉。","居然因其小，其馀赞经纶。","青青脩梧枝，尚有五色翎。","相参星辰履，共为黄河清。"]},{"t":"送杨文昌帅泸南","f":"五言古诗","c":["乡心动如翼，勇去挽不还。","长年卷百丈，疾飞三峡船。","东西跬步间，勋业唾手耳。","貂蝉出兜鍪，了不二初志。","泸川控井络，衿喉翰西徼。","貔貅拥玉帐，万灶听吟啸。","蜀相入不毛，赤地方流金。","至今龙门江，透底如此心。","公乎同此心，印水复印天。","我恐席未煖，又下瞿塘船。"]},{"t":"题冲老廉博士古木","f":"七言绝句","c":["离奇磊砢廉宣妙，幻出川僧屋角头。","风雨夜遥龙不寐，听他天籁自飕飗。"]},{"t":"次韵吴主簿初度供佛","f":"五言律诗","c":["未惬响朝阳，卑栖枳棘傍。","刚柔非吐茹，衰弱倚清强。","避酒来萧寺，思亲拜渭阳。","平生番袜法，背俗细平章。"]},{"t":"山居次卢玉堂见寄","f":"七言律诗","c":["旋十村墟旧缚茅，夜深云呗薄江郊。","更无可借文书处，只好相寻野逸交。","落叶自随流水去，闲门尽倒破囊抄。","故人递迭青云去，谁与山人赋解嘲。"]},{"t":"寄秋塘陈敬甫","f":"五言古诗","c":["华风岂不声，默与静者吹。","凉月自入袖，默许静者知。","风乎岂必尔，月亦听所之。","静者亦若是，弗与俗子期。","俗方日日浮，静岂忍诡随。","山林隘乾坤，小大各有宜。","思君令人老，一见动岁时。","下塘通上塘，一苇何远而。","畴曩北山日，皂盖松间飞。","澄潜二三子，喜迓见睫眉。","著翁泉上亭，泉石讶久违。","透闸观涛澜，雪溅冰玉澌。","激翁技痒处，汹涌翻文辞。"]},{"t":"墨荔支","f":"七言绝句","c":["老坡曾比江瑶柱，或谓江瑶柱不如。","拟写钗头皱红小，断魂蛮雨瘴烟疏。"]},{"t":"道场山两题 其一 清池","f":"五言律诗","c":["凿地潴寒碧，泠泠湛弗摇。","方奁开素镜，阔幅剪生绡。","甃古天为底，杯深雪涨潮。","俗交浓若醴，一滴也难消。"]},{"t":"道场山两题 其二 一勺泉","f":"五言律诗","c":["岩隙带痕云，涓涓不受尘。","洼尊元自浅，攲器不须盈。","镜彻双明碧，花浮少许春。","汉宫分烛后，新洁试清清。"]},{"t":"送顾哦松柬祁门尉 其一","f":"五言律诗","c":["角转城头晓，风回麦脚斜。","清明都冷落，阴翳趱韶华。","饭了长亭黍，来分野寺茶。","到家三月暮，恰好送莺花。"]},{"t":"送顾哦松柬祁门尉 其二","f":"五言律诗","c":["已矣吴门市，祁门问阿连。","有书聊话旧，无累不须仙。","蜀叟思长计，苕溪缚数椽。","不知双璧外，谁与办腰缠。"]},{"t":"丹霞张府博入夏蔬食","f":"七言律诗","c":["不为长斋绣佛前，欲酬芳瀣伴风蝉。","川奔直恐颓难障，灰死何曾溺不然。","冷帐弗生骑鹤梦，清才合友跨鲸仙。","几时卜筑红泉上，只尺丹霞小有天。"]},{"t":"代宣石桥谢两浙部使者","f":"七言律诗","c":["丙寅端午前三日，南宕西湖酒一卮。","趁此昌蒲新酿熟，看君棠棣燕歌迟。","春风玉笋分班处，夜雨金闺对榻时。","蛙在秋池分部曲，小须叔季奏埙篪。"]},{"t":"张萱作妃子夜游图子由谓之秦虢并驱争先图文潞公司马公东坡兄弟一时名胜洎宣和宸翰在焉藏诸御府后归绍兴权倖家复为开禧权倖所有更化后景献仲兄得之","f":"词","c":["孰挥若木枝，日驭不可勒。","志士分寸惜，长绳系不得。","忽观此图使我伤，使我痛愤嗟三郎。","三郎飞入月中去，回首不知宫漏长。","金羁金勒控紫缰，玉花玉面下采床。","天阶夜色净如洗，宫弯促?相抵当。","十家三国归模写，不写渔阳闹胡马。","较来不画亦不妨，囧囧莫掩张曲江。","宣和宸奎独烂烂，元祐名卿题得满。","既归天上誇袭藏，又落人间作奇玩。","沉思恶衣菲饮食，过门不子呱呱泣。","张萱已矣倘可呼，为我只作涂山图。"]},{"t":"武侯庙","f":"七言律诗","c":["黑柏森森旧息阴，锦官城北到如今。","虽生仲达犹难料，更十曹丕岂易禁。","曾过南阳寻故俗，偶思梁甫拟高吟。","外江三硖霜蟾老，蚤识先生溯硖心。"]},{"t":"林君筦榷上巴河蕲黄乱离仅以身免","f":"七言律诗","c":["话到蕲黄只永叹，不知心作食梅酸。","断头自是无降将，啮指终能愧贺兰。","变弗知权生亦愧，动才适义死何难。","多君逆旅观浮俗，尸素墦间一等看。"]},{"t":"送任大卿出知汉州","f":"五言古诗","c":["就列行初志，专城亦此心。","玉蟾卿月满，金雁景星临。","知旧玄裳鹤，从游绿绮琴。","歌风琴在御，梦草鹤同吟。","梁甫谁同调，高山自赏音。","往来三硖险，森布万灵钦。","信是娄师德，惭非释道林。","华风一披拂，小草竟萧森。","不赋空怀土，无枝勇惜阴。","房湖开绿幕，祇树砌黄金。","驷马虽难驻，双旌倘可寻。","逍遥堂旧话，领话望公深。"]},{"t":"种桑","f":"五言律诗","c":["无衣可柰何，桑树百馀窠。","拙计不及此，瘠田谁种它。","绿荷供楚制，白苧入吴歌。","金谷虽佳丽，知谁所得多。"]},{"t":"摘茶","f":"五言律诗","c":["苦莫苦于荼，回甘荠不如。","瘠丛嗔重敛，睡眼喜丰储。","未雨试芳洁，残春空绪馀。","丁宁加惠养，竭泽恐无鱼。"]},{"t":"赠御前梁宫干","f":"七言古诗","c":["梁楷惜墨如惜金，醉来亦复成漓淋。","天籁自响或自瘖，族史阁笔空沉吟。","前日去寻子赵子，道院水亭秋色里。","幻成赵子骑蹇驴，潇洒不减骑鲸鱼。","又写深衣跨牛客，云生谷口耕阡陌。","按图绝叫喜欲飞，棹笔授我使我题。","我方拄眼孤山西，岑楼残碧澹扫眉。","见成一段诗中画，宜雨宜晴四时挂。","输与滕王蛱蝶图，坐收少室山人贾。"]},{"t":"元日送客归西湖","f":"七言绝句","c":["采笔春消御柳边，棹歌忽听采菱船。","三贤见说迁居了，只寄梅花问水仙。"]},{"t":"题扇暍图","f":"五言律诗","c":["忠厚文传武，吾宁未释疑。","能扇行路暍，不疗采薇饥。","酷在炎炎处，凉生习习时。","白团替黄钺，宜画不宜诗。"]},{"t":"琉璃灯中鱼子","f":"五言律诗","c":["玄珠透水明，玉鱲弄晶晶。","跃碍冰痕薄，潜疑月色新。","器宏斯可乐，水浅易持盈。","归趁烧灯后，蘋洲拍拍春。"]},{"t":"风琴赠选上人","f":"五言律诗","c":["万籁甫消声，锵然忽自鸣。","独宜风力小，双与月华清。","历历谐三叠，玲玲叶九成。","宫商虽断续，何处不分明。"]},{"t":"寄宣城使君陈中书兼简谢别驾林叔恭 其一","f":"七言律诗","c":["森戟凝香赋夜严，酲开玉色判厌厌。","荼虽小苦还如荠，梅抑微酸必俟盐。","寿富拓成千里域，光荣飞上一规蟾。","道枢却在环中转，剩馥残膏亦溉沾。"]},{"t":"寄宣城使君陈中书兼简谢别驾林叔恭 其二","f":"七言律诗","c":["乐雠稽古暂专城，孰愈金莲夜直频。","风月平分与宏放，江山多助到清新。","乡来素练江犹净，近日芳池草又春。","想见尊前酬别乘，武夷山下付衣人。"]},{"t":"吊志老宿","f":"五言律诗","c":["浮休不足筹，遗恨黯难收。","死草起新馥，落梅添古愁。","一龛迟日月，百岁老春秋。","独有旧名氏，不随溪水流。"]},{"t":"溪行","f":"七言绝句","c":["夭夭拍拍涨桃花，葑未全青荻已芽。","两行若无杨柳树，看来无处著韶华。"]},{"t":"寄江东赵料院兼简仓使","f":"七言律诗","c":["江远天低月透沙，严城佳处舣仙槎。","明分象纬占群玉，巍峙岑楼仰九华。","棋局旋收归静胜，吟疆宽拓战淫哇。","春回水驿分新句，更寄南枝一两花。"]},{"t":"谢叶文昌二首 其一","f":"七言律诗","c":["星履声中识典刑，洗空浮俗快双明。","四朝孰愈德耆艾，九鼎曷如身重轻。","只作寻常高步武，安知咫尺是钧衡。","冲和一点关埏埴，噫欠春风六合生。"]},{"t":"谢叶文昌二首 其二","f":"七言律诗","c":["镜里津津喜上眉，人情瘦瘠遁心肥。","环中小复事虚应，方外敢忘求实归。","客好洁羞南涧藻，家常草具北山薇。","难消闲里舒长日，脩绠何须绊落晖。"]},{"t":"杜侍郎坐上得彝字","f":"七言古诗","c":["春事三分二分了，策勋淑景还宜早。","野桃官柳嫌春少，却笑上林莺易老。","岂知老干空斗南，七八千岁春酣酣。","无人闻此不大笑，有口只与庄生谈。","金钟大镛在东序，瑚琏陆离杂雕俎。","歌工在列乐在悬，更复明堂须柱础。","一枝老我苕水湄，煮字不充亭午饥。","丹崖苍壁信手题，咏歌事业铭鼎彝。"]},{"t":"萼庵魏紫","f":"五言律诗","c":["华风织翠裾，紫绶更纷敷。","屑玉嫩成糁，缕金齐撚须。","妖饶嗟易歇，落托醉难扶。","旧日沈香北，倾都只此姝。"]},{"t":"督钱肖岩教子","f":"五言律诗","c":["曾过竹岩幽，岩前正晚秋。","养廉忘节苦，种德俟芽抽。","横翠新如染，澄澜凝不流。","丁宁庭砌玉，及早事雕锼。"]},{"t":"移斑竹","f":"五言律诗","c":["刍尧挠岁寒，巍节笑多艰。","露湿添新绿，苔封减旧斑。","龙雏分竺寺，帝子泣湘山。","无限苍梧思，清风便往还。"]},{"t":"酬谢司直晦斋寄宋湖州见柬 其一","f":"五言律诗","c":["春无十日好，又是去堂堂。","柳借鹅黄重，花消蝶粉香。","清和宜晚步，零落课残芳。","北牖华风煖，朝来尚宠光。"]},{"t":"酬谢司直晦斋寄宋湖州见柬 其二","f":"五言律诗","c":["清苕春事早，三月已无花。","岁涝塍犹缺，田低水再车。","远怀难尽寄，近况却全佳。","也似云台吏，生涯未有涯。"]},{"t":"凤鸣寺十八应真乃日本国所制密印僧典于沈氏沈施于凤鸣","f":"五言律诗","c":["木素上金泥，云衣整稻畦。","曾充僧典质，未到佛阶梯。","领众三韩北，分身两浙西。","一龛老风雨，谁与振幽栖。"]},{"t":"酬季敬父清明见寄","f":"七言律诗","c":["半雨阴阴复半晴，芳郊紫径厌尘轻。","飞花逐旋将春去，续绠寻思系日倾。","梦苦流莺呼得觉，愁嫌啼鴂唤教生。","频搔短发临寒水，添了星星几点明。"]},{"t":"卢直院大监挽辞","f":"五言律诗","c":["客葬柰贫何，无山无薜萝。","近分南宕小，远胜北邙多。","不与貂蝉老，空将琬琰磨。","丁宁燕许手，遗事细蒐罗。"]},{"t":"送宋使君呈光禄","f":"五言律诗","c":["解绂宜新渥，催帆挂晓晴。","宿阴消岸趾，初日动帘旌。","班近寻鹓鹭，亲怡燕弟兄。","老人躔次近，同傍紫微明。"]},{"t":"送林府教英发","f":"五言律诗","c":["元化钧陶铸，先生独铸颜。","不祥麾跃冶，至蕴剖藏山。","幌冷云垂地，名脩玉缀班。","圜桥俨冠带，鹄立望公还。"]},{"t":"碧衔霞行","f":"七言古诗","c":["双衔金勒明霞碧，暗花隐起云如刺。","霜零燕涧草根甜，长鸣振鬣飞无迹。","一朝群空十二闲，在图八骏亦腼颜。","乡令生并人间世，踯躅吞声敢伸喙。","真人开国宗承祖，犹有幽燕两抔土。","要须马上驾群雄，九重跨出苍玉虹。","短鞚长驱当峻坂，却后伸前如履坦。","紫驼峰荐碧琳腴，馀沥娄分明玉瓒。","圉人太仆不敢侮，爪剔爬搔谨程度。","屹立亭亭时却顾，趯啮谁能犯其怒。","乡闻天马曾作歌，大宛西极都蒐罗。","凤膺龙脊非凡驷，马肝遂误文成死。","遂使刘郎葬茂陵，不到昆台十二层。"]},{"t":"桃花犬行","f":"七言古诗","c":["非玄非黄花蒙茸，炫昼不减原上红。","无功指踪走原野，兔尽倘可逃灾凶。","禁林都是秋声树，满身何处沾红雨。","苔痕玉砌卧斜阳，又误零霞低薄暮。","枫宸紫阙芳雾濛，长门永巷泠泠风。","夜严不声白昼永，羊车所至随从容。","鬼瞰高明目不瞬，勾连狸怪狐妖逞。","百步虽无槛虎威，双睛何用轩辕镜。","熙陵以西一锄地，寸金寸土君王赐。","平分只与碧衔霞，生死恩荣略相似。","相如飞辙自蜀都，初因狗监诵子虚。","四夷来王亦典丽，御考自称前进士。"]},{"t":"赵侯遥碧轩","f":"五言古诗","c":["一峰中雄酋，两峰拱而立。","崭然入云表，烟开翠鬟湿。","佳山如佳士，可望不可及。","诗人觑天巧，妙处归眼力。","新营称华扁，收此一寸碧。","婆娑在其下，缱绻与之习。","嗟哉尘土中，膏火日煎急。","青层但坐对，皓首未暇识。","趋舍各有适，枘凿不相入。","何当山上头，裴回瞰原隰。"]},{"t":"止止阁","f":"五言古诗","c":["回阑净如拭，古灶寒不烟。","宿之用弥壮，渟则澄以鲜。","乡来矜襄陵，今焉碧渊渊。","乡来观燎原，今也不复然。","激湍反其性，静则知其天。","抑炎弗用智，智烛天地先。","悠然百不理，复檐飞画船。","拍阑抚寥泬，倚楹鉴清涟。","山黛渺茫绿，水花先后妍。","原隰烟雨时，万变了目前。","汎观尘土中，搏攫如乌鸢。","娄藏满籯金，更聚百屋钱。","亡弓苦妄冀，去剑疑将还。","拟分芭蕉鹿，去馌虞芮田。","营营复营营，万绪膏火煎。","何如歌吉祥，亹亹乐者全。"]},{"t":"谢宣城朱长官","f":"五言古诗","c":["飞来何处山，秀整连凤池。","绝胜一锄地，天地不得私。","朣朣斗牛间，明玉生华滋。","凛姿岁寒后，萧洒观孙枝。","出宰山水县，小谢城东陲。","琴瑟日在御，箠楚不苟施。","春风河阳花，次第芳菲菲。","屈指九十日，日日把酒卮。","玉山不须扶，百里皆酣嘻。","行扳星辰履，颉颃丛霄蜚。","故家厚培㙲，衮绣看传衣。"]},{"t":"天台宋紫薇光禄挽章","f":"五言古诗","c":["闲适与康宁，山林只一人。","风流两晋旧，翰墨四朝新。","五裤歌宣化，三盘载演纶。","垂杨闲意绪，华顶老精神。","广乐千龄会，溟波几度尘。","壶中留白日，庭下拥朱轮。","荷嫩衣重制，兰馨佩更纫。","玉颓千日酿，俗蜕百年身。","赋里寻词客，桥边问应真。","灵光犹在鲁，商岭谩逃秦。","入社宜归洛，休耕不起莘。","骑箕渺何许，长啸玉楼春。"]},{"t":"山行即事","f":"五言律诗","c":["吹到堤边絮，春菲处处空。","苦滋荼叶雨，野韵刺花风。","荷贴平池绿，榴苞露井红。","忽闻淮麦熟，且愿似崆峒。"]},{"t":"次韵陈右史赏醉落托","f":"七言绝句","c":["罗幕低开护曲阑，娇红落托醉扶难。","朝来嫩日疏云淡，纵有些风尽耐寒。"]},{"t":"送王宁国","f":"七言律诗","c":["习习凉薰至自南，诗人官满策归骖。","腰缠简短聊遵约，家法森严贵不贪。","政入民谣歌得一，月临山驿赋成三。","独馀寻丈鸣弦地，仪表江东古子男。"]},{"t":"谢人饷蕨","f":"七言绝句","c":["瓦盂亭午未闻歌，少负心初负腹多。","薇蕨不侵耕凿地，八珍柰此属餍何。"]},{"t":"秦权","f":"七言绝句","c":["自程文法较锱铢，汗竹韦编付烬馀。","倒置重轻矜缜密，不知三十六年疏。"]},{"t":"莺","f":"七言绝句","c":["最堪听在绿阴阴，缓缓歌酬细细吟。","别院晓声知几许，田巴抵死只枭音。"]},{"t":"芳渚秋零小卷","f":"七言绝句","c":["沙明石老水收痕，零露寒生宿莽根。","欲尽夕阳秋态度，莫添白鸟破烟昏。"]},{"t":"彰教山茶敌胜宣城","f":"七言绝句","c":["吟压宣城小杜陵，忍红红拟白头吟。","丹滋晓滴珊瑚重，闯户春寒翠幄深。"]},{"t":"时斋","f":"五言律诗","c":["易去苦难追，知几勇不疑。","梭才起雷泽，鱼已奋天池。","夜冷梅粘雪，秋零桂著枝。","风云与人会，先不与人期。"]},{"t":"腊初雪至月末","f":"五言律诗","c":["四野静无尘，崇卑砌得匀。","不才添臃肿，瘦节耻轮囷。","乱委无非瑞，才消便是春。","多年闻混沌，今日见纯真。"]},{"t":"梁太子钓台","f":"七言绝句","c":["晴拂双鬟晓未开，先驱寸碧渡江来。","伤心旧日垂纶地，几度江春去又回。"]},{"t":"清泉得名于真大参","f":"五言律诗","c":["清者畏人知，泉胡不病兹。","土疏分石脉，砂浅静风漪。","薇腹应同洁，茶勋亦振奇。","出山嗟浑浑，三咽起余思。"]},{"t":"九华山","f":"五言律诗","c":["九华宜带雪，故故仲冬来。","翠扫忺梳洗，玄冥未剪裁。","骤观疑旧识，近看若新开。","曾说壶中玩，多应小有才。"]},{"t":"老融牛 其一","f":"七言绝句","c":["一战长驱七十城，可无馀勇替春耕。","归来不作凌烟梦，只写清溪瘦影明。"]},{"t":"老融牛 其二","f":"七言绝句","c":["力穑工夫画里看，闵劳念旧只长叹。","断魂千载荆州市，尸素甘心饱阿瞒。"]},{"t":"雪航","f":"七言绝句","c":["九逵埃壒点人衣，踏土何如踏浪儿。","烂熳溪头千树玉，风蓑月笛兴阑时。"]},{"t":"放闸","f":"七言律诗","c":["截住泠泠碧透沙，放开衮衮怒飞花。","石疑初裂蓬婆麓，鲸拟洪奔海若家。","殷地贾馀翻霹雳，喷岩用壮激谽谺。","凭阑小伫观流止，不独观澜一笑哗。"]},{"t":"下竺朱桐花一根出石上见之四十馀年","f":"七言绝句","c":["绿柄高扶绛玉开，层层萼萼染猩裁。","峄阳曾止青鸾翼，无此奇葩更不来。"]},{"t":"严山人饷蒲萄浆","f":"七言绝句","c":["翠朵搴藤剪绿垂，小槽新压水晶澌。","凉州亦有扬州鹤，惆怅山人只要诗。"]},{"t":"送心上人归琴川","f":"七言绝句","c":["五道川流似五弦，绿窗朱户照明鲜。","飞来峰下僧归去，髣髴华亭落照船。"]},{"t":"烟竹","f":"七言绝句","c":["林疏略见两三分，不是岚光不是云。","亟展生绡轻著墨，幻成初日度晴熏。"]},{"t":"秋夜","f":"七言绝句","c":["嫩凉细意入帘栊，禁树秋声未击蒙。","展尽绿蕉心寸寸，几时消息到梧桐。"]},{"t":"天竺两峰堂待月","f":"七言绝句","c":["朣朣如水洗新秋，到两峰前凝不流。","曾似丈人祠下看，丹梯飞步玉华楼。"]},{"t":"代人上魏左史","f":"五言古诗","c":["榜下尽横飞，龙头尚立螭。","穹崇方善下，谨厚孰逾卑。","制作虽师古，经纶盍制宜。","迥超千丈俗，密契九重知。","北海客常满，西湖雨亦奇。","文传仁者寿，用适圣之时。","数道甘棠咏，丛霄湛露诗。","未移骐骥步，已在凤凰池。","紫橐荷芬馥，巍冠佩陆离。","橐中云锦段，拈出解人颐。"]},{"t":"水月庵","f":"词","c":["心蟾光朣朣，性静湍不起。","悠哉小天地，万化渺无蒂。","清苕半洚水月庵，碧蟾夜夜先清涵。","曩曾借榻坐凉树，细数秋毫窥夜潭。","犹来清圆捉不得，何地容兹老豪逸。","脩名与月俱不死，衮衮东流几时息。","乡来万州赋此诗，寥寥百岁无此奇。","诗在天西锦官寺，珠璧照人觉形秽。"]},{"t":"刘寺庭犀盛开","f":"七言律诗","c":["凤井庭犀玉载腴，楼前楼后著花初。","不须素幌萦檀篆，只放鲜风入绮疏。","恨弗同寻姑射住，却疑僦得广寒居。","露零夜老秋衣薄，独自裴回绕屋除。"]},{"t":"直院卢蒲江为余作寿木怪石","f":"五言古诗","c":["草枯蓝田山，饮羽误入神。","归来落清梦，起写赝虎真。","槎牙虎边树，霜虬蜕脩鳞。","乡来一寸根，今者千岁苓。","冻雪压不低，华风吹不春。","落子大蔽牛，娄起厦屋倾。","日月弗知老，保此坚与贞。","年年姚家黄，角逐魏紫荣。","十里春风香，走杀陌上人。","夭妍极远到，不得一月程。","居然事颜色，只与朝菌盟。","安知有耆艾，落落仍亭亭。"]},{"t":"江西定上人梅","f":"七言绝句","c":["眼明不识春风影，收拾风烟入梦思。","一笑自知天下白，墨名乌足累冰姿。"]},{"t":"老融放耕图皇甫都护雁图二绝 其一","f":"七言绝句","c":["蓑笠从衡觳觫蕃，暝归晨作俟丰年。","诛求莫挠鸡豚社，春雨春寒苦最先。"]},{"t":"老融放耕图皇甫都护雁图二绝 其二","f":"七言绝句","c":["邕邕何处一声秋，杜若汀连宿莽洲。","米熟菰蒲随分饱，危机多是稻粱谋。"]},{"t":"木犀著雨","f":"五言古诗","c":["空山雨淫秋，妒我庭中犀。","犀敷粟玉英，浸渍仍葳蕤。","有如春方中，名品嗟淋漓。","因依海棠泪，著此霜蟾枝。","闻此辄掩耳，代犀前致辞。","燕脂怨无香，姿色独媚时。","烘晴睡未足，已惊胡马嘶。","彫零怕随雨，嫣然成怆悽。","鲜明擅韶华，不足较等夷。","自怜宫样黄，不结春风知。","木兰固可友，宿莽亦可师。","正色俗子憎，浓馥天风吹。","苔痕净如染，绿展承霏霏。","故家换骨法，降真合传衣。","大山与小山，骚雅同衿期。","至今百世下，犹有芗林诗。","何心与物竞，有泪无从挥。"]},{"t":"秦时石酒缸","f":"五言律诗","c":["臃肿窥秦制，曾闻酿酒来。","腹如包括胀，口作并吞开。","北筑饥难疗，东巡醉不回。","痕云疑潋滟，馀沥晕苍苔。"]},{"t":"九日还山中","f":"七言绝句","c":["去年佳约负东篱，凤井丹犀彷佛知。","便使山灵先勒驾，明朝更拟北山移。"]},{"t":"虞美人草","f":"七言古诗","c":["君恩如海海不深，妾义如铁利断金。","舍生取义我所欲，忍死织室羞同心。","春姿忽作秋蓬委，一寸刚明曾不死。","明年原上野花繁，一枝自托华风起。","袅袅娉娉不成艳，态度浅深生色染。","向人欲诉却无言，寂寞千年恨谁掩。","芳郊游女宛转歌，倚春拍手看婆娑。","露晞初日枝头坠，犹有君王别时泪。","翻刘覆楚知几何，大风竟作还乡歌。","淮南区区欲为帝，淮阴堂堂贺陈狶。"]},{"t":"苍苔","f":"七言律诗","c":["湿带秋痕绿可庭，花阴竹色借鲜明。","簪抽翠笋愁穿破，茵拓青丝喜剪成。","户外倚筇遮俗屦，楼头横玉衬寒英。","平阳不惜黄金埒，稠叠蒙茸四畔生。"]},{"t":"渔父","f":"五言律诗","c":["谋生与俗违，一叶浪中蜚。","水易分团月，云难隐少微。","雁沙眠晚照，鸥渚棹晴霏。","见说蓬莱浅，寻津问钓矶。"]},{"t":"装冬后不速之客来","f":"七言绝句","c":["绽裘纫絮办冬和，羽化其如独冷何。","藕荡欲搴霜后叶，晓来零落更无多。"]},{"t":"王总卿季和归自关西","f":"七言律诗","c":["关西长虑独兢兢，万灶分屯感慨深。","不易制如巫硖水，最难得是蜀人心。","拨灰忍见俱焚玉，铭鼎徐看小篆金。","欲倚筹边开玉帐，共观城外柏森森。"]},{"t":"耕谷","f":"七言绝句","c":["屦痕不印步虚坛，欲事锄犁恐亦难。","云子熟时还自饱，不知沆瀣与谁餐。"]},{"t":"识全","f":"七言绝句","c":["占得沙边柳外春，更专吟啸管阴晴。","延祥观后茅茨老，月旦工夫子细评。"]},{"t":"石亭","f":"七言绝句","c":["苍壁痕云煖不消，午阴花影共林皋。","丹藏亭树无人守，付与县枝雪色猱。"]},{"t":"秋塘报陈提刑讣","f":"七言律诗","c":["宏博曾闻鼎足无，脚才实处即荣途。","恰观次第行初志，冀懋神明振后图。","齿失半唇忘屏翰，棣联双萼更纷敷。","乡来少戆烦公笑，却忆公言诮故吾。"]},{"t":"送傅兄归江西简诸宋诸黄","f":"七言律诗","c":["冲和正脉到江西，中有千岩万壑奇。","百鍊易成终切玉，一炊难办必精糜。","艾萧杂处芝兰馥，风土殊方枳橘移。","铁石故家清婉赋，盍临疏影寄予思。"]},{"t":"题高髯墨菊枕屏","f":"五言律诗","c":["欲种团枝香，无地著蔓延。","密化移春霏，零露生秋妍。","非金亦非玉，采采仍田田。","餐英不成梦，唤起西窗眠。"]},{"t":"题高髯诗藁","f":"七言律诗","c":["翻水千篇未足哦，不酬一语亦同科。","若非身世相忘久，应是江山得助多。","旬月有人加锻鍊，壶觞无地不婆娑。","西湖南荡相寻处，门断红尘接翠萝。"]},{"t":"接虞税院贯卿遗书","f":"五言律诗","c":["尽心如善射，百步中弥亲。","不竞与闲契，尊生为死邻。","关讥千古恨，日计两眉颦。","一卷花严易，心知更几人。"]},{"t":"甘园寻梅 其一","f":"七言绝句","c":["疏枝重复裹莓苔，护得寒英煖未开。","料理不关元化事，翠华长是雪前来。"]},{"t":"甘园寻梅 其二","f":"七言绝句","c":["楮幌春生斗底房，不知冰结夜来霜。","无因领略黄昏月，只遣疏钟管暗香。"]},{"t":"松御座","f":"七言绝句","c":["偃盖交柯坐亦宜，春风翠辇憩逶迤。","大夫寂寞山阴道，不见西湖鼎盛时。"]},{"t":"云","f":"五言律诗","c":["自是无心物，依稀似有心。","因风才冉冉，酿雨忽沉沉。","一末绅朝岭，重檐帽晚岑。","丁宁休蔽日，我欲耀阳林。"]},{"t":"趣徐无竞作水仙","f":"五言律诗","c":["抱独贫如我，飘然更我怜。","亲思文度瘦，妇笑伯鸾颠。","混混污成俗，朣朣碧觑天。","肯移罗袜步，荐菊些林仙。"]},{"t":"雪湖池上新筑","f":"五言律诗","c":["疏绮闯冰池，苔封老石矶。","鱼方深避钓，鸥亦早忘机。","涤研融残雪，观书竞夕霏。","春风长似旧，还趁雪中归。"]},{"t":"曹泸南得思陵旧赐张魏公琴曰播云","f":"五言古诗","c":["岷峨豁尘昏，旧赐出播云。","不知落人间，虾蟆几亏盈。","晦显固靡常，数岂逃冥冥。","想当风雨时，破壁应有声。","怀璧戒匹夫，呵护烦百神。","一朝得所托，倏若屈蠖伸。","人以器图旧，器以人怀新。","玉轸黄金徽，烂烂奎画明。","魏公蔼名氏，千载如丹青。","歌风调舜弦，感物怀尧仁。","扶日昌中兴，四海同一云。","载维艰难初，事与得失并。","万灶嘉陵江，饮此一掬清。","悠然一再弹，万里怀长城。","云絮初无根，勇变嘲哳鸣。","捕蝉写真意，弦外无人听。","空嗟易水寒，遗恨崆峒平。"]},{"t":"杜侍郎之遂宁","f":"五言古诗","c":["宁为轻以清，抑为重而填。","重轻惟时中，举辄丽吾正。","诚斋振家学，本末尽诚敬。","所施见伦次，所瞩洞遐隐。","喧啾雄地籁，静胜了天定。","一经早授受，吴霜未侵鬓。","精明紫荷橐，所蕴固未尽。","玉堂与天远，仙槎向人近。","旌旄屋头州，维翰倚东屏。","敛此一道惠，徒引兆庶领。","泉山跨鳌碧，横江秀而整。","吾亲在其下，枌榆接封畛。","家有老吟僧，河海借馀润。"]},{"t":"喜曹安抚还自泸南","f":"七言律诗","c":["蜀道因仍涨燧烟，烦公玉节照山川。","省闱三见文衡正，边柝双兼武备全。","传自老成需代去，不知威惠倩谁宣。","回头半壁西南地，不是寻常刺史天。"]},{"t":"卢直院挽章","f":"七言律诗","c":["玉堂云气锁空濛，回首泠然跨阆风。","纸贵又腾身后贾，骚亡旧策眼前功。","蜗缘竺涧题名石，鹭忆吴江载酒篷。","零落九华三四帖，朣朣犹在破囊中。"]},{"t":"宋左曹湖州宣谕","f":"七言律诗","c":["皇华万斛下苕溪，夹道甘棠映绿漪。","为问只今回首处，曷如它日劝耕时。","恩光才洽腥风静，烽火初消化日迟。","士不明经无足用，乡来殷侑亦如斯。"]},{"t":"永嘉壁书记携诸公诗卷索语","f":"七言律诗","c":["草思含芳梦亦疑，芬陁擢秀自枝枝。","人间万事醉眯眼，江上数峰青到眉。","多暇湖山分昼永，少晴风日共春迟。","一春幽事从头了，先破苍苔吊紫芝。"]},{"t":"和寒泉春日儿童三咏 其一 竹马","f":"七言绝句","c":["争跨迎侯彩竹新，相呼回策巧如萦。","一鞭看是谁先著，稚子群中觅祖生。"]},{"t":"和寒泉春日儿童三咏 其二 风筝","f":"七言绝句","c":["纵轮不卷只嫌低，高处安知鹢退飞。","弱缕不禁儿辈掣，断鸢弗下断云归。"]},{"t":"和寒泉春日儿童三咏 其三 乌?角","f":"词","c":["煖响乌?二月初，调高不作小单于。","年年陌上儿童戏，嚼徵含商尽不如。"]},{"t":"酬寒泉牡丹","f":"七言律诗","c":["见说姚家与魏家，紫琼黄玉剪纷葩。","亭亭贵重推名辈，岁岁清明赏大花。","日褪晓晴连影好，露添夜冷并枝斜。","一从娄舞霓裳遍，憔悴春风怨物华。"]},{"t":"上巳日","f":"七言律诗","c":["龙飞乙酉三三日，节物催春睡不知。","便作花残莺老态，略无天朗气清时。","丽人行欠高吟续，禊帖碑从赝本欺。","逸兴不随今古尽，振衣千仞赴心期。"]},{"t":"柳絮","f":"七言律诗","c":["满城漠漠看飞扬，百鍊刚非贺老肠。","褪雨不忺知酝藉，倚风无力信行藏。","可曾著意随流急，竟亦何心作许狂。","酒似海留春不住，为春回雪荐离觞。"]},{"t":"杯中鱼子","f":"七言律诗","c":["眇如丝粟便悠然，洼玉深中浅注泉。","再晕不知前夜月，才生便乐此中天。","群分自笑如儿戏，聚育谁偏得母怜。","罔罟不来斯可乐，洋洋何必泳长川。"]},{"t":"悼陆秘读","f":"七言律诗","c":["诸老骑箕上太微，仲谋不似景升儿。","废寻蹊隧千年古，光奋胸襟一段奇。","直敢昧寻嗟枉尺，方宁适义不成规。","泠然差早终无愧，安俟名垂竹帛为。"]},{"t":"三贤堂","f":"七言律诗","c":["弹压风烟盍鼎分，一新丹碧耀层层。","异时三凤鸣还止，旧约群鸥唤得应。","船绕砌云寻水步，葑侵檐影似田塍。","关心夜老梅花瘦，别有孤山树上僧。"]},{"t":"题焕少章墨菊","f":"七言绝句","c":["采薇不疗餐英瘦，著眼无从到朵颐。","秋露染毫馀晓馥，便成画饼亦忘饥。"]},{"t":"谢疏寮高秘书同常博王省元见过 其一","f":"五言律诗","c":["友生朱与葛，月旦说疏寮。","老锡思投越，春江梦趁潮。","句新哦易熟，灯喜剪难消。","闻道搴旗鼓，山林不寂寥。"]},{"t":"谢疏寮高秘书同常博王省元见过 其二","f":"五言律诗","c":["不纵青云步，行间著得么。","官居最华要，吟似老头陁。","行辈今差少，声名早厌多。","犹将三万轴，清夜答弦歌。"]},{"t":"刀镊工","f":"七言律诗","c":["弹镊何曾款俗扃，清晨且了夜来经。","匣非台镜人谁鉴，阅少年头雪易零。","老葛句留身后贵，颠僧发烬死前灵。","白崖薙罢还来薙，饶得长安两独醒。"]},{"t":"卢玉堂枯木怪石","f":"五言律诗","c":["礧砢不坡陁，非才谢伐柯。","相看如我瘦，想见阅人多。","誉笑丹青俗，工如水墨何。","经营盘礴际，天地困搜罗。"]},{"t":"十四夜竹间对月客有说丹霞张郡博已还豫章","f":"七言律诗","c":["华玉初痕陇树颠，朣朣俄顷散澄鲜。","已无纤翳净如洗，犹有些儿修未全。","竺友啸闻青嶂外，胡床移近绿筠边。","怀人长恨千山隔，云淡天低鹤未眠。"]},{"t":"定平怀墨梅","f":"五言律诗","c":["南昌梅少府，人道是梅仙。","不疗疏枝瘦，安知坏色妍。","春归天上去，真自镜中传。","同出吟机杼，无声亦自贤。"]},{"t":"次周和州韵 其一","f":"五言律诗","c":["绿水绕园庐，花无一日虚。","柳桥闲研席，竹屿小篮舆。","恶草防滋蔓，新篁戒剪梳。","不堪奇字累，酬接费分疏。"]},{"t":"次周和州韵 其二","f":"五言律诗","c":["抔土铭骐骏，诙如柳子骚。","涤新藏缺研，悯旧惜残毫。","射石惩年少，闻鸡仄枕高。","云低鸿翼远，弋者不偿劳。"]},{"t":"图翁瓜圃出故淮东使者方诗境所藏杨补之三友","f":"五言律诗","c":["画寿诗中境，人修地下文。","金兰三友合，泾渭两边分。","冻壑层攲盖，炎天独欠君。","莫嫌疏影瘦，及与欠清芬。"]},{"t":"落日汎舟拉赵寒泉刘成道","f":"七言绝句","c":["雨添湖满绿浮堤，高柳摇青接葑低。","觅得晚凉船便住，背斜阳处听蝉嘶。"]},{"t":"送洁老归碧云新居","f":"七言律诗","c":["小小如巢便称怀，邻无百万买洪崖。","炊云子熟呼仙饷，借雪精游与俗乖。","禅谬分灯传口耳，耕宁合耦外形骸。","田中大义休提掇，定与诸方打不谐。"]},{"t":"宋兄安卿墨梅","f":"七言绝句","c":["清婉浑非铁石姿，故家别调合传衣。","华风不疗春痕瘦，可是工夫不造微。"]},{"t":"凤泉初月","f":"七言绝句","c":["一痕隐隐介亭西，庾亮楼头未醉时。","多是团团深夜看，可曾见此巧如眉。"]},{"t":"临安长官赵两山约观将军木石镜玲珑水净土寺 其一","f":"七言绝句","c":["逐鹿区区百战酣，道边谁掩大夫惭。","锦山锦野幽寻地，独对将军忆召南。"]},{"t":"临安长官赵两山约观将军木石镜玲珑水净土寺 其二","f":"七言绝句","c":["坚中素蕴独晶晶，异质潜分付目成。","泐尽烧痕犹反照，菱花多是用常明。"]},{"t":"临安长官赵两山约观将军木石镜玲珑水净土寺 其三","f":"七言绝句","c":["断崖飞磴遍题名，刻尽玲珑老石英。","欲写苔痕酬胜践，偶然天籁不曾鸣。"]},{"t":"临安长官赵两山约观将军木石镜玲珑水净土寺 其四","f":"七言绝句","c":["觳觫何如款段骑，袜头番著副絇丝。","胸中天地无人识，只有桥边白鹭鸶。"]},{"t":"威德方丈桂著花长官赵两山相过","f":"五言律诗","c":["举子忙时节，秋庭桂子春。","暂分餐菊伴，来款种花人。","密影窥檐小，繁英趁月新。","发硎盘错外，树下看修轮。"]},{"t":"临安长官号两山","f":"七言律诗","c":["小筑难谋似燕营，卷帘容燕贺新成。","绿抽万玉医人俗，青出双螺闯户明。","家与宦贫宁免仕，猿教鹤伴不须惊。","紫荆花下庭萱老，浊酒狂歌燕弟兄。"]},{"t":"云天瑞所藏李唐风雨图","f":"词","c":["炮车卷东南，白昼沙石昏。","悠然隘西北，顷刻潭湫翻。","晴窗展李画，叆叇迷江村。","乃知笔有神，巧剔造物根。","信意泼浓墨，了不见墨痕。","但见平林黯黯木欲折，辊底怒浪掀天浑。","平地十步九蹉跌，奈此倚岸舟如盆。","得非折天柱，恐是颠昆崙。","不然于菟髑髅下，巨浸潜蛟勇斗涛山崩。","空江冥冥不知晓，更无一个闲鸥鸟。","断岸微茫水亭小，三两重茅都卷了。","漓洒云阴阴，翻然如惜金。","西子宜浅妆，浓抹尤清深。","于戏此妙不可寻，百金一笔不足临，掩卷袖手空沉吟。"]},{"t":"送侍左秘书高疏寮得处州 其一","f":"五言律诗","c":["一水分吴越，幽思可得分。","软红援汩汩，坚白扫纭纭。","富卷投囊草，芳馀辟蠹芸。","傍池双宿鹭，留得水边云。"]},{"t":"送侍左秘书高疏寮得处州 其二","f":"五言律诗","c":["诗人去作州，需次小迟留。","风物忺题品，江山怕搅搜。","竹凉深处榻，荈酽醉时瓯。","见说三岩好，因书话胜游。"]},{"t":"送宋左曹得温州 其一","f":"五言律诗","c":["翁居藩辅久，叔年又相先。","万石不足数，一灯无别传。","家声青琐闼，风味赤城仙。","好是猿啼处，霞标最近天。"]},{"t":"送宋左曹得温州 其二","f":"五言律诗","c":["数峰江上青，宜雨亦宜晴。","著意画难就，助人吟易成。","县官怀近郡，郎署暂专城。","况是烹鲜手，襦歌屡有声。"]},{"t":"寄安抚曹观使 其一","f":"五言律诗","c":["君子不宜闲，闲中有节文。","检方医竹瘦，图蔓发兰薰。","见说新添鹤，频留欲去云。","应无浮俗事，嘈杂玷清闻。"]},{"t":"寄安抚曹观使 其二","f":"五言律诗","c":["筼筜抱节癯，风味似楼居。","自是宦情薄，容教杯酒疏。","扫除新筑室，收拾旧观书。","何必陶元亮，斜阳自荷锄。"]},{"t":"孤山彭高士借榻","f":"七言绝句","c":["万籁笙镛一枕秋，幌云垂地月痕收。","偶然做得还乡梦，梦见鸿濛与道游。"]},{"t":"月渚","f":"五言律诗","c":["秀色老千岩，窗虚小郁蓝。","水明收晚照，沙暝展晴岚。","野饷隐沦共，清游名胜谈。","中秋无好友，举酒便成三。"]},{"t":"寄福州李伯达","f":"七言律诗","c":["江汉归来重访寻，貂裘未弊亦尘侵。","碧眸憎俗重扃户，白羽扇凉一援琴。","池草易生苕水梦，莼羹难老故乡心。","有书若问东阳瘦，记遣神林问惠琳。"]},{"t":"辉船窗见过","f":"七言律诗","c":["北宕戒坛才税驾，过湖问路扣吾庐。","棹侵葑畛轻于叶，策尽松阴缓当车。","图上众香和露写，袖中经卷杀金书。","飞来更践重来约，莫遣山灵讶阔疏。"]},{"t":"送魏贰卿之静州","f":"七言律诗","c":["一其所二一成非，揆以人情萃必睽。","镜岂有心私应物，楚如不众敢咻齐。","瘦攲雪萼难谐俗，劲错霜根弗肯低。","岣嵝芳尘犹可袭，剩收赤箭就刀圭。"]},{"t":"春柳睡鹊鸲鹆图","f":"七言绝句","c":["曲尘缕缕鹊深栖，写出章台二月时。","幽响不知何处喜，一声鸲鹆圣先知。"]},{"t":"破山高僧塔","f":"五言律诗","c":["寺倚四僧传，僧今已蜕蝉。","塔随蓁棘老，德与苾刍全。","翠滴添衣重，云低染屦鲜。","何年山脊断，飞去玉蜿蜒。"]},{"t":"破山璎珞桧","f":"五言律诗","c":["雪枝新纵纵，霜子旧玲玲。","漙露烦添缀，萦风缓剪零。","贯珠烦蚁度，编贝倩谁经。","瑶草随山尽，来寻千岁苓。"]},{"t":"酬赵西里游虎丘 其一","f":"五言律诗","c":["相携上郁峨，舟似叶随波。","寺压秋痕瘦，云沉古迹多。","远舒高处望，清递隔船歌。","尽写吴中胜，新吟细濯磨。"]},{"t":"酬赵西里游虎丘 其二","f":"五言律诗","c":["曾说剑池游，风烟入校雠。","台孤头点石，窞迥趾翻鳅。","彩鹢山前棹，青鸾水上楼。","暮关须小待，款曲尽觥筹。"]},{"t":"蠡口","f":"七言律诗","c":["未谋人国已谋身，往事无从问水滨。","游鹿谆谆犹在耳，平湖淼淼忽扬尘。","寺明丹垩低檐古，树饱风霜老节新。","又理阖闾城外棹，更无鸥鸟傍青纶。"]},{"t":"枫桥酬张季思","f":"七言律诗","c":["欲唤扁舟一访寻，开窗同揖小猊岑。","风晴堕叶声应燥，目远孤鸿影易沉。","餐为菊英聊缓带，醉因雪萼小低簪。","隔溪半夜疏钟到，定有清新入短吟。"]},{"t":"分题画策得山茶","f":"七言绝句","c":["绿枝丹叶未春回，生色潜随采笔开。","欲伴高文归大册，道山延阁小蓬莱。"]},{"t":"寄三衢使君赵寺丞","f":"七言律诗","c":["刺史天开卷暝云，凛姿如玉照人明。","蓬莱地近异尘世，箕颍风高凝古情。","度外峻超千文俗，春来又劝一年耕。","屏藩王室皆同姓，况是金瓯覆姓名。"]},{"t":"续赋祥鉴义梅花","f":"五言古诗","c":["香国开楼居，桃李合戍边。","移根赏奇怪，屡舞却锦缠。","静闻竺友吟，粲若春雪妍。","暗馥腾鹤膝，苍藓腥蜗涎。","既明红紫伦，更秉薰莸权。","垄树寒自零，苑柳暖自眠。","逶蛇木兰后，揖逊凌波前。","凌波不忍去，步月时蹁跹。"]},{"t":"复老归东嘉予亦治还蜀之装赋别湖上","f":"五言古诗","c":["华风不常煖，华月岂常曜。","泠泠弗鸣条，囧囧自反照。","野马空眯目，爝火谩腾耀。","谁结萤囊口，寒原并秋烧。","谁枵土囊腹，夜壑哀万窍。","向迩虽暂热，凭力亦易悄。","悠然付静胜，了不直一笑。","山林隐君子，浮俗固殊调。","华风起蘋末，华月挂林表。","既安云霾妒，畴忍尘杂扰。","角叹一麟足，鹗洗百鸷少。","弱水三万里，蓬莱眼中小。","况夫左传癖，举世不足乐。","亦复烟霞痼，沉绵颇相肖。","云胡去留柄，坐困佞壬袅。","挥手从此别，掉头莫回眺。","爱惜双眉厖，脱略万事了。","龙翔解悬榻，雁宕拓吟徼。","摩挲送鸿目，掷弃连鳌钓。","云来寄心思，临风一长啸。"]},{"t":"书六一居士归田图","f":"七言绝句","c":["赋田中乐驾言归，勇决如何得似诗。","诗后退之盘谷序，画成犹是未归时。"]},{"t":"孤山后","f":"七言绝句","c":["采鹢浮春皓齿歌，延祥观后晚偏多。","可无人物如张绪，只是垂杨不似他。"]},{"t":"石林诸孙叶子云左手法二王逸迹不下右手","f":"五言古诗","c":["桐轩法钟王，人鲜出其右。","出奇左运腕，亦复龙蛇走。","悠然伸劲画，壮甚紫铁钮。","番然变道古，古藤瘦牵纠。","轻墨蔓如缕，大者大如斗。","故家翰墨场，有此擅场手。","星星满青镜，入眼未始有。","四支同一初，视听有常守。","执捉与践履，造次各先后。","云何互其用，落落便相偶。","犹来幽人心，囧囧净不垢。","衡从一机透，众妙俱辐辏。","逢原盖自得，左右均去取。","枝叶随根本，股肱副元首。","一身小天地，默窥元化母。"]},{"t":"卢次夔下第","f":"五言律诗","c":["得失见君心，令人恨满膺。","诸贤品华玉，四字独苍蝇。","留取搀前步，来居向上层。","趁将春未去，载酒啸吟明。"]},{"t":"杜鹃","f":"七言绝句","c":["旧草堂东水竹西，年年只与落花期。","长亭今夜声连晓，愁似经年病拾遗。"]},{"t":"横翠阁","f":"五言律诗","c":["阑干曲曲西，待得夕阳迟。","展画真成赘，无诗却不宜。","鸿虽供晚眺，月欠扫新眉。","安得泠然御，来观烟雨时。"]},{"t":"太守陈中书问彰教近况","f":"五言古诗","c":["徐君旧剪茅，小小亦堪巢。","野客便招隐，闲情赋解嘲。","村疏难得友，葵熟易为庖。","鼓吹分蛙部，琅玕长竹梢。","瘦寻残火种，冗剔故书抄。","北崦虽移檄，西湖未绝交。","贫优宁似负，推固不如敲。","自审如衡石，谁能较斗筲。","曲池风力皱，缺甃藓文凹。","曾枉行春旆，芳题满近郊。"]},{"t":"陪陈中书游两仙堂","f":"五言古诗","c":["透云两鸿鹄，何年忽卑飞。","指爪泥上留，弗与岁月移。","大声疾璆琳，万窍不敢嘶。","琅然答空山，玲然震清溪。","俯仰半千载，日日春菲菲。","绪馀及草木，草木竟莫知。","坐令万金产，不直五字奇。","江左数六谢，选中辄见推。","清新辈阿连，亦岂愧客儿。","开元天宝间，有客偿心期。","玉颓沈香北，健笔挥珠玑。","天威不可夺，人爵不可縻。","此邦非故乡，每至辄倦归。","楼居寄逸想，更较先后为。","有美池上仙，凛凛岩壑姿。","辙飞两公后，惄若饥渴思。","作堂肖公像，叠嶂双溪西。","幻出天上人，对峙玉羽衣。","乾坤浩荡春，盎盎在两眉。","清冰照人冷，恍如吟啸时。","泠泠气欲仙，拟絷游龙骑。","世隘乌足容，才大不得施。","至今骚雅流，临风挥涕洏。"]},{"t":"淡墨水仙栀子 其一","f":"七言绝句","c":["烁石流金记曝根，古壶疏插煮泉温。","翠扶柔玉春无力，独与华风伴月痕。"]},{"t":"淡墨水仙栀子 其二","f":"七言绝句","c":["六萼敷腴透玉明，六柧垂实趁秋零。","众香酝藉须弹压，笑挽凌波赋鹡鸰。"]},{"t":"陈紫微赴召 其一","f":"七言律诗","c":["帝辍词臣重抚绥，次边尤轸大江陲。","百篇斗酒玩万物，十雨五风终四期。","谣颂不遗纤悉美，形容难尽许多奇。","纵龟放鹤朝天去，岂独江东列郡师。"]},{"t":"陈紫微赴召 其二","f":"七言律诗","c":["苦心如檗凛于冰，赢得冲冠雪一簪。","千载四明登陆处，三生五月度泸心。","清泠烈暑生秋思，谐协凉薰入正音。","今日惮公如惮黯，试看塞柝夜沈沈。"]},{"t":"陪陈紫微麻姑观","f":"七言绝句","c":["不惮朱砂九转迟，绝怜岣嵝令君痴。","一抔幻出新舂玉，更听人言狡狯为。"]},{"t":"题粲侄岘山秋晚","f":"七言绝句","c":["分明写出岘山诗，陇树初寒晚照低。","掩卷只思人堕泪，不思量到白铜鞮。"]},{"t":"续当涂别驾林率庵赋谪仙李翰林","f":"五言古诗","c":["龊龊复龊龊，未死如未生。","公去月明在，留得青山茔。","青山倚公高，屹立千载英。","翠巘拓吟垒，飞瀑按酒兵。","行客一仰止，折几鄙吝萌。","狂歌长短吟，迈古日月明。","俊逸兼鲍谢，丽则侪云卿。","骅骝博艳姬，土苴群方兄。","节峻玄霜严，义重紫禁轻。","酹土土长燥，雷魁何由平。","生男禁多才，此话闻阿庚。","真才弃如土，大厦谁支倾。","不用谢安石，大雅空垂名。"]},{"t":"送赵丞","f":"七言律诗","c":["归装又逐西凉去，轻省还如赴上时。","廉者固宜疏住计，富哉只有送行诗。","贴天自与鹓鸿举，钳纸谁容雁鹜欺。","它日宣城厅壁记，岿然一样斗山思。"]},{"t":"三角亭","f":"五言律诗","c":["成规与俗殊，鼎足外无馀。","曲是从前恶，圆非近日疏。","神山分槛小，槐影直檐虚。","要识其中趣，明明举一隅。"]},{"t":"忆水芙蓉木芙蓉寄西湖诸友 其一","f":"七言绝句","c":["竹凉池馆绿荷风，同看吴宫小队红。","少却乱红深处棹，西陵桥北断桥东。"]},{"t":"忆水芙蓉木芙蓉寄西湖诸友 其二","f":"七言绝句","c":["花满秋城闯水明，镜中滴露掌中零。","曾雠新咏游花下，写寄城中石与丁。"]},{"t":"次韵林别驾 其一","f":"五言律诗","c":["官分长贰荣，乐事胜专城。","避俗如僧定，寻仙结伴行。","吟疆宽处拓，醉玉醒时倾。","拟叶埙篪响，邯郸步不成。"]},{"t":"次韵林别驾 其二","f":"五言律诗","c":["往住溪头寺，曾陪太一舟。","港收天影缩，桥碍浦云流。","练石声声月，丹枫片片秋。","砌蛩添苦思，吟动瀼西愁。"]},{"t":"次韵谢学士","f":"七言律诗","c":["凛姿行复伟衣冠，螭亦何曾耻暂蟠。","入梦少曾忘博约，得书多是报平安。","雪零短发新尤甚，盟近黄花旧不寒。","肯入乱山相劳苦，密云香郁破团团。"]},{"t":"对菊寄王常博","f":"词","c":["鲜风嫩日养芳新，来会闲人九日盟。","相泽畔吟腾晓馥，就花中隐著脩名。","碧浮剩嗅茱萸醁，黄落谁摇沆瀣英。","商素雅为仁者寿，荐甘?碧辅清明。"]},{"t":"题张雪湖吴山煖暧","f":"七言绝句","c":["山藏晻霭树藏云，十驾难追欲去春。","鳞砌古愁千万绪，因君开卷又重新。"]},{"t":"次韵玉堂卢蒲江省中木犀","f":"七言律诗","c":["一种分蟾各自知，人间不似省中枝。","繁英尽委开仍好，幽馥先来去又迟。","雨后莫忘秋晓步，风鲜曾约夜凉吹。","小山纵有淮南赋，可是蓬山欠景差。"]},{"t":"卢蒲江雪夜约同直省中出示采菊读书煎茶种橘四诗索危秘书诸名胜同赋 其一","f":"七言绝句","c":["拙须务速巧须迟，尽巧依稀与拙宜。","除却艺兰纫楚佩，反骚只有落英诗。"]},{"t":"卢蒲江雪夜约同直省中出示采菊读书煎茶种橘四诗索危秘书诸名胜同赋 其二","f":"七言绝句","c":["糁葵负腹愧便便，偶上蓬莱借榻眠。","梦过子云还问字，梦醒龙液冷无烟。"]},{"t":"卢蒲江雪夜约同直省中出示采菊读书煎茶种橘四诗索危秘书诸名胜同赋 其三","f":"七言绝句","c":["亭亭古砌剪霜苔，密琐疏棂冷不开。","纱帽笼头防俗客，小团新锡上方来。"]},{"t":"卢蒲江雪夜约同直省中出示采菊读书煎茶种橘四诗索危秘书诸名胜同赋 其四","f":"七言绝句","c":["青压低枝欲破香，秋迟风燥未曾霜。","枳蕃江北令人笑，更试仙山与道乡。"]},{"t":"闻雪湖张签判讣","f":"词","c":["嘉兴陆长官，遗我尺素书。","报云钧天诏九地，夺我好友张雪湖。","雪湖翩翩上天去，下视尘滓知何如。","因依未去时，泠然山泽癯。","万象困搜搅，撚断苍髯须。","十年不调闭户居，铁石不受烟火腴，辟俗如辟豕负涂。","后来稍稍低簪裾，百步掩鼻犹反趋。","官高金多娇妻奴，蠛蠓乱眼才斯须。","填门只有长者车，北海尊酒无时无，明朝一饭欠宿储。","印泥指爪嗟鸿鹄，精明定化为兰菊。","纫称骚人陆离佩，英泛绿尊浇魁雷。","骚人之腹秋蝉清，吐芳腾馥日日新。","纷纷郁郁仍轮囷，散为天地无边春。"]},{"t":"吴提干之官浙东","f":"五言律诗","c":["叔季振华裾，晶晶照上都。","对床风送雨，隔岸越分吴。","池草冰澌煖，庭萱玉色腴。","綵帆飞晓镜，拂拭贺家湖。"]},{"t":"吴状元赴阙属陈兼佥催送行语","f":"七言律诗","c":["细把前朝圣政推，娄教龙首到黄扉。","自南渡后从头数，比旧京时过眼稀。","磊砢固当为世用，风云端不与人违。","采薇只在丁山下，亟伫青鸾入翠微。"]},{"t":"立秋前一日蛩响","f":"七言绝句","c":["火孕金英眇未抽，学吟先报短檠秋。","傍窗袅袅清如缕，明日西风一样愁。"]},{"t":"宁国奉圣寺有许浑旧题","f":"五言律诗","c":["题擅玉台宾，山名益著闻。","禽珍腾逸响，草异荐奇芬。","壁可曾留锡，檐栖欲去云。","尘嚣避三舍，不度碧溪濆。"]},{"t":"次复斋奚左藏补陁岩寺韵寺有象鼻岩渴霓皆佳致","f":"七言律诗","c":["当年聚石赋全提，断处飞梁险处梯。","铁展霓腰疑水竭，玉伸象准卷云低。","危于汉使回车坂，深似秦人避乱溪。","钟梵殷床连夜旦，相忘猿鸟各安栖。"]},{"t":"石如虹至水际余名之曰渴霓","f":"七言绝句","c":["直舒千尺怒谽谺，高贴云根枕水涯。","水竭欲飞仍小住，砰轰欲跨阿香车。"]},{"t":"复斋坟前左顾石龟","f":"七言绝句","c":["宽罾密罔断江流，好在云藏莫浪游。","我欲黄金如斗大，斩新左顾铸馀不。"]},{"t":"清隐寺乳泉","f":"七言绝句","c":["脉通九地各东西，洗钵曾分牧女糜。","万斛从来不择地，试看一滴汎华池。"]},{"t":"仁寿堂","f":"七言绝句","c":["阔开荡荡城中天，朝菌灵椿总大年。","凿井耕田皆帝力，不知谁党复谁偏。"]},{"t":"奉圣寺江阁","f":"七言绝句","c":["散衣江阁抚疏檐，吹彻西凉已属餍。","得陇未终还望蜀，半规更待月纤纤。"]},{"t":"隐山","f":"七言绝句","c":["小岭明明属小支，傍山论价与山违。","巢由去后箕山老，夜夜天云隐少微。"]},{"t":"酬当涂何户曹畏斋金陵三篇见寄兼柬饷台上幕许从道 其一","f":"七言律诗","c":["山木凌秋似鬓苍，静观浮俗饱炎凉。","唤回猿鹤弹三叠，话到陈隋笑几场。","云度闲情疑路断，草生奇馥染林香。","莫乘残照催归骑，白下留门惯漏长。"]},{"t":"酬当涂何户曹畏斋金陵三篇见寄兼柬饷台上幕许从道 其二","f":"七言律诗","c":["笔耕白首不逢年，间得新题似得仙。","磨透铁泓空费力，吟残金薤弗成篇。","未忘陋巷希瞠若，不信长虹死浩然。","小驻行云聊寄恨，莫为愁雨湿吴天。"]},{"t":"酬当涂何户曹畏斋金陵三篇见寄兼柬饷台上幕许从道 其三","f":"七言律诗","c":["松根葛藟亟扳缘，势极青冥恨不前。","莺閟好音春不响，鹤嫌遗臭夜移眠。","回头华表一千载，开眼檀萝十九年。","想见息阴羞恶木，断魂岭海吊诸贤。"]},{"t":"克己斋","f":"五言律诗","c":["罔念圣为狂，医狂亦有方。","正逵遵稳审，私孽殄微茫。","蜕俗嗟封壳，耘心破畛疆。","它山石攻玉，日用细平章。"]}]};